window.VOCES={"autores":[{"s":"seneca","n":"Séneca","r":"/recursos/voces-que-nos-habitan/autores/seneca/","y":"c. 4 a. C.–65","e":"fil","en":"Filosofía","p":"clasico","d":["Filosofía","Ética"]},{"s":"marco-aurelio","n":"Marco Aurelio","r":"/recursos/voces-que-nos-habitan/autores/marco-aurelio/","y":"121–180","e":"fil","en":"Filosofía","p":"clasico","d":["Filosofía","Ética"]},{"s":"sigmund-freud","n":"Sigmund Freud","r":"/recursos/voces-que-nos-habitan/autores/sigmund-freud/","y":"1856–1939","e":"pa","en":"Psicoanálisis","p":"moderno","d":["Psicoanálisis","Medicina","Psicología"]},{"s":"william-james","n":"William James","r":"/recursos/voces-que-nos-habitan/autores/william-james/","y":"1842–1910","e":"ini","en":"Los comienzos","p":"moderno","d":["Psicología","Filosofía","Medicina"]},{"s":"alfred-adler","n":"Alfred Adler","r":"/recursos/voces-que-nos-habitan/autores/alfred-adler/","y":"1870–1937","e":"pa","en":"Psicoanálisis","p":"moderno","d":["Psicología","Medicina","Psiquiatría"]},{"s":"platon","n":"Platón","r":"/recursos/voces-que-nos-habitan/autores/platon/","y":"c. 428–348 a. C.","e":"fil","en":"Filosofía","p":"clasico","d":["Filosofía"]},{"s":"aristoteles","n":"Aristóteles","r":"/recursos/voces-que-nos-habitan/autores/aristoteles/","y":"384–322 a. C.","e":"fil","en":"Filosofía","p":"clasico","d":["Filosofía","Ciencias naturales"]},{"s":"epicteto","n":"Epicteto","r":"/recursos/voces-que-nos-habitan/autores/epicteto/","y":"c. 50–135","e":"fil","en":"Filosofía","p":"clasico","d":["Filosofía","Ética"]},{"s":"baruch-spinoza","n":"Baruch Spinoza","r":"/recursos/voces-que-nos-habitan/autores/baruch-spinoza/","y":"1632–1677","e":"fil","en":"Filosofía","p":"moderno","d":["Filosofía"]},{"s":"immanuel-kant","n":"Immanuel Kant","r":"/recursos/voces-que-nos-habitan/autores/immanuel-kant/","y":"1724–1804","e":"fil","en":"Filosofía","p":"moderno","d":["Filosofía"]},{"s":"arthur-schopenhauer","n":"Arthur Schopenhauer","r":"/recursos/voces-que-nos-habitan/autores/arthur-schopenhauer/","y":"1788–1860","e":"fil","en":"Filosofía","p":"moderno","d":["Filosofía"]},{"s":"friedrich-nietzsche","n":"Friedrich Nietzsche","r":"/recursos/voces-que-nos-habitan/autores/friedrich-nietzsche/","y":"1844–1900","e":"fil","en":"Filosofía","p":"moderno","d":["Filosofía","Filología"]},{"s":"rene-descartes","n":"René Descartes","r":"/recursos/voces-que-nos-habitan/autores/rene-descartes/","y":"1596–1650","e":"fil","en":"Filosofía","p":"moderno","d":["Filosofía","Matemáticas","Ciencias naturales"]},{"s":"john-locke","n":"John Locke","r":"/recursos/voces-que-nos-habitan/autores/john-locke/","y":"1632–1704","e":"fil","en":"Filosofía","p":"moderno","d":["Filosofía","Medicina","Política"]},{"s":"buda","n":"Buda","r":"/recursos/voces-que-nos-habitan/autores/buda/","y":"s. VI–IV a. C.","e":"ori","en":"Tradiciones orientales","p":"clasico","d":["Espiritualidad","Filosofía"]},{"s":"lao-tse","n":"Lao-tse","r":"/recursos/voces-que-nos-habitan/autores/lao-tse/","y":"fechas inciertas","e":"ori","en":"Tradiciones orientales","p":"clasico","d":["Filosofía","Espiritualidad"]}],"temas":{"vinculos":["Vínculos",true],"emociones":["Emociones",true],"identidad":["Identidad",true],"deseo":["Deseo",true],"conocimiento":["Conocimiento",true],"felicidad":["Felicidad",true],"habitos":["Hábitos",true],"autoestima":["Autoestima",true],"responsabilidad":["Responsabilidad",true],"autoconocimiento":["Autoconocimiento",true],"conciencia":["Conciencia",true],"libertad":["Libertad",true],"aceptacion":["Aceptación",true],"ira":["Ira y agresión",true],"sociedad":["Sociedad",true],"amor":["Amor",true],"sufrimiento":["Sufrimiento",true],"regulacion-emocional":["Regulación emocional",true],"miedo":["Miedo",true],"autenticidad":["Autenticidad",true],"sentido-de-vida":["Sentido de la vida",true],"cambio":["Cambio",true],"resiliencia":["Resiliencia",true],"muerte":["La muerte",true],"tiempo":["El tiempo",true],"educacion":["Aprender y enseñar",true],"verdad":["La verdad",true],"infancia":["Infancia",true],"cuerpo":["El cuerpo",true],"amistad":["Amistad",true],"inconsciente":["Lo inconsciente",true],"presencia":["Presencia",true],"atencion":["Atención",true],"trascendencia":["Trascendencia",true],"compasion":["Compasión",true],"alegria":["Alegría",true],"transformacion-personal":["Transformación personal",true],"poder":["Poder",true],"angustia":["Angustia",true],"desarrollo-humano":["Desarrollo humano",true],"existencia":["Existencia",true],"soledad":["Soledad",true],"comunicacion":["Comunicación",true],"incertidumbre":["Incertidumbre",true],"trabajo":["Trabajo",true],"cultura":["Cultura",true],"esperanza":["Esperanza",true],"salud-mental":["Salud mental",true],"silencio":["Silencio",true],"naturaleza":["Naturaleza",true],"voluntad":["Voluntad",true],"culpa":["Culpa",true],"creatividad":["Creatividad",true],"terapia":["Terapia",true],"memoria":["Memoria",true],"encuentro":["El encuentro",true],"duelo":["Duelo",true],"perdida":["Pérdida",false],"humor":["Humor",false],"tristeza":["Tristeza",false],"gratitud":["Gratitud",false],"familia":["Familia",false],"repeticion":["Repetición",false],"tecnologia":["Tecnología",false],"suenos":["Sueños",false],"empatia":["Empatía",false],"conexion":["Conexión",false],"trauma":["Trauma",false]},"citas":[{"i":"seneca-001","a":"seneca","t":"Hacelo así, querido Lucilio: reclamate para vos mismo.","o":"Ita fac, mi Lucili: vindica te tibi","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 1, 1","te":["autoconocimiento","libertad","tiempo"]},{"i":"seneca-002","a":"seneca","t":"Una gran parte de la vida se escapa haciendo mal, la mayor parte sin hacer nada, y la vida entera haciendo otra cosa.","o":"magna pars vitae elabitur male agentibus, maxima nihil agentibus, tota vita aliud agentibus","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 1, 1","te":["tiempo","sentido-de-vida"]},{"i":"seneca-003","a":"seneca","t":"¿A quién podrás mostrarme que le dé algún valor al tiempo, que aprecie cada día, que entienda que muere cada día?","o":"Quem mihi dabis qui aliquod pretium tempori ponat, qui diem aestimet, qui intellegat se cotidie mori?","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 1, 2","te":["tiempo","muerte"]},{"i":"seneca-004","a":"seneca","t":"Todo el tiempo que quedó atrás ya lo tiene la muerte.","o":"quidquid aetatis retro est mors tenet","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 1, 2","te":["tiempo","muerte"]},{"i":"seneca-005","a":"seneca","t":"Mientras se la posterga, la vida pasa.","o":"Dum differtur vita transcurrit.","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 1, 3","te":["tiempo","cambio"]},{"i":"seneca-006","a":"seneca","t":"Todo, Lucilio, es ajeno: solo el tiempo es nuestro.","o":"Omnia, Lucili, aliena sunt, tempus tantum nostrum est","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 1, 3","te":["tiempo","libertad"]},{"i":"seneca-007","a":"seneca","t":"No está en ninguna parte quien está en todas.","o":"Nusquam est qui ubique est.","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 2, 2","te":["presencia","atencion"]},{"i":"seneca-008","a":"seneca","t":"No es pobre quien tiene poco, sino quien desea más.","o":"non qui parum habet, sed qui plus cupit, pauper est","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 2, 6","te":["deseo","felicidad"]},{"i":"seneca-009","a":"seneca","t":"Deliberá todo con tu amigo, pero antes deliberá sobre él.","o":"Tu vero omnia cum amico delibera, sed de ipso prius","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 3, 2","te":["amistad","vinculos"]},{"i":"seneca-010","a":"seneca","t":"Las dos cosas son un error: confiar en todos y no confiar en nadie.","o":"utrumque enim vitium est, et omnibus credere et nulli","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 3, 4","te":["vinculos","amistad"]},{"i":"seneca-011","a":"seneca","t":"Ningún bien se disfruta si no se lo comparte.","o":"nullius boni sine socio iucunda possessio est","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 6, 4","te":["amistad","alegria","encuentro"]},{"i":"seneca-012","a":"seneca","t":"Más te servirán la voz viva y la convivencia que los discursos.","o":"Plus tamen tibi et viva vox et convictus quam oratio proderit","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 6, 5","te":["encuentro","educacion"]},{"i":"seneca-013","a":"seneca","t":"Retirate en vos mismo cuanto puedas; tratá con quienes te harán mejor y recibí a quienes vos podés hacer mejores.","o":"Recede in te ipse quantum potes; cum his versare qui te meliorem facturi sunt, illos admitte quos tu potes facere meliores.","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 7, 8","te":["vinculos","autoconocimiento","transformacion-personal"]},{"i":"seneca-014","a":"seneca","t":"Esto es recíproco: los seres humanos, mientras enseñan, aprenden.","o":"Mutuo ista fiunt, et homines dum docent discunt.","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 7, 8","te":["educacion","encuentro"]},{"i":"seneca-015","a":"seneca","t":"Para tener por quién morir, para tener a quién seguir al exilio. (Respuesta a “¿para qué buscás un amigo?”)","o":"Ut habeam pro quo mori possim, ut habeam quem in exsilium sequar","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 9, 10","te":["amistad","amor"]},{"i":"seneca-016","a":"seneca","t":"Son más, Lucilio, las cosas que nos asustan que las que nos aplastan, y sufrimos más a menudo por la opinión que por la realidad.","o":"Plura sunt, Lucili, quae nos terrent quam quae premunt, et saepius opinione quam re laboramus.","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 13, 4","te":["miedo","sufrimiento","angustia"]},{"i":"seneca-017","a":"seneca","t":"Algunas cosas nos atormentan más de lo que deberían, otras antes de lo que deberían, y otras cuando no deberían atormentarnos en absoluto.","o":"Quaedam ergo nos magis torquent quam debent, quaedam ante torquent quam debent, quaedam torquent cum omnino non debeant","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 13, 5","te":["angustia","miedo","sufrimiento"]},{"i":"seneca-018","a":"seneca","t":"La filosofía no es un arte para el público ni hecho para la ostentación: no está en las palabras sino en los hechos.","o":"Non est philosophia populare artificium nec ostentationi paratum; non in verbis sed in rebus est.","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 16, 3","te":["sentido-de-vida","autenticidad"]},{"i":"seneca-019","a":"seneca","t":"La naturaleza desea poco; la opinión, lo inmenso.","o":"Exiguum natura desiderat, opinio immensum.","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 16, 8","te":["deseo","felicidad"]},{"i":"seneca-020","a":"seneca","t":"¿Qué es la sabiduría? Querer siempre lo mismo y rechazar siempre lo mismo.","o":"quid est sapientia? semper idem velle atque idem nolle.","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 20, 5","te":["identidad","autenticidad"]},{"i":"seneca-021","a":"seneca","t":"Antes que nada, querido Lucilio, hacé esto: aprendé a alegrarte.","o":"Hoc ante omnia fac, mi Lucili: disce gaudere.","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 23, 3","te":["alegria","felicidad"]},{"i":"seneca-022","a":"seneca","t":"La verdadera alegría es una cosa seria.","o":"verum gaudium res severa est","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 23, 4","te":["alegria","felicidad"]},{"i":"seneca-023","a":"seneca","t":"Quien dice esto [“meditá sobre la muerte”] nos manda meditar sobre la libertad. Quien aprendió a morir desaprendió a servir.","o":"qui hoc dicit meditari libertatem iubet. Qui mori didicit servire dedidicit","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 26, 10","te":["muerte","libertad"]},{"i":"seneca-024","a":"seneca","t":"Una mente buena no se presta ni se compra.","o":"Bona mens nec commodatur nec emitur","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 27, 8","te":["autoconocimiento","transformacion-personal"]},{"i":"seneca-025","a":"seneca","t":"Morimos cada día: cada día se nos quita una parte de la vida, y aun cuando crecemos, la vida decrece.","o":"Cotidie morimur; cotidie enim demitur aliqua pars vitae, et tunc quoque cum crescimus vita decrescit.","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 24, 20","te":["muerte","tiempo","cambio"]},{"i":"seneca-026","a":"seneca","t":"Tenés que cambiar de ánimo, no de cielo.","o":"Animum debes mutare, non caelum.","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 28, 1","te":["transformacion-personal","cambio"]},{"i":"seneca-027","a":"seneca","t":"¿Te preguntás por qué esa huida no te ayuda? Huís con vos mismo.","o":"Quaeris quare te fuga ista non adiuvet? tecum fugis.","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 28, 2","te":["autoconocimiento","cambio","sufrimiento"]},{"i":"seneca-028","a":"seneca","t":"Dios está cerca de vos, está con vos, está adentro.","o":"prope est a te deus, tecum est, intus est.","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 41, 1","te":["trascendencia","conciencia"]},{"i":"seneca-029","a":"seneca","t":"Dentro de nosotros habita un espíritu sagrado, observador y guardián de nuestros males y nuestros bienes.","o":"sacer intra nos spiritus sedet, malorum bonorumque nostrorum observator et custos","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 41, 2","te":["conciencia","trascendencia"]},{"i":"seneca-030","a":"seneca","t":"“Son esclavos”. No: son seres humanos.","o":"'Servi sunt.' Immo homines.","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 47, 1","te":["sociedad","encuentro"]},{"i":"seneca-031","a":"seneca","t":"Si querés vivir para vos, tenés que vivir para otro.","o":"alteri vivas oportet, si vis tibi vivere.","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 48, 2","te":["vinculos","sentido-de-vida","encuentro"]},{"i":"seneca-032","a":"seneca","t":"Nuestro mal no viene de afuera: está dentro de nosotros, asentado en las mismas entrañas.","o":"non est extrinsecus malum nostrum: intra nos est, in visceribus ipsis sedet","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 50, 4","te":["sufrimiento","autoconocimiento"]},{"i":"seneca-033","a":"seneca","t":"Nadie es lo bastante fuerte para salir a flote solo: hace falta que alguien le tienda la mano, que alguien lo saque.","o":"Nemo per se satis valet ut emergat; oportet manum aliquis porrigat, aliquis educat.","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 52, 2","te":["vinculos","terapia","resiliencia"]},{"i":"seneca-034","a":"seneca","t":"Que los ojos no estén secos al perder a un amigo, ni desborden: hay que llorar, no lamentarse a gritos.","o":"Nec sicci sint oculi amisso amico nec fluant; lacrimandum est, non plorandum.","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 63, 1","te":["duelo","tristeza","perdida"]},{"i":"seneca-035","a":"seneca","t":"Aquel a quien creés perdido, solo se adelantó.","o":"quem putas perisse praemissus est","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 81, 7","te":["duelo","muerte","perdida"]},{"i":"seneca-036","a":"seneca","t":"Nadie muere sino en su día.","o":"nemo nisi suo die moritur","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 69, 6","te":["muerte"]},{"i":"seneca-037","a":"seneca","t":"Lo bueno no es vivir, sino vivir bien.","o":"non enim vivere bonum est, sed bene vivere.","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 70, 4","te":["sentido-de-vida"]},{"i":"seneca-038","a":"seneca","t":"Para quien no sabe a qué puerto se dirige, ningún viento es favorable.","o":"ignoranti quem portum petat nullus suus ventus est","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 71, 3","te":["sentido-de-vida","incertidumbre"]},{"i":"seneca-039","a":"seneca","t":"Hay que aprender mientras no sepas; y si creemos al proverbio, mientras vivas.","o":"Tamdiu discendum est quamdiu nescias; si proverbio credimus, quamdiu vivas.","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 74, 3","te":["educacion","desarrollo-humano"]},{"i":"seneca-040","a":"seneca","t":"El dolor es leve si la opinión no le agrega nada.","o":"levis est dolor si nihil illi opinio adiecerit","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 74, 13","te":["sufrimiento","aceptacion"]},{"i":"seneca-041","a":"seneca","t":"El ocio sin estudio es muerte y sepultura del ser humano vivo.","o":"otium sine litteris mors est et hominis vivi sepultura","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 81, 3","te":["sentido-de-vida","educacion"]},{"i":"seneca-042","a":"seneca","t":"El ser humano, cosa sagrada para el ser humano.","o":"Homo, sacra res homini","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 81, 33","te":["sociedad","encuentro"]},{"i":"seneca-043","a":"seneca","t":"Sufre más de lo necesario quien sufre antes de lo necesario.","o":"Plus dolet quam necesse est qui ante dolet quam necesse est","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 81, 8","te":["angustia","sufrimiento","miedo"]},{"i":"seneca-044","a":"seneca","t":"No tenés que estar en otra parte, sino ser otro.","o":"non aliubi sis oportet sed alius","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 81, 8","te":["transformacion-personal","cambio"]},{"i":"seneca-045","a":"seneca","t":"Considerá una gran cosa ser un solo hombre: ser siempre el mismo.","o":"Magnam rem puta unum hominem agere.","l":"la","ob":"Cartas a Lucilio","an":"c. 62–65","u":"Carta 81, 33","te":["identidad","autenticidad"]},{"i":"seneca-046","a":"seneca","t":"No es que tengamos poco tiempo, sino que perdemos mucho.","o":"Non exiguum temporis habemus, sed multum perdidimus.","l":"la","ob":"Sobre la brevedad de la vida","an":"c. 49","u":"1, 3","te":["tiempo"]},{"i":"seneca-047","a":"seneca","t":"La vida, si sabés usarla, es larga.","o":"uita, si uti scias, longa est","l":"la","ob":"Sobre la brevedad de la vida","an":"c. 49","u":"2, 1","te":["tiempo","sentido-de-vida"]},{"i":"seneca-048","a":"seneca","t":"El mayor obstáculo para vivir es la espera, que depende del mañana y pierde el hoy.","o":"Maximum uiuendi impedimentum est exspectatio, quae pendet ex crastino, perdit hodiernum.","l":"la","ob":"Sobre la brevedad de la vida","an":"c. 49","u":"9, 1","te":["tiempo","presencia"]},{"i":"seneca-049","a":"seneca","t":"Todo lo que vendrá está en lo incierto: viví ahora.","o":"Omnia quae uentura sunt in incerto iacent: protinus uiue.","l":"la","ob":"Sobre la brevedad de la vida","an":"c. 49","u":"9, 1","te":["incertidumbre","presencia","tiempo"]},{"i":"seneca-050","a":"seneca","t":"A vivir hay que aprender toda la vida y, lo que quizás te asombre más, toda la vida hay que aprender a morir.","o":"uiuere tota uita discendum est et, quod magis fortasse miraberis, tota uita discendum est mori.","l":"la","ob":"Sobre la brevedad de la vida","an":"c. 49","u":"7, 3","te":["muerte","desarrollo-humano","sentido-de-vida"]},{"i":"seneca-051","a":"seneca","t":"Nada es menos propio de una persona atareada que vivir: no hay ciencia más difícil.","o":"Nihil minus est hominis occupati quam uiuere: nullius rei difficilior scientia est.","l":"la","ob":"Sobre la brevedad de la vida","an":"c. 49","u":"7, 3","te":["tiempo","trabajo","sentido-de-vida"]},{"i":"seneca-052","a":"seneca","t":"El mayor remedio de la ira es la demora.","o":"Maximum remedium irae mora est.","l":"la","ob":"Sobre la ira","an":"c. 41","u":"Libro 2, 29, 1","te":["ira","regulacion-emocional"]},{"i":"seneca-053","a":"seneca","t":"El fuego prueba el oro; la desgracia, a los valientes.","o":"Ignis aurum probat, miseria fortes uiros.","l":"la","ob":"Sobre la providencia","an":"c. 64","u":"5, 9","te":["resiliencia","sufrimiento"]},{"i":"marco-aurelio-001","a":"marco-aurelio","t":"Empezá la mañana diciéndote: hoy me voy a encontrar con el entrometido, el desagradecido, el arrogante, el mentiroso, el envidioso, el insociable.","o":"Begin the morning by saying to thyself, I shall meet with the busybody, the ungrateful, arrogant, deceitful, envious, unsocial.","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 2, 1","te":["vinculos","aceptacion"]},{"i":"marco-aurelio-002","a":"marco-aurelio","t":"Recordá cuánto tiempo hace que venís postergando estas cosas.","o":"Remember how long thou hast been putting off these things","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 2, 4","te":["tiempo","cambio"]},{"i":"marco-aurelio-003","a":"marco-aurelio","t":"Nadie pierde otra vida que la que vive ahora, ni vive otra que la que ahora pierde.","o":"no man loses any other life than this which he now lives, nor lives any other than this which he now loses","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 2, 14","te":["tiempo","presencia","muerte"]},{"i":"marco-aurelio-004","a":"marco-aurelio","t":"Cada uno vive solo este momento presente, que es un punto indivisible; todo lo demás de su vida ya pasó o es incierto.","o":"every man lives only this present time, which is an indivisible point, and that all the rest of his life is either past or it is uncertain","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 3, 10","te":["presencia","tiempo","incertidumbre"]},{"i":"marco-aurelio-005","a":"marco-aurelio","t":"En ningún lugar encuentra una persona un retiro más tranquilo y libre de inquietud que en su propia alma.","o":"nowhere either with more quiet or more freedom from trouble does a man retire than into his own soul","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 4, 3","te":["silencio","presencia","autoconocimiento"]},{"i":"marco-aurelio-006","a":"marco-aurelio","t":"El universo es transformación; la vida, opinión.","o":"The universe is transformation: life is opinion.","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 4, 3","te":["cambio","conciencia"]},{"i":"marco-aurelio-007","a":"marco-aurelio","t":"Quitá tu opinión y se quita la queja “me hicieron daño”.","o":"Take away thy opinion, and then there is taken away the complaint, \"I have been harmed.\"","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 4, 7","te":["sufrimiento","aceptacion"]},{"i":"marco-aurelio-008","a":"marco-aurelio","t":"No actúes como si fueras a vivir diez mil años. La muerte pende sobre vos. Mientras vivas, mientras esté en tu poder, sé bueno.","o":"Do not act as if thou wert going to live ten thousand years. Death hangs over thee. While thou livest, while it is in thy power, be good.","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 4, 17","te":["muerte","tiempo","responsabilidad"]},{"i":"marco-aurelio-009","a":"marco-aurelio","t":"Cuántas molestias se ahorra quien no mira lo que dice, hace o piensa el vecino, sino solo lo que hace él mismo.","o":"How much trouble he avoids who does not look to see what his neighbor says or does or thinks, but only to what he does himself","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 4, 18","te":["autoconocimiento","responsabilidad"]},{"i":"marco-aurelio-010","a":"marco-aurelio","t":"Sé como el promontorio contra el que rompen sin cesar las olas: se mantiene firme y amansa la furia del agua a su alrededor.","o":"Be like the promontory against which the waves continually break, but it stands firm and tames the fury of the water around it.","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 4, 49","te":["resiliencia","regulacion-emocional"]},{"i":"marco-aurelio-011","a":"marco-aurelio","t":"Como sean tus pensamientos habituales, así será el carácter de tu mente: el alma se tiñe de sus pensamientos.","o":"Such as are thy habitual thoughts, such also will be the character of thy mind; for the soul is dyed by the thoughts.","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 5, 16","te":["conciencia","habitos","identidad"]},{"i":"marco-aurelio-012","a":"marco-aurelio","t":"La mejor manera de vengarte es no volverte como quien te hizo daño.","o":"The best way of avenging thyself is not to become like","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 6, 6","te":["ira","vinculos"]},{"i":"marco-aurelio-013","a":"marco-aurelio","t":"Mirá hacia adentro. Adentro está la fuente del bien, y siempre brotará si siempre cavás.","o":"Look within. Within is the fountain of good, and it will ever bubble up, if thou wilt ever dig.","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 7, 59","te":["autoconocimiento","conciencia"]},{"i":"marco-aurelio-014","a":"marco-aurelio","t":"Si algo externo te duele, no es esa cosa la que te perturba, sino tu propio juicio sobre ella.","o":"If thou art pained by any external thing, it is not this thing that disturbs thee, but thy own judgment about it.","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 8, 47","te":["sufrimiento","regulacion-emocional","conciencia"]},{"i":"marco-aurelio-015","a":"marco-aurelio","t":"No sigas discutiendo cómo debe ser un hombre bueno: selo.","o":"No longer talk at all about the kind of man that a good man ought to be, but be such.","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 10, 16","te":["autenticidad","responsabilidad"]},{"i":"marco-aurelio-016","a":"marco-aurelio","t":"Considerá cuánto más dolor nos causan la ira y el fastidio por esos actos que los actos mismos.","o":"consider how much more pain is brought on us by the anger and vexation caused by such acts than by the acts themselves","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 11, 18","te":["ira","sufrimiento"]},{"i":"marco-aurelio-017","a":"marco-aurelio","t":"[Cada uno se ama más que a nadie, y sin embargo] valora menos su propia opinión sobre sí que la opinión de los demás.","o":"sets less value on his own opinion of himself than on the opinion of others","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 12, 4","te":["identidad","autenticidad"]},{"i":"marco-aurelio-018","a":"marco-aurelio","t":"Cuidate de no volverte un César, de no teñirte con ese tinte.","o":"Take care that thou art not made into a Caesar, that thou art not dyed with this dye","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 6, 30","te":["poder","identidad"]},{"i":"marco-aurelio-019","a":"marco-aurelio","t":"La perfección del carácter consiste en vivir cada día como si fuera el último.","o":"The perfection of moral character consists in this, in passing every day as the last","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 7, 69","te":["muerte","presencia"]},{"i":"marco-aurelio-020","a":"marco-aurelio","t":"Los seres humanos existen los unos para los otros. Enseñales, entonces, o soportalos.","o":"Men exist for the sake of one another. Teach them then, or bear with them.","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 8, 59","te":["vinculos","aceptacion"]},{"i":"marco-aurelio-021","a":"marco-aurelio","t":"Lo que es obstáculo en el camino nos ayuda en ese camino.","o":"that which is an obstacle on the road helps us on this road","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 5, 20","te":["resiliencia","cambio"]},{"i":"marco-aurelio-022","a":"marco-aurelio","t":"Cuando te ofenda la desvergüenza de alguien, preguntate enseguida: ¿es posible que no haya desvergonzados en el mundo? No es posible.","o":"When thou art offended with any man's shameless conduct, immediately ask thyself, Is it possible, then, that shameless men should not be in the world? It is not possible.","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 9, 42","te":["aceptacion","ira"]},{"i":"marco-aurelio-023","a":"marco-aurelio","t":"Que no te perturbe lo que vendrá: llegarás a ello, si hace falta, con la misma razón que hoy usás para lo presente.","o":"Let not future things disturb thee, for thou wilt come to them, if it shall be necessary, having with thee the same reason which now thou usest for present things.","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 7, 8","te":["incertidumbre","angustia","presencia"]},{"i":"marco-aurelio-024","a":"marco-aurelio","t":"Puesto que es posible que dejes la vida en este mismo momento, regulá cada acto y cada pensamiento en consecuencia.","o":"Since it is possible that thou mayest depart from life this very moment, regulate every act and thought accordingly.","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 2, 11","te":["muerte","presencia"]},{"i":"marco-aurelio-025","a":"marco-aurelio","t":"“Ocupate de pocas cosas si querés estar tranquilo”, dice el filósofo. Pero pensá si no sería mejor decir: hacé lo necesario.","o":"Occupy thyself with few things, says the philosopher, if thou wouldst be tranquil.--But consider if it would not be better to say, Do what is necessary","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 4, 24","te":["presencia","trabajo"]},{"i":"marco-aurelio-026","a":"marco-aurelio","t":"Si alguien puede convencerme y mostrarme que no pienso o no actúo bien, cambiaré con gusto: busco la verdad, y nadie fue jamás dañado por ella.","o":"If any man is able to convince me and show me that I do not think or act right, I will gladly change; for I seek the truth, by which no man was ever injured.","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 6, 21","te":["verdad","cambio","transformacion-personal"]},{"i":"marco-aurelio-027","a":"marco-aurelio","t":"No malgastes lo que te queda de vida en pensamientos sobre los demás.","o":"Do not waste the remainder of thy life in thoughts about others","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 3, 4","te":["tiempo","autoconocimiento"]},{"i":"marco-aurelio-028","a":"marco-aurelio","t":"A la mañana, cuando te levantes de mala gana, tené presente este pensamiento: me levanto para hacer la obra de un ser humano.","o":"In the morning when thou risest unwillingly, let this thought be present,--I am rising to the work of a human being.","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 5, 1","te":["trabajo","sentido-de-vida"]},{"i":"marco-aurelio-029","a":"marco-aurelio","t":"Es propio del ser humano amar incluso a quienes obran mal.","o":"It is peculiar to man to love even those who do wrong.","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 7, 22","te":["amor","compasion"]},{"i":"marco-aurelio-030","a":"marco-aurelio","t":"No te perturbes pensando en la totalidad de tu vida.","o":"Do not disturb thyself by thinking of the whole of thy life.","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 8, 36","te":["angustia","presencia"]},{"i":"marco-aurelio-031","a":"marco-aurelio","t":"Cuando quieras alegrarte, pensá en las virtudes de quienes viven con vos.","o":"When thou wishest to delight thyself, think of the virtues of those who live with thee","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 6, 48","te":["alegria","vinculos","gratitud"]},{"i":"marco-aurelio-032","a":"marco-aurelio","t":"Todas las cosas están entrelazadas unas con otras, y el lazo es sagrado.","o":"All things are implicated with one another, and the bond is holy","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 7, 9","te":["conexion","naturaleza"]},{"i":"marco-aurelio-033","a":"marco-aurelio","t":"De la vida humana, el tiempo es un punto y la sustancia, un flujo.","o":"Of human life the time is a point, and the substance is in a flux","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 2, 17","te":["tiempo","cambio"]},{"i":"marco-aurelio-034","a":"marco-aurelio","t":"Si algo te resulta difícil de lograr, no pienses que es imposible para el ser humano.","o":"If a thing is difficult to be accomplished by thyself, do not think that it is impossible for man","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 6, 19","te":["resiliencia"]},{"i":"marco-aurelio-035","a":"marco-aurelio","t":"No desprecies la muerte: aceptala de buen grado, porque también ella es una de las cosas que la naturaleza quiere.","o":"Do not despise death, but be well content with it, since this too is one of those things which nature wills.","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 9, 3","te":["muerte","aceptacion","naturaleza"]},{"i":"marco-aurelio-036","a":"marco-aurelio","t":"Si alguien se equivoca, enseñale con amabilidad y mostrale su error.","o":"If a man is mistaken, instruct him kindly and show him his error.","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 10, 4","te":["comunicacion","compasion"]},{"i":"marco-aurelio-037","a":"marco-aurelio","t":"Considerá que también vos hacés muchas cosas mal, y que sos un ser humano como los demás.","o":"consider that thou also doest many things wrong, and that thou art a man like others","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 11, 18","te":["compasion","autoconocimiento"]},{"i":"marco-aurelio-038","a":"marco-aurelio","t":"Quien obra mal, obra mal contra sí mismo.","o":"He who does wrong does wrong against himself.","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 9, 4","te":["responsabilidad"]},{"i":"marco-aurelio-039","a":"marco-aurelio","t":"Tu opinión presente fundada en la comprensión, tu conducta presente orientada al bien común y tu disposición presente de contento con todo lo que sucede: eso basta.","o":"Thy present opinion founded on understanding, and thy present conduct directed to social good, and thy present disposition of contentment with everything which happens--that is enough.","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 9, 6","te":["presencia","aceptacion"]},{"i":"marco-aurelio-040","a":"marco-aurelio","t":"Que no te importe tener frío o calor si estás cumpliendo tu deber.","o":"Let it make no difference to thee whether thou art cold or warm, if thou art doing thy duty","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 6, 2","te":["responsabilidad","trabajo"]},{"i":"marco-aurelio-041","a":"marco-aurelio","t":"Acostumbrate a atender con cuidado lo que dice otro y, en lo posible, a estar en la mente de quien habla.","o":"Accustom thyself to attend carefully to what is said by another, and as much as it is possible, be in the speaker's mind.","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 6, 53","te":["comunicacion","encuentro","atencion"]},{"i":"marco-aurelio-042","a":"marco-aurelio","t":"Borrá la fantasía. Detené el tirón de los hilos. Limitate al presente.","o":"Wipe out the imagination. Stop the pulling of the strings. Confine thyself to the present.","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 7, 29","te":["presencia","atencion"]},{"i":"marco-aurelio-043","a":"marco-aurelio","t":"A nadie le sucede nada que no esté formado por naturaleza para soportar.","o":"Nothing happens to any man which he is not formed by nature to bear.","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 5, 18","te":["resiliencia","aceptacion"]},{"i":"marco-aurelio-044","a":"marco-aurelio","t":"Todo dura solo un día: lo que recuerda y lo recordado.","o":"Everything is only for a day, both that which remembers and that which is remembered.","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 4, 35","te":["tiempo","muerte"]},{"i":"marco-aurelio-045","a":"marco-aurelio","t":"Amá el oficio que aprendiste, por modesto que sea, y contentate con él.","o":"Love the art, poor as it may be, which thou hast learned, and be content with it","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 4, 31","te":["trabajo","aceptacion"]},{"i":"marco-aurelio-046","a":"marco-aurelio","t":"El arte de vivir se parece más al del luchador que al del bailarín.","o":"The art of life is more like the wrestler's art than the dancer's","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 7, 61","te":["resiliencia","sentido-de-vida"]},{"i":"marco-aurelio-047","a":"marco-aurelio","t":"Que haya serenidad frente a lo que viene de una causa externa.","o":"Let there be freedom from perturbations with respect to the things which come from the external cause","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 9, 31","te":["regulacion-emocional","aceptacion"]},{"i":"marco-aurelio-048","a":"marco-aurelio","t":"Retirate en vos mismo. La razón que gobierna tiene esta naturaleza: se contenta consigo cuando obra con justicia, y así asegura la tranquilidad.","o":"Retire into thyself. The rational principle which rules has this nature, that it is content with itself when it does what is just, and so secures tranquillity.","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 7, 28","te":["silencio","autoconocimiento"]},{"i":"marco-aurelio-049","a":"marco-aurelio","t":"No es justo ofenderse con los demás: tu deber es cuidarlos y soportarlos con dulzura.","o":"it is no way right to be offended with men, but it is thy duty to care for them and to bear with them gently","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 9, 3","te":["vinculos","compasion"]},{"i":"marco-aurelio-050","a":"marco-aurelio","t":"Qué ridículo y qué extraño a la vida es quien se sorprende de cualquier cosa que sucede en ella.","o":"How ridiculous and what a stranger he is who is surprised at anything which happens in life.","l":"en","ob":"Meditaciones","an":"c. 170–180","u":"Libro 12, 13","te":["aceptacion","existencia"]},{"i":"sigmund-freud-001","a":"sigmund-freud","t":"La intención de que el ser humano sea “feliz” no está contenida en el plan de la “Creación”.","o":"die Absicht, daß der Mensch \"glücklich\" sei, ist im Plan der \"Schöpfung\" nicht enthalten","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 2","te":["felicidad","sufrimiento"]},{"i":"sigmund-freud-002","a":"sigmund-freud","t":"El sufrimiento nos amenaza desde tres lados: desde el propio cuerpo, condenado a la decadencia y la disolución, que ni siquiera puede prescindir del dolor y la angustia como señales de alarma; desde el mundo exterior, que puede abatirse sobre nosotros con fuerzas hiperpotentes, implacables y destructivas; y por último, desde los vínculos con otros seres humanos.","o":"Von drei Seiten droht das Leiden, vom eigenen Körper her, der, zu Verfall und Auflösung bestimmt, sogar Schmerz und Angst als Warnungssignale nicht entbehren kann, von der Außenwelt, die mit übermächtigen, unerbittlichen, zerstörenden Kräften gegen uns wüten kann, und endlich aus den Beziehungen zu anderen Menschen.","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 2","te":["sufrimiento","vinculos","cuerpo"]},{"i":"sigmund-freud-003","a":"sigmund-freud","t":"El sufrimiento que proviene de esta fuente [los vínculos] lo sentimos quizás más dolorosamente que cualquier otro.","o":"Das Leiden, das aus dieser Quelle stammt, empfinden wir vielleicht schmerzlicher als jedes andere","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 2","te":["sufrimiento","vinculos"]},{"i":"sigmund-freud-004","a":"sigmund-freud","t":"Nunca estamos más desprotegidos frente al sufrimiento que cuando amamos; nunca más desamparadamente infelices que cuando perdimos al objeto amado o su amor.","o":"Niemals sind wir ungeschützter gegen das Leiden, als wenn wir lieben, niemals hilfloser unglücklich, als wenn wir das geliebte Objekt oder seine Liebe verloren haben.","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 2","te":["amor","perdida","duelo"]},{"i":"sigmund-freud-005","a":"sigmund-freud","t":"La vida, tal como nos es impuesta, resulta demasiado pesada: nos trae demasiados dolores, desengaños, tareas insolubles.","o":"Das Leben, wie es uns auferlegt ist, ist zu schwer für uns, es bringt uns zuviel Schmerzen, Enttäuschungen, unlösbare Aufgaben.","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 2","te":["sufrimiento","existencia"]},{"i":"sigmund-freud-006","a":"sigmund-freud","t":"El ser humano se ha convertido, por así decir, en una especie de dios con prótesis: bastante magnífico cuando se coloca todos sus órganos auxiliares, pero estos no se le han integrado.","o":"Der Mensch ist sozusagen eine Art Prothesengott geworden, recht großartig, wenn er alle seine Hilfsorgane anlegt, aber sie sind nicht mit ihm verwachsen","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 3","te":["tecnologia","cultura"]},{"i":"sigmund-freud-007","a":"sigmund-freud","t":"La felicidad, en ese sentido moderado en que se la reconoce posible, es un problema de la economía libidinal de cada individuo.","o":"Das Glück in jenem ermäßigten Sinn, in dem es als möglich erkannt wird, ist ein Problem der individuellen Libidoökonomie.","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 2","te":["felicidad","deseo"]},{"i":"sigmund-freud-008","a":"sigmund-freud","t":"El goce de la belleza tiene un carácter sensorial particular, suavemente embriagador.","o":"Der Genuß an der Schönheit hat einen besonderen, milde berauschenden Empfindungscharakter.","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 2","te":["alegria","cultura"]},{"i":"sigmund-freud-009","a":"sigmund-freud","t":"La utilidad de la belleza no es evidente, su necesidad cultural no se ve, y sin embargo la cultura no podría prescindir de ella.","o":"Ein Nutzen der Schönheit liegt nicht klar zutage, ihre kulturelle Notwendigkeit ist nicht einzusehen, und doch könnte man sie in der Kultur nicht vermissen.","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 2","te":["cultura"]},{"i":"sigmund-freud-010","a":"sigmund-freud","t":"Esta actitud estética ante la meta de la vida protege poco contra los sufrimientos que amenazan, pero puede compensar muchas cosas.","o":"Diese ästhetische Einstellung zum Lebensziel bietet wenig Schutz gegen drohende Leiden, vermag aber für vieles zu entschädigen.","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 2","te":["sufrimiento","cultura"]},{"i":"sigmund-freud-011","a":"sigmund-freud","t":"Quien emprende este camino hacia la felicidad [rehacer el mundo según sus deseos] con una rebeldía desesperada, por lo general no logrará nada: la realidad es demasiado fuerte para él.","o":"Wer in verzweifelter Empörung diesen Weg zum Glück einschlägt, wird in der Regel nichts erreichen; die Wirklichkeit ist zu stark für ihn.","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 2","te":["felicidad","deseo"]},{"i":"sigmund-freud-012","a":"sigmund-freud","t":"La tarea es desplazar las metas pulsionales de manera que la frustración que impone el mundo exterior no pueda alcanzarlas.","o":"Die zu lösende Aufgabe ist, die Triebziele solcherart zu verlegen, daß sie von der Versagung der Außenwelt nicht getroffen werden können.","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 2","te":["deseo","sufrimiento"]},{"i":"sigmund-freud-013","a":"sigmund-freud","t":"Y sin embargo, las personas valoran poco el trabajo como camino hacia la felicidad.","o":"Und dennoch wird Arbeit als Weg zum Glück von den Menschen wenig geschätzt.","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 2","te":["trabajo","felicidad"]},{"i":"sigmund-freud-014","a":"sigmund-freud","t":"El ser humano civilizado cambió una parte de posibilidad de felicidad por una parte de seguridad.","o":"Der Kulturmensch hat für ein Stück Glücksmöglichkeit ein Stück Sicherheit eingetauscht.","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 5","te":["cultura","felicidad","sociedad"]},{"i":"sigmund-freud-015","a":"sigmund-freud","t":"La cultura tiene que movilizarlo todo para poner límites a las pulsiones agresivas de los seres humanos.","o":"Die Kultur muß alles aufbieten, um den Aggressionstrieben der Menschen Schranken zu setzen","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 5","te":["cultura","ira","sociedad"]},{"i":"sigmund-freud-016","a":"sigmund-freud","t":"Siempre es posible ligar amorosamente entre sí a una multitud mayor de personas, con tal de que queden otras para manifestarles la agresión.","o":"Es ist immer möglich, eine größere Menge von Menschen in Liebe aneinander zu binden, wenn nur andere für die Äußerung der Aggression übrigbleiben.","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 5","te":["sociedad","ira","poder"]},{"i":"sigmund-freud-017","a":"sigmund-freud","t":"Las pasiones pulsionales son más fuertes que los intereses racionales.","o":"triebhafte Leidenschaften sind stärker als vernünftige Interessen","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 5","te":["deseo","sociedad"]},{"i":"sigmund-freud-018","a":"sigmund-freud","t":"La agresión es introyectada, interiorizada, en verdad devuelta al lugar de donde vino: vuelta contra el propio yo.","o":"Die Aggression wird introjiziert, verinnerlicht, eigentlich aber dorthin zurückgeschickt, woher sie gekommen ist, also gegen das eigene Ich gewendet.","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 7","te":["culpa","ira","inconsciente"]},{"i":"sigmund-freud-019","a":"sigmund-freud","t":"A la tensión entre el severo superyó y el yo que le está sometido la llamamos conciencia de culpa; se manifiesta como necesidad de castigo.","o":"Die Spannung zwischen dem gestrengen Über-Ich und dem ihm unterworfenen Ich heißen wir Schuldbewußtsein; sie äußert sich als Strafbedürfnis.","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 7","te":["culpa","inconsciente"]},{"i":"sigmund-freud-020","a":"sigmund-freud","t":"Lo malo es, al principio, aquello por lo cual se nos amenaza con la pérdida del amor; por angustia ante esa pérdida hay que evitarlo.","o":"Das Böse ist also anfänglich dasjenige, wofür man mit Liebesverlust bedroht wird; aus Angst vor diesem Verlust muß man es vermeiden.","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 7","te":["culpa","miedo","amor"]},{"i":"sigmund-freud-021","a":"sigmund-freud","t":"La agresión de la conciencia moral conserva la agresión de la autoridad.","o":"Die Aggression des Gewissens konserviert die Aggression der Autorität.","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 7","te":["culpa","poder"]},{"i":"sigmund-freud-022","a":"sigmund-freud","t":"Las religiones, al menos, nunca desconocieron el papel del sentimiento de culpa en la cultura.","o":"Die Religionen wenigstens haben die Rolle des Schuldgefühls in der Kultur nie verkannt.","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 8","te":["culpa","cultura","trascendencia"]},{"i":"sigmund-freud-023","a":"sigmund-freud","t":"Eros y Ananké [amor y necesidad] se convirtieron también en los padres de la cultura humana.","o":"Eros und Ananke sind auch die Eltern der menschlichen Kultur geworden.","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 4","te":["amor","cultura"]},{"i":"sigmund-freud-024","a":"sigmund-freud","t":"[Mi propósito era] presentar el sentimiento de culpa como el problema más importante del desarrollo cultural.","o":"das Schuldgefühl als das wichtigste Problem der Kulturentwicklung hinzustellen","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 8","te":["culpa","cultura"]},{"i":"sigmund-freud-025","a":"sigmund-freud","t":"No sabría indicar una necesidad de la infancia tan intensa como la de la protección paterna.","o":"Ein ähnlich starkes Bedürfnis aus der Kindheit wie das nach dem Vaterschutz wüßte ich nicht anzugeben.","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 1","te":["familia","infancia"]},{"i":"sigmund-freud-026","a":"sigmund-freud","t":"El beneficio del orden es innegable: permite al ser humano aprovechar mejor el espacio y el tiempo, mientras ahorra sus fuerzas psíquicas.","o":"Die Wohltat der Ordnung ist ganz unleugbar, sie ermöglicht dem Menschen die beste Ausnützung von Raum und Zeit, während sie seine psychischen Kräfte schont.","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 3","te":["habitos","cultura"]},{"i":"sigmund-freud-027","a":"sigmund-freud","t":"El orden es una especie de compulsión de repetición que, establecida una vez, decide cuándo, dónde y cómo debe hacerse algo.","o":"Die Ordnung ist eine Art Wiederholungszwang, die durch einmalige Einrichtung entscheidet, wann, wo und wie etwas getan werden soll","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 3","te":["habitos","inconsciente"]},{"i":"sigmund-freud-028","a":"sigmund-freud","t":"El amor de meta inhibida fue en su origen amor plenamente sensual, y lo sigue siendo en lo inconsciente del ser humano.","o":"Die zielgehemmte Liebe war eben ursprünglich vollsinnliche Liebe und ist es im Unbewußten des Menschen noch immer.","l":"de","ob":"El malestar en la cultura","an":"1930","u":"Capítulo 4","te":["amor","inconsciente","deseo"]},{"i":"sigmund-freud-029","a":"sigmund-freud","t":"La voz del intelecto es baja, pero no descansa hasta hacerse oír.","o":"die Stimme des Intellekts ist leise, aber sie ruht nicht, ehe sie sich Gehör geschafft hat","l":"de","ob":"El porvenir de una ilusión","an":"1927","u":"Capítulo 9","te":["verdad","conciencia"]},{"i":"sigmund-freud-030","a":"sigmund-freud","t":"No, nuestra ciencia no es una ilusión. Pero sería una ilusión creer que podríamos obtener de otra parte lo que ella no puede darnos.","o":"Nein, unsere Wissenschaft ist keine Illusion. Eine Illusion aber wäre es zu glauben, daß wir anderswoher bekommen könnten, was sie uns nicht geben kann.","l":"de","ob":"El porvenir de una ilusión","an":"1927","u":"Capítulo 9","te":["verdad","conocimiento"]},{"i":"sigmund-freud-031","a":"sigmund-freud","t":"El ser humano no puede seguir siendo niño para siempre: tiene que salir, finalmente, a la “vida hostil”.","o":"Der Mensch kann nicht ewig Kind bleiben, er muß endlich hinaus ins \"feindliche Leben\".","l":"de","ob":"El porvenir de una ilusión","an":"1927","u":"Capítulo 8","te":["desarrollo-humano","infancia","responsabilidad"]},{"i":"sigmund-freud-032","a":"sigmund-freud","t":"No hay ninguna instancia por encima de la razón.","o":"Es gibt keine Instanz über der Vernunft.","l":"de","ob":"El porvenir de una ilusión","an":"1927","u":"Capítulo 4","te":["verdad"]},{"i":"sigmund-freud-033","a":"sigmund-freud","t":"Como estamos dispuestos a renunciar a buena parte de nuestros deseos infantiles, podemos soportar que algunas de nuestras expectativas resulten ser ilusiones.","o":"Da wir bereit sind, auf ein gutes Stück unserer infantilen Wünsche zu verzichten, können wir es vertragen, wenn sich einige unserer Erwartungen als Illusionen herausstellen.","l":"de","ob":"El porvenir de una ilusión","an":"1927","u":"Capítulo 9","te":["deseo","aceptacion","desarrollo-humano"]},{"i":"sigmund-freud-034","a":"sigmund-freud","t":"Podemos insistir cuanto queramos en que el intelecto humano carece de fuerza frente a la vida pulsional, y tener razón.","o":"Wir mögen noch so oft betonen, der menschliche Intellekt sei kraftlos im Vergleich zum menschlichen Triebleben, und recht damit haben.","l":"de","ob":"El porvenir de una ilusión","an":"1927","u":"Capítulo 9","te":["deseo","conciencia"]},{"i":"sigmund-freud-035","a":"sigmund-freud","t":"El yo es, ante todo, un yo corporal: no es solo un ser de superficie, sino él mismo la proyección de una superficie.","o":"Das Ich ist vor allem ein körperliches, es ist nicht nur ein Oberflächenwesen, sondern selbst die Projektion einer Oberfläche.","l":"de","ob":"El yo y el ello","an":"1923","u":"Capítulo 2","te":["identidad","cuerpo"]},{"i":"sigmund-freud-036","a":"sigmund-freud","t":"El yo es la verdadera sede de la angustia.","o":"Das Ich ist ja die eigentliche Angststätte.","l":"de","ob":"El yo y el ello","an":"1923","u":"Capítulo 5","te":["angustia","identidad"]},{"i":"sigmund-freud-037","a":"sigmund-freud","t":"[Vemos] al mismo yo como una pobre criatura, sometida a tres servidumbres y que, por eso, sufre la amenaza de tres peligros.","o":"dasselbe Ich als armes Ding, welches unter dreierlei Dienstbarkeiten steht und demzufolge unter den Drohungen von dreierlei Gefahren leidet","l":"de","ob":"El yo y el ello","an":"1923","u":"Capítulo 5","te":["identidad","sufrimiento"]},{"i":"sigmund-freud-038","a":"sigmund-freud","t":"El psicoanálisis es un instrumento que debe permitirle al yo la conquista progresiva del ello.","o":"Die Psychoanalyse ist ein Werkzeug, welches dem Ich die fortschreitende Eroberung des Es ermöglichen soll.","l":"de","ob":"El yo y el ello","an":"1923","u":"Capítulo 5","te":["terapia","inconsciente"]},{"i":"sigmund-freud-039","a":"sigmund-freud","t":"[El yo] ni siquiera es dueño en su propia casa, sino que depende de escasas noticias sobre lo que ocurre de manera inconsciente en su vida anímica.","o":"daß es nicht einmal Herr ist im eigenen Hause, sondern auf kärgliche Nachrichten angewiesen bleibt von dem, was unbewußt in seinem Seelenleben vorgeht","l":"de","ob":"Conferencias de introducción al psicoanálisis","an":"1917","u":"Capítulo 18","te":["inconsciente","identidad","autoconocimiento"]},{"i":"sigmund-freud-040","a":"sigmund-freud","t":"Las palabras fueron en su origen magia, y la palabra conserva todavía hoy mucho de su antiguo poder mágico.","o":"Worte waren ursprünglich Zauber, und das Wort hat noch heute viel von seiner alten Zauberkraft bewahrt.","l":"de","ob":"Conferencias de introducción al psicoanálisis","an":"1917","u":"Capítulo 1","te":["comunicacion","terapia"]},{"i":"sigmund-freud-041","a":"sigmund-freud","t":"Con palabras una persona puede hacer dichosa a otra o empujarla a la desesperación.","o":"Durch Worte kann ein Mensch den anderen selig machen oder zur Verzweiflung treiben","l":"de","ob":"Conferencias de introducción al psicoanálisis","an":"1917","u":"Capítulo 1","te":["comunicacion","vinculos"]},{"i":"sigmund-freud-042","a":"sigmund-freud","t":"En el tratamiento analítico no ocurre otra cosa que un intercambio de palabras entre el analizado y el médico.","o":"In der analytischen Behandlung geht nichts anderes vor als ein Austausch von Worten zwischen dem Analysierten und dem Arzt.","l":"de","ob":"Conferencias de introducción al psicoanálisis","an":"1917","u":"Capítulo 1","te":["terapia","comunicacion"]},{"i":"sigmund-freud-043","a":"sigmund-freud","t":"Los sentimientos hostiles significan un lazo afectivo tanto como los tiernos.","o":"Die feindlichen Gefühle bedeuten ebenso eine Gefühlsbindung wie die zärtlichen","l":"de","ob":"Conferencias de introducción al psicoanálisis","an":"1917","u":"Capítulo 27","te":["vinculos","ira","amor"]},{"i":"sigmund-freud-047","a":"sigmund-freud","t":"Donde era ello, ha de advenir yo. Es un trabajo de cultura, como la desecación del Zuiderzee.","o":"Wo Es war, soll Ich werden. Es ist Kulturarbeit etwa wie die Trockenlegung der Zuydersee.","l":"de","ob":"Nuevas conferencias de introducción al psicoanálisis","an":"1933","u":"Capítulo 3","te":["inconsciente","terapia","transformacion-personal"]},{"i":"sigmund-freud-044","a":"sigmund-freud","t":"La interpretación de los sueños es la vía regia hacia el conocimiento de lo inconsciente en la vida anímica.","o":"Die Traumdeutung aber ist die Via regia zur Kenntnis des Unbewußten im Seelenleben.","l":"de","ob":"La interpretación de los sueños","an":"1900","u":"Capítulo 7","te":["suenos","inconsciente"]},{"i":"sigmund-freud-045","a":"sigmund-freud","t":"El sueño es el cumplimiento (disfrazado) de un deseo (sofocado, reprimido).","o":"Der Traum ist die (verkleidete) Erfüllung eines (unterdrückten, verdrängten) Wunsches","l":"de","ob":"La interpretación de los sueños","an":"1900","u":"Capítulo 4","te":["suenos","deseo","inconsciente"]},{"i":"sigmund-freud-046","a":"sigmund-freud","t":"La meta de toda vida es la muerte.","o":"Das Ziel alles Lebens ist der Tod","l":"de","ob":"Más allá del principio del placer","an":"1920","u":"Capítulo 5","te":["muerte"]},{"i":"sigmund-freud-050","a":"sigmund-freud","t":"El psicoanálisis consideró desde el comienzo que ese destino [que parece perseguir a algunas personas] es en gran parte autoprovocado y está determinado por influencias de la primera infancia.","o":"die Psychoanalyse hat vom Anfang an solches Schicksal für zum großen Teil selbstbereitet und durch frühinfantile Einflüsse determiniert gehalten","l":"de","ob":"Más allá del principio del placer","an":"1920","u":"Capítulo 3","te":["repeticion","infancia","inconsciente"]},{"i":"sigmund-freud-048","a":"sigmund-freud","t":"Nuestras enfermas histéricas sufren de reminiscencias.","o":"Unsere hysterisch Kranken leiden an Reminiszenzen.","l":"de","ob":"Sobre psicoanálisis (Cinco conferencias)","an":"1910","u":"Capítulo 1","te":["sufrimiento","memoria","trauma"]},{"i":"sigmund-freud-049","a":"sigmund-freud","t":"La interpretación de los sueños es, en realidad, la vía regia hacia el conocimiento de lo inconsciente, el fundamento más seguro del psicoanálisis.","o":"Die Traumdeutung ist in Wirklichkeit die Via Regia zur Kenntnis des Unbewußten, die sicherste Grundlage der Psychoanalyse","l":"de","ob":"Sobre psicoanálisis (Cinco conferencias)","an":"1910","u":"Capítulo 3","te":["suenos","inconsciente"]},{"i":"william-james-001","a":"william-james","t":"El hábito es así el enorme volante de la sociedad, su más preciado agente conservador.","o":"Habit is thus the enormous fly-wheel of society, its most precious conservative agent.","l":"en","ob":"Principios de psicología, vol. 1","an":"1890","u":"Capítulo 4","te":["habitos","sociedad"]},{"i":"william-james-002","a":"william-james","t":"Lo importante en toda educación es hacer de nuestro sistema nervioso un aliado y no un enemigo.","o":"make our nervous system our ally instead of our enemy","l":"en","ob":"Principios de psicología, vol. 1","an":"1890","u":"Capítulo 4","te":["habitos","educacion"]},{"i":"william-james-003","a":"william-james","t":"Si los jóvenes comprendieran qué pronto se convertirán en meros manojos ambulantes de hábitos, prestarían más atención a su conducta mientras todavía son moldeables.","o":"Could the young but realize how soon they will become mere walking bundles of habits, they would give more heed to their conduct while in the plastic state.","l":"en","ob":"Principios de psicología, vol. 1","an":"1890","u":"Capítulo 4","te":["habitos","desarrollo-humano"]},{"i":"william-james-004","a":"william-james","t":"Estamos hilando nuestro propio destino, bueno o malo, y no hay manera de deshacerlo.","o":"We are spinning our own fates, good or evil, and never to be undone.","l":"en","ob":"Principios de psicología, vol. 1","an":"1890","u":"Capítulo 4","te":["habitos","responsabilidad"]},{"i":"william-james-005","a":"william-james","t":"Cada mínimo trazo de virtud o de vicio deja su cicatriz, por pequeña que sea.","o":"Every smallest stroke of virtue or of vice leaves its never so little scar.","l":"en","ob":"Principios de psicología, vol. 1","an":"1890","u":"Capítulo 4","te":["habitos","identidad"]},{"i":"william-james-006","a":"william-james","t":"No permitas ninguna excepción hasta que el nuevo hábito esté firmemente arraigado en tu vida.","o":"Never suffer an exception to occur till the new habit is securely rooted in your life","l":"en","ob":"Principios de psicología, vol. 1","an":"1890","u":"Capítulo 4","te":["habitos","cambio"]},{"i":"william-james-007","a":"william-james","t":"Aprovechá la primera oportunidad posible para actuar según cada resolución que tomes.","o":"Seize the very first possible opportunity to act on every resolution you make","l":"en","ob":"Principios de psicología, vol. 1","an":"1890","u":"Capítulo 4","te":["habitos","cambio"]},{"i":"william-james-008","a":"william-james","t":"Mantené viva en vos la capacidad de esfuerzo con un pequeño ejercicio gratuito cada día.","o":"Keep the faculty of effort alive in you by a little gratuitous exercise every day","l":"en","ob":"Principios de psicología, vol. 1","an":"1890","u":"Capítulo 4","te":["habitos","voluntad"]},{"i":"william-james-009","a":"william-james","t":"[La conciencia] no está hecha de piezas articuladas: fluye. “Río” o “corriente” son las metáforas que mejor la describen.","o":"It is nothing jointed; it flows. A 'river' or a 'stream' are the metaphors by which it is most naturally described.","l":"en","ob":"Principios de psicología, vol. 1","an":"1890","u":"Capítulo 9","te":["conciencia"]},{"i":"william-james-010","a":"william-james","t":"Llamémosla corriente del pensamiento, de la conciencia o de la vida subjetiva.","o":"let us call it the stream of thought, of consciousness, or of subjective life","l":"en","ob":"Principios de psicología, vol. 1","an":"1890","u":"Capítulo 9","te":["conciencia"]},{"i":"william-james-011","a":"william-james","t":"Todo pensamiento tiende a formar parte de una conciencia personal.","o":"Every thought tends to be part of a personal consciousness.","l":"en","ob":"Principios de psicología, vol. 1","an":"1890","u":"Capítulo 9","te":["conciencia","identidad"]},{"i":"william-james-012","a":"william-james","t":"Ningún estado, una vez pasado, puede repetirse idéntico a lo que fue.","o":"no state once gone can recur and be identical with what it was before","l":"en","ob":"Principios de psicología, vol. 1","an":"1890","u":"Capítulo 9","te":["conciencia","cambio"]},{"i":"william-james-013","a":"william-james","t":"Mi experiencia es aquello a lo que acepto prestar atención.","o":"My experience is what I agree to attend to.","l":"en","ob":"Principios de psicología, vol. 1","an":"1890","u":"Capítulo 11","te":["atencion","conciencia"]},{"i":"william-james-014","a":"william-james","t":"Sin un interés selectivo, la experiencia es un caos absoluto.","o":"without selective interest, experience is an utter chaos","l":"en","ob":"Principios de psicología, vol. 1","an":"1890","u":"Capítulo 11","te":["atencion","conciencia"]},{"i":"william-james-015","a":"william-james","t":"Todo el mundo sabe qué es la atención.","o":"Every one knows what attention is.","l":"en","ob":"Principios de psicología, vol. 1","an":"1890","u":"Capítulo 11","te":["atencion"]},{"i":"william-james-016","a":"william-james","t":"La capacidad de traer de vuelta voluntariamente una atención que se dispersa, una y otra vez, es la raíz misma del juicio, del carácter y de la voluntad.","o":"the faculty of voluntarily bringing back a wandering attention, over and over again, is the very root of judgment, character, and will","l":"en","ob":"Principios de psicología, vol. 1","an":"1890","u":"Capítulo 11","te":["atencion","voluntad","presencia"]},{"i":"william-james-017","a":"william-james","t":"Una persona tiene tantos “yo” sociales como individuos la reconocen.","o":"a man has as many social selves as there are individuals who recognize him","l":"en","ob":"Principios de psicología, vol. 1","an":"1890","u":"Capítulo 10","te":["identidad","vinculos"]},{"i":"william-james-018","a":"william-james","t":"En su sentido más amplio, el “sí mismo” de una persona es la suma total de todo lo que puede llamar suyo.","o":"a man's Self is the sum total of all that he","l":"en","ob":"Principios de psicología, vol. 1","an":"1890","u":"Capítulo 10","te":["identidad"]},{"i":"william-james-019","a":"william-james","t":"Autoestima = éxito / pretensiones.","o":"Self-esteem = Success/ Pretensions.","l":"en","ob":"Principios de psicología, vol. 1","an":"1890","u":"Capítulo 10","te":["autoestima","identidad"]},{"i":"william-james-020","a":"william-james","t":"Renunciar a las pretensiones es un alivio tan bendito como verlas satisfechas.","o":"To give up pretensions is as blessed a relief as to get them gratified","l":"en","ob":"Principios de psicología, vol. 1","an":"1890","u":"Capítulo 10","te":["autoestima","aceptacion"]},{"i":"william-james-021","a":"william-james","t":"El bebé, asaltado a la vez por ojos, oídos, nariz, piel y entrañas, lo siente todo como una gran confusión floreciente y zumbante.","o":"The baby, assailed by eyes, ears, nose, skin, and entrails at once, feels it all as one great blooming, buzzing confusion","l":"en","ob":"Principios de psicología, vol. 1","an":"1890","u":"Capítulo 13","te":["desarrollo-humano","infancia"]},{"i":"william-james-045","a":"william-james","t":"Solo el interés da acento y énfasis, luz y sombra, fondo y primer plano.","o":"Interest alone gives accent and emphasis, light and shade, background and foreground","l":"en","ob":"Principios de psicología, vol. 1","an":"1890","u":"Capítulo 11","te":["atencion","conciencia"]},{"i":"william-james-048","a":"william-james","t":"Solo las cosas que noto le dan forma a mi mente.","o":"Only those items which I","l":"en","ob":"Principios de psicología, vol. 1","an":"1890","u":"Capítulo 11","te":["atencion","conciencia"]},{"i":"william-james-049","a":"william-james","t":"El infierno que nos espera en el más allá, del que habla la teología, no es peor que el infierno que nos fabricamos en este mundo al moldear habitualmente nuestro carácter de la manera equivocada.","o":"The hell to be endured hereafter, of which theology tells, is no worse than the hell we make for ourselves in this world by habitually fashioning our characters in the wrong way.","l":"en","ob":"Principios de psicología, vol. 1","an":"1890","u":"Capítulo 4","te":["habitos","sufrimiento","responsabilidad"]},{"i":"william-james-022","a":"william-james","t":"El arte de ser sabio es el arte de saber qué pasar por alto.","o":"the art of being wise is the art of knowing what to overlook","l":"en","ob":"Principios de psicología, vol. 2","an":"1890","u":"Capítulo 22","te":["atencion","conocimiento"]},{"i":"william-james-023","a":"william-james","t":"Nos sentimos tristes porque lloramos, enojados porque golpeamos, asustados porque temblamos.","o":"we feel sorry because we cry, angry because we strike, afraid because we tremble","l":"en","ob":"Principios de psicología, vol. 2","an":"1890","u":"Capítulo 25","te":["emociones","cuerpo"]},{"i":"william-james-024","a":"william-james","t":"Una emoción humana puramente desencarnada no es nada.","o":"A purely disembodied human emotion is a nonentity.","l":"en","ob":"Principios de psicología, vol. 2","an":"1890","u":"Capítulo 25","te":["emociones","cuerpo"]},{"i":"william-james-025","a":"william-james","t":"Si queremos vencer tendencias emocionales indeseadas, debemos atravesar con asiduidad, y al principio a sangre fría, los movimientos externos de las disposiciones contrarias que preferimos cultivar.","o":"we must assiduously, and in the first instance cold-bloodedly, go through the","l":"en","ob":"Principios de psicología, vol. 2","an":"1890","u":"Capítulo 25","te":["regulacion-emocional","habitos"]},{"i":"william-james-026","a":"william-james","t":"El logro esencial de la voluntad es atender a un objeto difícil y sostenerlo firme ante la mente.","o":"to_ ATTEND _to a difficult object and hold it fast before the mind","l":"en","ob":"Principios de psicología, vol. 2","an":"1890","u":"Capítulo 26","te":["atencion","voluntad"]},{"i":"william-james-047","a":"william-james","t":"Así como el arte de leer (a partir de cierta etapa de la formación) es el arte de saltear…","o":"As the art of reading (after a certain stage in one's education) is the art of skipping","l":"en","ob":"Principios de psicología, vol. 2","an":"1890","u":"Capítulo 22","te":["educacion","atencion"]},{"i":"william-james-050","a":"william-james","t":"El genio, en verdad, no es mucho más que la capacidad de percibir de una manera no habitual.","o":"Genius, in truth, means little more than the faculty of perceiving in an unhabitual way.","l":"en","ob":"Principios de psicología, vol. 2","an":"1890","u":"Capítulo 19","te":["creatividad","conciencia"]},{"i":"william-james-041","a":"william-james","t":"[La religión significará para nosotros] los sentimientos, actos y experiencias de las personas en su soledad, en la medida en que se perciben en relación con lo que consideren divino.","o":"the feelings, acts, and experiences of individual men in their solitude, so far as they apprehend themselves to stand in relation to whatever they may consider the divine","l":"en","ob":"Las variedades de la experiencia religiosa","an":"1902","u":"Conferencia 2","te":["trascendencia","soledad"]},{"i":"william-james-042","a":"william-james","t":"[Nuestra conciencia de vigilia] no es más que un tipo especial de conciencia; a su alrededor, separadas por la más fina de las pantallas, hay formas potenciales de conciencia completamente distintas.","o":"is but one special type of consciousness, whilst all about it, parted from it by the filmiest of screens, there lie potential forms of consciousness entirely different","l":"en","ob":"Las variedades de la experiencia religiosa","an":"1902","u":"Conferencia 13","te":["conciencia","trascendencia"]},{"i":"william-james-043","a":"william-james","t":"El mundo de nuestra conciencia presente es solo uno entre muchos mundos de conciencia que existen.","o":"the world of our present consciousness is only one out of many worlds of consciousness that exist","l":"en","ob":"Las variedades de la experiencia religiosa","an":"1902","u":"Conferencia 20","te":["conciencia"]},{"i":"william-james-044","a":"william-james","t":"La religión, sea lo que sea, es la reacción total de una persona ante la vida.","o":"Religion, whatever it is, is a man's total reaction upon life","l":"en","ob":"Las variedades de la experiencia religiosa","an":"1902","u":"Conferencia 2","te":["trascendencia","sentido-de-vida"]},{"i":"william-james-038","a":"william-james","t":"La verdad de una idea no es una propiedad estancada que le es inherente. La verdad le sucede a una idea: se vuelve verdadera, los acontecimientos la hacen verdadera.","o":"The truth of an idea is not a stagnant property inherent in it. Truth HAPPENS to an idea. It BECOMES true, is MADE true by events.","l":"en","ob":"Pragmatismo","an":"1907","u":"Conferencia 6","te":["verdad"]},{"i":"william-james-039","a":"william-james","t":"Como seres humanos, podemos ser mentes sanas un día y almas enfermas al siguiente.","o":"as human beings we can be healthy minds on one day and sick souls on the next","l":"en","ob":"Pragmatismo","an":"1907","u":"Conferencia 8","te":["salud-mental","sufrimiento"]},{"i":"william-james-040","a":"william-james","t":"Cualquiera sea el universo en que crea un profesor, tiene que ser al menos un universo que se preste a discursos largos.","o":"Whatever universe a professor believes in must at any rate be a universe that lends itself to lengthy discourse.","l":"en","ob":"Pragmatismo","an":"1907","u":"Conferencia 1","te":["educacion","humor"]},{"i":"william-james-027","a":"william-james","t":"Dondequiera que un proceso vital le comunica entusiasmo a quien lo vive, allí la vida se vuelve verdaderamente significativa.","o":"Wherever a process of life communicates an eagerness to him who lives it, there the life becomes genuinely significant.","l":"en","ob":"Charlas a los maestros sobre psicología y a los estudiantes sobre algunos ideales de la vida","an":"1899","u":"«On A Certain Blindness In Human Beings»","te":["sentido-de-vida","alegria"]},{"i":"william-james-028","a":"william-james","t":"Ni toda la verdad ni todo el bien se revelan a un solo observador.","o":"neither the whole of truth nor the whole of good is revealed to any single observer","l":"en","ob":"Charlas a los maestros sobre psicología y a los estudiantes sobre algunos ideales de la vida","an":"1899","u":"«On A Certain Blindness In Human Beings»","te":["verdad","encuentro"]},{"i":"william-james-029","a":"william-james","t":"La ceguera que todos padecemos respecto de los sentimientos de criaturas y personas distintas de nosotros.","o":"the blindness with which we all are afflicted in regard to the feelings of creatures and people different from ourselves","l":"en","ob":"Charlas a los maestros sobre psicología y a los estudiantes sobre algunos ideales de la vida","an":"1899","u":"«On A Certain Blindness In Human Beings»","te":["empatia","vinculos"]},{"i":"william-james-030","a":"william-james","t":"La acción parece seguir al sentimiento, pero en realidad acción y sentimiento van juntos.","o":"Action seems to follow feeling, but really action and feeling go together","l":"en","ob":"Charlas a los maestros sobre psicología y a los estudiantes sobre algunos ideales de la vida","an":"1899","u":"«The Gospel Of Relaxation»","te":["emociones","regulacion-emocional"]},{"i":"william-james-031","a":"william-james","t":"El camino voluntario soberano hacia la alegría, si perdimos la espontánea, es enderezarnos con alegría, mirar alrededor con alegría [y actuar y hablar como si ya estuviera allí].","o":"the sovereign voluntary path to cheerfulness, if our spontaneous cheerfulness be lost, is to sit up cheerfully, to look round cheerfully","l":"en","ob":"Charlas a los maestros sobre psicología y a los estudiantes sobre algunos ideales de la vida","an":"1899","u":"«The Gospel Of Relaxation»","te":["alegria","regulacion-emocional"]},{"i":"william-james-032","a":"william-james","t":"Somos seres prácticos, cada uno con funciones y deberes limitados que cumplir.","o":"We are practical beings, each of us with limited functions and duties to perform.","l":"en","ob":"Charlas a los maestros sobre psicología y a los estudiantes sobre algunos ideales de la vida","an":"1899","u":"«On A Certain Blindness In Human Beings»","te":["trabajo","identidad"]},{"i":"william-james-046","a":"william-james","t":"Cada recaída es como dejar caer un ovillo que uno estaba enrollando con cuidado.","o":"Each lapse is like the letting fall of a ball of string which one is carefully winding up","l":"en","ob":"Charlas a los maestros sobre psicología y a los estudiantes sobre algunos ideales de la vida","an":"1899","u":"«The Laws Of Habit»","te":["habitos","cambio"]},{"i":"william-james-033","a":"william-james","t":"No le tengas miedo a la vida. Creé que la vida vale la pena, y tu creencia ayudará a crear el hecho.","o":"Be not afraid of life. Believe that life","l":"en","ob":"La voluntad de creer y otros ensayos","an":"1897","u":"«Is Life Worth Living?»","te":["sentido-de-vida","miedo","esperanza"]},{"i":"william-james-034","a":"william-james","t":"Solo arriesgándonos de una hora a la otra vivimos realmente.","o":"It is only by risking our persons from one hour to another that we live at all.","l":"en","ob":"La voluntad de creer y otros ensayos","an":"1897","u":"«Is Life Worth Living?»","te":["libertad","incertidumbre"]},{"i":"william-james-035","a":"william-james","t":"A menudo, nuestra fe anticipada en un resultado incierto es lo único que hace que el resultado se cumpla.","o":"our faith beforehand in an uncertified result","l":"en","ob":"La voluntad de creer y otros ensayos","an":"1897","u":"«Is Life Worth Living?»","te":["esperanza","incertidumbre"]},{"i":"william-james-036","a":"william-james","t":"Nuestra naturaleza pasional no solo puede legítimamente, sino que debe, decidir entre proposiciones [cuando se trata de una opción genuina que el intelecto no puede zanjar].","o":"Our passional nature not only lawfully may, but must, decide an option between propositions","l":"en","ob":"La voluntad de creer y otros ensayos","an":"1897","u":"«The Will To Believe»","te":["deseo","verdad","libertad"]},{"i":"william-james-037","a":"william-james","t":"Podemos decir que esta vida vale la pena, ya que es lo que hacemos de ella, desde el punto de vista moral.","o":"This life is worth living, we can say,","l":"en","ob":"La voluntad de creer y otros ensayos","an":"1897","u":"«Is Life Worth Living?»","te":["sentido-de-vida","responsabilidad"]},{"i":"william-james-051","a":"william-james","t":"Una regla de pensamiento que me impidiera absolutamente reconocer ciertos tipos de verdad, si esas verdades realmente existieran, [sería una regla irracional].","o":"a rule of thinking which would absolutely prevent me from acknowledging certain kinds of truth if those kinds of truth were really there","l":"en","ob":"La voluntad de creer y otros ensayos","an":"1897","u":"«The Will To Believe»","te":["verdad","conocimiento"]},{"i":"alfred-adler-001","a":"alfred-adler","t":"La psicología individual comparada ve en cada acontecimiento psíquico la huella, por así decir el símbolo, de un plan de vida orientado de manera unitaria.","o":"Die vergleichende Individualpsychose erblickt in jedem psychischen Geschehen den Abdruck, sozusagen ein Symbol des einheitlich gerichteten Lebensplanes","l":"de","ob":"El carácter neurótico","an":"1912 (2.ª ed. 1922)","u":"","te":["identidad","sentido-de-vida"]},{"i":"alfred-adler-002","a":"alfred-adler","t":"Y se revela como la obra demoníaca de un afán de dominio desatado que estrangula o aprovecha con astucia el inmortal sentimiento de comunidad de la humanidad.","o":"Und er entschleiert sich als das dämonische Werk der allgemein entfesselten Herrschsucht, die das unsterbliche Gemeinschaftsgefühl der Menschheit drosselt oder listig missbraucht.","l":"de","ob":"El carácter neurótico","an":"1912 (2.ª ed. 1922)","u":"","te":["poder","sociedad"]},{"i":"alfred-adler-003","a":"alfred-adler","t":"Lo aprendido le impondrá una tarea de vida: ir adelante en el desmontaje del afán de poder y en la educación para la comunidad.","o":"Die gewonnenen Erkenntnisse werden ihn dann freilich mit einer Lebensaufgabe belasten: voranzugehen bei dem Abbau des Strebens nach Macht und bei der Erziehung zur Gemeinschaft.","l":"de","ob":"El carácter neurótico","an":"1912 (2.ª ed. 1922)","u":"","te":["poder","educacion","sociedad"]},{"i":"alfred-adler-004","a":"alfred-adler","t":"El desarrollo psíquico de una persona y sus fracasos, incluidas las neurosis y las psicosis, provienen de su posición frente a la lógica absoluta de la convivencia humana.","o":"dass die seelische Entwicklung eines Menschen und deren Fehlschlage, auch die Neurosen und Psychosen, aus seiner Stellungnahme zur absoluten Logik des menschlichen Zusammenlebens stammen.","l":"de","ob":"El carácter neurótico","an":"1912 (2.ª ed. 1922)","u":"","te":["vinculos","salud-mental","sociedad"]},{"i":"alfred-adler-005","a":"alfred-adler","t":"[No llega a esa contradicción por la estructura de su cerebro,] sino por un sentimiento de inferioridad adquirido en una posición difícil de la infancia.","o":"durch ein in einer schwierigen Position der Kindheit erworbenes Minderwertigkeitsgefühl.","l":"de","ob":"El carácter neurótico","an":"1912 (2.ª ed. 1922)","u":"","te":["autoestima","infancia"]},{"i":"alfred-adler-006","a":"alfred-adler","t":"La psicología individual exige desmontar sin condiciones el afán de poder y desplegar el sentimiento de comunidad.","o":"Die Anschauungen unserer Individualpsychologie verlangen den bedingungslosen Abbau des Machtstrebens und die Entfaltung des Gemeinschaftsgefühls.","l":"de","ob":"El carácter neurótico","an":"1912 (2.ª ed. 1922)","u":"","te":["poder","vinculos","sociedad"]},{"i":"alfred-adler-007","a":"alfred-adler","t":"Lo que llamamos la esencia de la neurosis consiste en un gasto aumentado de los recursos psíquicos disponibles.","o":"Was wir das Wesen der Neurose nennen, besteht aus dem vermehrten Aufwand der verfügbaren psychischen Mittel.","l":"de","ob":"El carácter neurótico","an":"1912 (2.ª ed. 1922)","u":"","te":["salud-mental"]},{"i":"alfred-adler-008","a":"alfred-adler","t":"En las personas nerviosas no se encuentran rasgos de carácter completamente nuevos: ni uno solo que no pueda hallarse también en las personas “normales”.","o":"Es linden sich bei den Nervösen keine vollkommen neuen Charakterzüge, kein einziger Zug, der nicht auch beim Normalen nachzuweisen wäre.","l":"de","ob":"El carácter neurótico","an":"1912 (2.ª ed. 1922)","u":"","te":["salud-mental","identidad"]},{"i":"alfred-adler-009","a":"alfred-adler","t":"Los rasgos de carácter acentuados ya se encuentran con claridad en la disposición del alma infantil.","o":"Die verschärften Charakterzüge sind schon deutlich in der neurotischen Disposition der Kinderseele vorzufinden","l":"de","ob":"El carácter neurótico","an":"1912 (2.ª ed. 1922)","u":"","te":["infancia","identidad"]},{"i":"alfred-adler-010","a":"alfred-adler","t":"Así desenmascaramos al carácter neurótico como servidor de una finalidad ficticia y establecimos su dependencia de una meta final.","o":"Somit haben wir auch den neurotischen Charakter als den Diener eines fiktiven Zweckes entlarvt und seine Abhängigkeit von einem Endziel festgestellt.","l":"de","ob":"El carácter neurótico","an":"1912 (2.ª ed. 1922)","u":"","te":["sentido-de-vida","inconsciente"]},{"i":"alfred-adler-011","a":"alfred-adler","t":"Entre estas protecciones están también la fijación y el refuerzo de los rasgos de carácter, que en el caos de la vida forman líneas directrices útiles y así reducen la inseguridad.","o":"Zu diesen Sicherungen gehören auch die Fixierung und Verstärkung der Charakterzüge, die im Chaos des Lebens brauchbare Leitlinien bilden und so die Unsicherheit verringern.","l":"de","ob":"El carácter neurótico","an":"1912 (2.ª ed. 1922)","u":"","te":["identidad","incertidumbre"]},{"i":"alfred-adler-012","a":"alfred-adler","t":"Pero su querer y su pensar se construyen siempre sobre la base de un sentimiento de inferioridad.","o":"Immer aber baut sich sein Wollen und Denken über der Grundlage eines Gefühls der Minderwertigkeit auf.","l":"de","ob":"El carácter neurótico","an":"1912 (2.ª ed. 1922)","u":"","te":["autoestima"]},{"i":"alfred-adler-013","a":"alfred-adler","t":"Este sentimiento debe entenderse siempre como relativo: nace de los vínculos con su entorno o con sus metas.","o":"Dieses Gefühl ist stets als relativ zu verstehen, ist aus den Beziehungen zu seiner Umgebung erwachsen oder zu seinen Zielen.","l":"de","ob":"El carácter neurótico","an":"1912 (2.ª ed. 1922)","u":"","te":["autoestima","vinculos"]},{"i":"alfred-adler-014","a":"alfred-adler","t":"Siempre lo precedió un medirse, un compararse con otros: primero con el padre, el más fuerte de la familia; a veces con la madre, con los hermanos; más tarde con cada persona que se le presenta.","o":"Stets ist ein Messen, ein Vergleichen mit anderen vorausgegangen, erst mit dem Vater, dem Stärksten in der Familie, zuweilen mit der Mutter, mit den Geschwistern, später mit jeder Person, die dem Patienten entgegentritt.","l":"de","ob":"El carácter neurótico","an":"1912 (2.ª ed. 1922)","u":"","te":["autoestima","familia","vinculos"]},{"i":"alfred-adler-015","a":"alfred-adler","t":"Mirando de cerca se reconoce que todo niño, sobre todo el más desfavorecido por naturaleza, hizo una evaluación severa de sí mismo.","o":"Bei näherer Einsicht erkennt man, dass jedes Kind, insbesondere aber das von Natur aus bedrängtere, eine scharfe Selbsteinschätzung vorgenommen hat.","l":"de","ob":"El carácter neurótico","an":"1912 (2.ª ed. 1922)","u":"","te":["infancia","autoestima"]},{"i":"alfred-adler-016","a":"alfred-adler","t":"Pronto el niño aprende a valorar también su debilidad, su desamparo, su miedo y sus muchas incapacidades como medios que le aseguran la ayuda, el apoyo y el interés de los suyos.","o":"Bald aber lernt das Kind auch in seiner Schwäche und Hilflosigkeit, in seiner Angst und in seinen mannigfachen Unfähigkeiten Mittel schätzen, die ihm die Hilfe und Unterstützung seiner Angehörigen, ihr Interesse sichern.","l":"de","ob":"El carácter neurótico","an":"1912 (2.ª ed. 1922)","u":"","te":["infancia","vinculos","miedo"]},{"i":"alfred-adler-017","a":"alfred-adler","t":"En los niños con una desventaja física de origen, el sentimiento de sí que despierta queda siempre disminuido: se valoran menos porque sus posibilidades de satisfacción son mucho más pobres.","o":"Bei konstitutionell minderwertigen Kindern wird das erwachende Persönlichkeitsgefühl stets herabgedrückt, ihre Selbsteinschätzung fällt geringer aus, weil ihre Befriedigungsmöglichkeit weitaus dürftiger ist.","l":"de","ob":"El carácter neurótico","an":"1912 (2.ª ed. 1922)","u":"","te":["infancia","autoestima","cuerpo"]},{"i":"alfred-adler-018","a":"alfred-adler","t":"Su sentimiento de inferioridad frente a las personas y las cosas, su inseguridad en el mundo, lo empujan a reforzar sus líneas directrices.","o":"Sein Minderwertigkeitsgefühl den Personen und Dingen gegenüber, seine Unsicherheit in der Welt drängen ihn zur Verstärkung der Leitlinien.","l":"de","ob":"El carácter neurótico","an":"1912 (2.ª ed. 1922)","u":"","te":["autoestima","incertidumbre"]},{"i":"alfred-adler-019","a":"alfred-adler","t":"Su ficción directriz, actuar como si tuviera que ser superior a todos, puede tomar por eso también la forma de comportarse como si fuera un niño.","o":"Seine leitende Fiktion, so zu handeln, als ob er allen überlegen sein müsste, kann deshalb auch die Form annehmen, sich so zu benehmen, als ob er ein Kind wäre.","l":"de","ob":"El carácter neurótico","an":"1912 (2.ª ed. 1922)","u":"","te":["identidad","inconsciente"]},{"i":"alfred-adler-020","a":"alfred-adler","t":"Sería un error suponer que solo la persona neurótica tiene estas líneas directrices.","o":"Es wäre gefehlt, anzunehmen, dass nur der Neurotiker solche Leitlinien aufweist.","l":"de","ob":"El carácter neurótico","an":"1912 (2.ª ed. 1922)","u":"","te":["identidad","salud-mental"]},{"i":"alfred-adler-021","a":"alfred-adler","t":"La persona nerviosa lleva consigo constantemente el sentimiento de inseguridad.","o":"Der Nervöse trägt das Gefühl der Unsicherheit ständig mit sich.","l":"de","ob":"El carácter neurótico","an":"1912 (2.ª ed. 1922)","u":"","te":["angustia","incertidumbre"]},{"i":"alfred-adler-022","a":"alfred-adler","t":"Se encadenó tanto a sus líneas directrices, las toma tan al pie de la letra y busca tan solo cumplirlas, que sin saberlo renunció a encarar sin prejuicios la solución de los problemas reales.","o":"Er hat sich so sehr an Leitlinien gekettet, nimmt diese wörtlich und sucht nur sie zu realisieren, dass er, ohne es zu wissen, darauf verzichtet hat, unbefangen, ohne Vorurteil an die Lösung realer Fragen zu gehen.","l":"de","ob":"El carácter neurótico","an":"1912 (2.ª ed. 1922)","u":"","te":["libertad","inconsciente","cambio"]},{"i":"alfred-adler-023","a":"alfred-adler","t":"La forma y el contenido de la línea directriz neurótica provienen de las impresiones del niño que se siente relegado.","o":"Form und Inhalt der neurotischen Leitlinie stammen aus den Eindrücken des Kindes, das sich zurückgesetzt fühlt.","l":"de","ob":"El carácter neurótico","an":"1912 (2.ª ed. 1922)","u":"","te":["infancia","autoestima"]},{"i":"alfred-adler-024","a":"alfred-adler","t":"La mirada de la persona neurótica se dirige también, por su sentimiento de inseguridad, mucho más lejos hacia el futuro.","o":"Der Blick des Neurotikers richtet sich auch - wegen des Gefühls der Unsicherheit - viel weiter in die Zukunft.","l":"de","ob":"El carácter neurótico","an":"1912 (2.ª ed. 1922)","u":"","te":["angustia","tiempo"]},{"i":"alfred-adler-025","a":"alfred-adler","t":"Estos rasgos le dan con regularidad la sensación de una carga inmensa que, junto con su enfermedad, le hace creer que tiene un papel de héroe y de mártir.","o":"Regelmässig verschaffen ihm diese Züge das Gefühl einer immensen Belastung, die ihm in Verbindung mit seinem Kranksein eine Helden- und Märtyrerrolle vorgaukelt.","l":"de","ob":"El carácter neurótico","an":"1912 (2.ª ed. 1922)","u":"","te":["identidad","sufrimiento"]},{"i":"alfred-adler-026","a":"alfred-adler","t":"Al mismo tiempo, esos reproches eternos sirven para mantener despiertos su sentimiento y su atención, para demostrarse que lo dejan de lado y no cuentan con él.","o":"Gleichzeitig dienen diese ewigen Vorwürfe dazu, sein Gefühl, seine Aufmerksamkeit wach zu halten, sich zu beweisen, dass man ihn zurücksetze, nicht mit ihm rechne.","l":"de","ob":"El carácter neurótico","an":"1912 (2.ª ed. 1922)","u":"","te":["autoestima","vinculos"]},{"i":"alfred-adler-027","a":"alfred-adler","t":"Si retrocede ante empresas prometedoras, como suele hacerlo también ante delitos o actos inmorales, es porque teme por su sentimiento de sí.","o":"Wenn er vor Gewinn versprechenden Unternehmungen zurückschreckt, wie meist auch vor Verbrechen und unmoralischen Handlungen, so deshalb, weil er für sein Persönlichkeitsgefühl fürchtet.","l":"de","ob":"El carácter neurótico","an":"1912 (2.ª ed. 1922)","u":"","te":["miedo","autoestima"]},{"i":"alfred-adler-028","a":"alfred-adler","t":"[A la persona sana] tampoco se le dividen los fenómenos del mundo en opuestos rígidos.","o":"Ebensowenig zerfallen ihm die Erscheinungen der Welt in starre Gegensätze","l":"de","ob":"El carácter neurótico","an":"1912 (2.ª ed. 1922)","u":"","te":["salud-mental","aceptacion"]},{"i":"alfred-adler-029","a":"alfred-adler","t":"Más bien procura siempre desprender su pensar y su actuar de la línea directriz irreal y ponerlos en armonía con la realidad.","o":"er ist vielmehr jederzeit bestrebt, sein Denken und Handeln von der irrealen Leitlinie loszulösen und mit der Wirklichkeit in Einklang zu bringen.","l":"de","ob":"El carácter neurótico","an":"1912 (2.ª ed. 1922)","u":"","te":["salud-mental","transformacion-personal"]},{"i":"alfred-adler-030","a":"alfred-adler","t":"Que use ficciones como medio para un fin se debe a su utilidad para poder siquiera plantear las cuentas de la vida.","o":"Dass er überhaupt Fiktionen als Mittel zum Zweck benützt, liegt in der Brauchbarkeit der Fiktion, um die Rechnung des Lebens überhaupt ansetzen zu können.","l":"de","ob":"El carácter neurótico","an":"1912 (2.ª ed. 1922)","u":"","te":["conocimiento","sentido-de-vida"]},{"i":"alfred-adler-031","a":"alfred-adler","t":"Desde entonces su integración en la comunidad queda impedida: el trabajo, la sociedad y el amor no se adaptan a su actitud de lucha, suelen ser evitados con timidez o, en el mejor de los casos, se convierten en el escenario de su ambiciosa embriaguez de poder.","o":"Seine Einfügung in die Gemeinschaft ist fortan gehindert, Beruf, Gesellschaft und Liebe fügen sich nicht seiner Kämpferstellung, werden meist scheu umgangen oder bilden bestenfalls den Tummelplatz seines ehrgeizigen Machtrausches.","l":"de","ob":"El carácter neurótico","an":"1912 (2.ª ed. 1922)","u":"","te":["trabajo","amor","sociedad"]},{"i":"alfred-adler-032","a":"alfred-adler","t":"De una inferioridad física de origen, y de posiciones de la infancia que obran de modo parecido, nace así un sentimiento de inferioridad que exige una compensación: elevar el sentimiento de sí.","o":"Aus der konstitutionellen Minderwertigkeit und aus ähnlich wirkenden Positionen der Kindheit erwächst also ein Gefühl der Minderwertigkeit, das eine Kompensation im Sinne der Erhöhung des Persönlichkeitsgefühls verlangt.","l":"de","ob":"El carácter neurótico","an":"1912 (2.ª ed. 1922)","u":"","te":["autoestima","infancia"]},{"i":"alfred-adler-033","a":"alfred-adler","t":"La ficción directriz tiene un esquema simple, infantil, e influye en la percepción y en el mecanismo de la memoria.","o":"Die leitende Fiktion hat ein einfaches, infantiles Schema und beeinflusst die Apperzeption und den Mechanismus des Gedächtnisses.","l":"de","ob":"El carácter neurótico","an":"1912 (2.ª ed. 1922)","u":"","te":["memoria","infancia","inconsciente"]},{"i":"alfred-adler-034","a":"alfred-adler","t":"En este y otros trabajos pude mostrar cómo la inferioridad de un órgano influye de manera duradera en la psique: en el actuar y el pensar, en los sueños, en la elección de oficio, en las inclinaciones y capacidades artísticas.","o":"Ich konnte in dieser und anderen Arbeiten darauf verweisen, wie die Minderwertigkeit eines Organs dauernd die Psyche beeinflusst, im Handeln und Denken, im Träumen, in der Berufswahl, in künstlerischen Neigungen und Fähigkeiten","l":"de","ob":"El carácter neurótico","an":"1912 (2.ª ed. 1922)","u":"","te":["cuerpo","identidad","creatividad"]},{"i":"alfred-adler-035","a":"alfred-adler","t":"La persona nerviosa viene de esta esfera de inseguridad y estuvo en la infancia bajo la presión de su inferioridad física de origen.","o":"Der nervöse Mensch kommt aus dieser Sphäre der Unsicherheit und stand in der Kindheit unter dem Drucke seiner konstitutionellen Minderwertigkeit.","l":"de","ob":"El carácter neurótico","an":"1912 (2.ª ed. 1922)","u":"","te":["infancia","incertidumbre"]},{"i":"alfred-adler-036","a":"alfred-adler","t":"Y para encontrar una línea directriz toma como segundo punto fijo al padre o a la madre, a quienes dota de todas las fuerzas de este mundo.","o":"Und um eine Leitlinie zu finden, nimmt es als zweiten fixen Punkt Vater oder Mutter, die es nun mit allen Kräften dieser Welt ausstattet.","l":"de","ob":"El carácter neurótico","an":"1912 (2.ª ed. 1922)","u":"","te":["familia","infancia"]},{"i":"alfred-adler-037","a":"alfred-adler","t":"Las satisfacciones infantiles del afán de poder se vuelven así un modelo y refuerzan la línea directriz.","o":"Die kindlichen Befriedigungen des Machtstrebens werden so vorbildlich und verstärken die Leitlinie.","l":"de","ob":"El carácter neurótico","an":"1912 (2.ª ed. 1922)","u":"","te":["poder","infancia","repeticion"]},{"i":"alfred-adler-038","a":"alfred-adler","t":"También la persona sana tendría que renunciar a orientarse en el mundo si no ordenara su imagen del mundo y su experiencia según ficciones.","o":"Der Gesunde müsste ebenfalls auf die Orientierung in der Welt verziehten, wenn er nicht nach Fiktionen das Weltbild und sein Erleben einordnete.","l":"de","ob":"El carácter neurótico","an":"1912 (2.ª ed. 1922)","u":"","te":["conocimiento","salud-mental"]},{"i":"alfred-adler-039","a":"alfred-adler","t":"Estas impresiones, que surgen necesariamente de un sentimiento originario de inferioridad, generan una actitud agresiva cuyo fin es superar la inseguridad.","o":"Diese Eindrücke, die sich aus einem ursprünglichen Gefühl der Minderwertigkeit mit Notwendigkeit herausheben, rufen eine Aggressionsstellung ins Leben, deren Zweck die Überwindung der Unsicherheit ist.","l":"de","ob":"El carácter neurótico","an":"1912 (2.ª ed. 1922)","u":"","te":["ira","autoestima","incertidumbre"]},{"i":"alfred-adler-040","a":"alfred-adler","t":"Al superar esta dificultad que él mismo arregló y creó, busca y encuentra una vez más la elevación de su sentimiento de sí.","o":"In der Überwindung dieser arrangierten, selbstgeschaffenen Schwierigkeit sucht und findet er noch einmal die Erhöhung seines Persönlichkeit^gefühls.","l":"de","ob":"El carácter neurótico","an":"1912 (2.ª ed. 1922)","u":"","te":["autoestima","repeticion"]},{"i":"alfred-adler-041","a":"alfred-adler","t":"La crisis neurótica, comparable a una lucha por el poder, tiene la función de proteger el sentimiento de sí de las humillaciones.","o":"Der neurotische Anfall endlich, dem Kampf um die Macht vergleichbar, hat die Aufgabe, das Persönlichkeitsgefühl vor Herabsetzungen zu bewahren.","l":"de","ob":"El carácter neurótico","an":"1912 (2.ª ed. 1922)","u":"","te":["salud-mental","autoestima"]},{"i":"alfred-adler-042","a":"alfred-adler","t":"El fin ficticio del afán de poder adquiere así una influencia enorme y arrastra en su dirección todas las fuerzas psíquicas.","o":"Dabei kommt der fiktive Endzweck des Machtstrebens zu ungeheurem Einfluss und zieht alle psychischen Kräfte in seine Richtung.","l":"de","ob":"El carácter neurótico","an":"1912 (2.ª ed. 1922)","u":"","te":["poder","inconsciente"]},{"i":"alfred-adler-043","a":"alfred-adler","t":"La realidad se desvaloriza en distinto grado, y los caminos correctores, adaptados a la comunidad, resultan cada vez más insuficientes.","o":"Die Realität wird dabei in verschiedenem Grade entwertet, und die korrigierenden, der Gemeinschaft angepassten Bahnen erweisen sich immer mehr als insuffizient.","l":"de","ob":"El carácter neurótico","an":"1912 (2.ª ed. 1922)","u":"","te":["salud-mental","sociedad"]},{"i":"alfred-adler-044","a":"alfred-adler","t":"La angustia aparece con frecuencia; a menudo sirve para demostrar que uno no puede estar solo.","o":"Angst findet sich häufig; sie dient oft dem Beweise, dass man nicht allein sein könne.","l":"de","ob":"El carácter neurótico","an":"1912 (2.ª ed. 1922)","u":"","te":["angustia","soledad","vinculos"]},{"i":"alfred-adler-045","a":"alfred-adler","t":"Hacia el final de la lactancia, la terquedad y el negativismo infantil ya pueden estar claramente desarrollados.","o":"Gegen Ende der Säuglingszeit kann der Trotz und der kindliche Negativismus schon deutlich entwickelt sein.","l":"de","ob":"El carácter neurótico","an":"1912 (2.ª ed. 1922)","u":"","te":["infancia","desarrollo-humano"]},{"i":"alfred-adler-046","a":"alfred-adler","t":"Es fácil entender que se vuelvan incapaces de amor y de amistad.","o":"Dass sie zur Liebe und zur Freundschaft unfähig werden, ist leicht zu verstehen.","l":"de","ob":"El carácter neurótico","an":"1912 (2.ª ed. 1922)","u":"","te":["amor","amistad"]},{"i":"alfred-adler-047","a":"alfred-adler","t":"El arreglo se ve con más claridad en el alcoholismo y en la adicción a la morfina y a la cocaína, que solo se curan del todo cuando crece el sentimiento de comunidad y disminuye la vanidad.","o":"Am deutlichsten ist das Arrangement bei Alkoholismus, Morphinismus und Kokainismus, die restlos nur heilen, wenn das Gemeinschaftsgefühl wächst und die Eitelkeit abnimmt.","l":"de","ob":"El carácter neurótico","an":"1912 (2.ª ed. 1922)","u":"","te":["salud-mental","vinculos","terapia"]},{"i":"alfred-adler-048","a":"alfred-adler","t":"Con razón puede dudarse de que, en personas sanas, el amor sea capaz de semejante transformación [en odio].","o":"Es ist mit Recht zu bezweifeln, dass Liebe bei gesunden Menschen einer solchen Umwandlung fähig wäre.","l":"de","ob":"El carácter neurótico","an":"1912 (2.ª ed. 1922)","u":"","te":["amor","ira"]},{"i":"alfred-adler-049","a":"alfred-adler","t":"En general sería demasiado doloroso reconocerse a sí mismo el “amor rechazado”.","o":"Es wäre in der Regel zu schmerzhaft, sich die \"verschmähte Liebe\" einzugestehen.","l":"de","ob":"El carácter neurótico","an":"1912 (2.ª ed. 1922)","u":"","te":["amor","perdida","inconsciente"]},{"i":"alfred-adler-050","a":"alfred-adler","t":"Como motivo siempre disponible para nuevos estallidos y presiones queda todavía el pasado, el recuerdo de privaciones anteriores.","o":"Als stets bereiter Anlass zu erneuten Heftigkeiten und Bedrängungen bleibt immer noch die Vergangenheit und die Erinnerung an frühere Entbehrungen","l":"de","ob":"El carácter neurótico","an":"1912 (2.ª ed. 1922)","u":"","te":["memoria","ira","repeticion"]},{"i":"alfred-adler-051","a":"alfred-adler","t":"Nuestra investigación nos llevó a comprender cómo, a partir de la inferioridad absoluta del niño, [se desarrolla una valoración de sí que produce el sentimiento de inferioridad].","o":"Unsere Betrachtung hat uns dahingeführt zu verstehen, wie sich aus der absoluten Minderwertigkeit des Kindes","l":"de","ob":"El carácter neurótico","an":"1912 (2.ª ed. 1922)","u":"","te":["infancia","autoestima"]},{"i":"platon-012","a":"platon","t":"El comienzo es la parte más importante de cualquier obra, sobre todo cuando se trata de algo joven y tierno.","o":"the beginning is the most important part of any work, especially in the case of a young and tender thing","l":"en","ob":"La República","an":"c. 375 a. C.","u":"Libro 2","te":["infancia","educacion"]},{"i":"platon-013","a":"platon","t":"La ciudad donde los gobernantes tienen menos ganas de gobernar es siempre la mejor y la más tranquila; aquella donde más lo desean, la peor.","o":"the State in which the rulers are most reluctant to govern is always the best and most quietly governed, and the State in which they are most eager, the worst.","l":"en","ob":"La República","an":"c. 375 a. C.","u":"Libro 7","te":["poder","sociedad"]},{"i":"platon-014","a":"platon","t":"Hasta que los filósofos sean reyes, o los reyes y príncipes de este mundo tengan el espíritu y la fuerza de la filosofía…","o":"Until philosophers are kings, or the kings and princes of this world have the spirit and power of philosophy","l":"en","ob":"La República","an":"c. 375 a. C.","u":"Libro 5","te":["poder","sociedad"]},{"i":"platon-015","a":"platon","t":"El ejercicio físico, aunque sea obligatorio, no daña el cuerpo; pero el conocimiento adquirido por obligación no echa raíces en la mente.","o":"Bodily exercise, when compulsory, does no harm to the body; but knowledge which is acquired under compulsion obtains no hold on the mind.","l":"en","ob":"La República","an":"c. 375 a. C.","u":"Libro 7","te":["educacion","libertad"]},{"i":"platon-016","a":"platon","t":"El alma es como el ojo: cuando se posa sobre aquello en que brillan la verdad y el ser, percibe, comprende y resplandece de inteligencia.","o":"And the soul is like the eye: when resting upon that on which truth and being shine, the soul perceives and understands, and is radiant with intelligence","l":"en","ob":"La República","an":"c. 375 a. C.","u":"Libro 6","te":["verdad","conciencia"]},{"i":"platon-017","a":"platon","t":"Quien tiene un carácter sereno y alegre apenas siente el peso de la vejez; para quien tiene el carácter opuesto, juventud y vejez son igualmente una carga.","o":"for he who is of a calm and happy nature will hardly feel the pressure of age, but to him who is of an opposite disposition youth and age are equally a burden.","l":"en","ob":"La República","an":"c. 375 a. C.","u":"","te":["desarrollo-humano","felicidad"]},{"i":"platon-018","a":"platon","t":"Mirá: seres humanos que viven en una caverna subterránea…","o":"Behold! human beings living in a underground den","l":"en","ob":"La República","an":"c. 375 a. C.","u":"Libro 7","te":["conocimiento","verdad"]},{"i":"platon-019","a":"platon","t":"Para ellos, la verdad no sería otra cosa que las sombras de las imágenes.","o":"To them, I said, the truth would be literally nothing but the shadows of the images.","l":"en","ob":"La República","an":"c. 375 a. C.","u":"Libro 7","te":["verdad","conocimiento"]},{"i":"platon-020","a":"platon","t":"El verdadero creador es la necesidad, que es la madre de nuestra invención.","o":"the true creator is necessity, who is the mother of our invention","l":"en","ob":"La República","an":"c. 375 a. C.","u":"Libro 2","te":["creatividad"]},{"i":"platon-021","a":"platon","t":"La formación musical es el instrumento más poderoso, porque el ritmo y la armonía penetran en lo más íntimo del alma.","o":"musical training is a more potent instrument than any other, because rhythm and harmony find their way into the inward places of the soul","l":"en","ob":"La República","an":"c. 375 a. C.","u":"Libro 3","te":["educacion","cultura"]},{"i":"platon-022","a":"platon","t":"La virtud es libre.","o":"Virtue is free","l":"en","ob":"La República","an":"c. 375 a. C.","u":"Libro 10","te":["libertad","responsabilidad"]},{"i":"platon-023","a":"platon","t":"Una fe inquebrantable en la verdad y en lo justo.","o":"adamantine faith in truth and right","l":"en","ob":"La República","an":"c. 375 a. C.","u":"Libro 10","te":["verdad","esperanza"]},{"i":"platon-024","a":"platon","t":"¿No es el amor por aprender amor por la sabiduría, es decir, filosofía?","o":"is not the love of learning the love of wisdom, which is philosophy?","l":"en","ob":"La República","an":"c. 375 a. C.","u":"Libro 2","te":["educacion","conocimiento"]},{"i":"platon-025","a":"platon","t":"En el cielo, respondí, hay un modelo de ella [la ciudad justa]: quien lo desee puede contemplarlo y, contemplándolo, poner en orden su propia casa.","o":"In heaven, I replied, there is laid up a pattern of it, methinks, which he who desires may behold, and beholding, may set his own house in order.","l":"en","ob":"La República","an":"c. 375 a. C.","u":"Libro 9","te":["transformacion-personal","sentido-de-vida"]},{"i":"platon-001","a":"platon","t":"Una vida sin examen no merece ser vivida.","o":"the unexamined life is not worth living","l":"en","ob":"Apología de Sócrates","an":"c. 399–390 a. C.","u":"","te":["autoconocimiento","sentido-de-vida"]},{"i":"platon-002","a":"platon","t":"Él no sabe nada y cree que sabe; yo ni sé ni creo saber.","o":"he knows nothing, and thinks that he knows; I neither know nor think that I know.","l":"en","ob":"Apología de Sócrates","an":"c. 399–390 a. C.","u":"","te":["conocimiento","autoconocimiento"]},{"i":"platon-003","a":"platon","t":"Llegó la hora de partir y seguimos nuestros caminos: yo, a morir; ustedes, a vivir. Cuál es mejor, solo lo sabe el dios.","o":"The hour of departure has arrived, and we go our ways-I to die, and you to live. Which is better God only knows.","l":"en","ob":"Apología de Sócrates","an":"c. 399–390 a. C.","u":"","te":["muerte","incertidumbre"]},{"i":"platon-004","a":"platon","t":"Temer a la muerte es aparentar una sabiduría que no se tiene: es creer saber lo que no se sabe.","o":"For the fear of death is indeed the pretence of wisdom, and not real wisdom, being a pretence of knowing the unknown","l":"en","ob":"Apología de Sócrates","an":"c. 399–390 a. C.","u":"","te":["muerte","miedo","conocimiento"]},{"i":"platon-005","a":"platon","t":"Sepan con certeza que a un hombre bueno no puede sucederle ningún mal, ni en vida ni después de muerto.","o":"know of a certainty, that no evil can happen to a good man, either in life or after death.","l":"en","ob":"Apología de Sócrates","an":"c. 399–390 a. C.","u":"","te":["muerte","esperanza"]},{"i":"platon-006","a":"platon","t":"[Soy] una especie de tábano que el dios le dio a la ciudad.","o":"am a sort of gadfly, given to the state by God","l":"en","ob":"Apología de Sócrates","an":"c. 399–390 a. C.","u":"","te":["sociedad","verdad"]},{"i":"platon-007","a":"platon","t":"Sé que no tengo sabiduría, ni pequeña ni grande.","o":"for I know that I have no wisdom, small or great.","l":"en","ob":"Apología de Sócrates","an":"c. 399–390 a. C.","u":"","te":["conocimiento","autenticidad"]},{"i":"platon-008","a":"platon","t":"Prefiero morir habiendo hablado a mi manera que vivir hablando a la de ustedes.","o":"I would rather die having spoken after my manner, than speak in your manner and live.","l":"en","ob":"Apología de Sócrates","an":"c. 399–390 a. C.","u":"","te":["autenticidad","libertad"]},{"i":"platon-009","a":"platon","t":"Lo difícil, amigos, no es escapar de la muerte, sino de la injusticia, que corre más rápido que la muerte.","o":"the difficulty, my friends, is not to avoid death, but to avoid unrighteousness; for that runs faster than death.","l":"en","ob":"Apología de Sócrates","an":"c. 399–390 a. C.","u":"","te":["responsabilidad","muerte"]},{"i":"platon-010","a":"platon","t":"Un hombre que valga algo no debe calcular las probabilidades de vivir o morir.","o":"a man who is good for anything ought not to calculate the chance of living or dying","l":"en","ob":"Apología de Sócrates","an":"c. 399–390 a. C.","u":"","te":["responsabilidad","miedo"]},{"i":"platon-011","a":"platon","t":"Quienes me escuchan siempre imaginan que yo tengo la sabiduría que encuentro que les falta a otros.","o":"my hearers always imagine that I myself possess the wisdom which I find wanting in others","l":"en","ob":"Apología de Sócrates","an":"c. 399–390 a. C.","u":"","te":["conocimiento","identidad"]},{"i":"platon-026","a":"platon","t":"La naturaleza humana era en su origen una y éramos un todo: el deseo y la búsqueda de ese todo se llama amor.","o":"human nature was originally one and we were a whole, and the desire and pursuit of the whole is called love.","l":"en","ob":"El banquete","an":"c. 385–370 a. C.","u":"","te":["amor","deseo"]},{"i":"platon-027","a":"platon","t":"Solo el amor hace que hombres, y también mujeres, se atrevan a morir por quien aman.","o":"Love will make men dare to die for their beloved--love alone; and women as well as men.","l":"en","ob":"El banquete","an":"c. 385–370 a. C.","u":"","te":["amor"]},{"i":"platon-028","a":"platon","t":"El amor es amor de poseer el bien para siempre.","o":"love is of the everlasting possession of the good","l":"en","ob":"El banquete","an":"c. 385–370 a. C.","u":"","te":["amor","deseo"]},{"i":"platon-029","a":"platon","t":"Esa es, más que ninguna otra, la vida que el ser humano debe vivir: la contemplación de la belleza en sí.","o":"is that life above all others which man should live, in the contemplation of beauty absolute","l":"en","ob":"El banquete","an":"c. 385–370 a. C.","u":"","te":["trascendencia","sentido-de-vida"]},{"i":"platon-030","a":"platon","t":"El Amor es el más antiguo, el más noble y el más poderoso de los dioses.","o":"Love is the eldest and noblest and mightiest of the gods","l":"en","ob":"El banquete","an":"c. 385–370 a. C.","u":"","te":["amor"]},{"i":"platon-031","a":"platon","t":"Empezar por las bellezas de la tierra y subir hacia aquella otra belleza, usando estas solo como peldaños.","o":"to begin from the beauties of earth and mount upwards for the sake of that other beauty, using these as steps only","l":"en","ob":"El banquete","an":"c. 385–370 a. C.","u":"","te":["trascendencia","amor"]},{"i":"platon-032","a":"platon","t":"La sabiduría es lo más bello, y el Amor es amor de lo bello: por eso el Amor es también filósofo, amante de la sabiduría.","o":"For wisdom is a most beautiful thing, and Love is of the beautiful; and therefore Love is also a philosopher or lover of wisdom","l":"en","ob":"El banquete","an":"c. 385–370 a. C.","u":"","te":["amor","conocimiento"]},{"i":"platon-033","a":"platon","t":"[El Amor] es un gran espíritu (daimon) y, como todos los espíritus, está a medio camino entre lo divino y lo mortal.","o":"He is a great spirit (daimon), and like all spirits he is intermediate between the divine and the mortal.","l":"en","ob":"El banquete","an":"c. 385–370 a. C.","u":"","te":["amor","trascendencia"]},{"i":"platon-049","a":"platon","t":"No advierten que [el verdadero filósofo] no hace otra cosa que ocuparse de morir y de estar muerto.","o":"they do not perceive that he is always pursuing death and dying","l":"en","ob":"Fedón","an":"c. 380 a. C.","u":"","te":["muerte"]},{"i":"platon-050","a":"platon","t":"Los verdaderos filósofos, Simmias, se ejercitan siempre en morir; por eso a ellos, más que a nadie, la muerte no les resulta terrible.","o":"And the true philosophers, Simmias, are always occupied in the practice of dying, wherefore also to them least of all men is death terrible.","l":"en","ob":"Fedón","an":"c. 380 a. C.","u":"","te":["muerte","miedo"]},{"i":"platon-051","a":"platon","t":"El cuerpo nos da infinitas molestias por la sola necesidad de alimentarse.","o":"For the body is a source of endless trouble to us by reason of the mere requirement of food","l":"en","ob":"Fedón","an":"c. 380 a. C.","u":"","te":["cuerpo"]},{"i":"platon-052","a":"platon","t":"Critón, le debo un gallo a Asclepio: ¿te acordarás de pagar la deuda?","o":"Crito, I owe a cock to Asclepius; will you remember to pay the debt?","l":"en","ob":"Fedón","an":"c. 380 a. C.","u":"","te":["muerte","gratitud"]},{"i":"platon-053","a":"platon","t":"[De todos los hombres de su tiempo que conocí,] fue el más sabio, el más justo y el mejor.","o":"he was the wisest and justest and best.","l":"en","ob":"Fedón","an":"c. 380 a. C.","u":"","te":["duelo","amistad"]},{"i":"platon-039","a":"platon","t":"Querido Pan, y ustedes, los demás dioses de este lugar: concédanme ser bello por dentro, y que lo de afuera y lo de adentro estén en armonía.","o":"Beloved Pan, and all ye other gods who haunt this place, give me beauty in the inward soul; and may the outward and inward man be at one.","l":"en","ob":"Fedro","an":"c. 370 a. C.","u":"","te":["autenticidad","trascendencia"]},{"i":"platon-040","a":"platon","t":"Que la imagen sea compuesta: un par de caballos alados y un auriga.","o":"let the figure be composite--a pair of winged horses and a charioteer.","l":"en","ob":"Fedro","an":"c. 370 a. C.","u":"","te":["identidad","regulacion-emocional"]},{"i":"platon-041","a":"platon","t":"Este invento tuyo [la escritura] producirá olvido en las almas de quienes aprendan, porque dejarán de ejercitar la memoria.","o":"this discovery of yours will create forgetfulness in the learners' souls, because they will not use their memories","l":"en","ob":"Fedro","an":"c. 370 a. C.","u":"","te":["memoria","tecnologia"]},{"i":"platon-042","a":"platon","t":"Parecerán saberlo todo y en general no sabrán nada.","o":"they will appear to be omniscient and will generally know nothing","l":"en","ob":"Fedro","an":"c. 370 a. C.","u":"","te":["conocimiento","tecnologia"]},{"i":"platon-043","a":"platon","t":"El alma, en todo su ser, es inmortal.","o":"The soul through all her being is immortal","l":"en","ob":"Fedro","an":"c. 370 a. C.","u":"","te":["trascendencia"]},{"i":"platon-044","a":"platon","t":"Hay también una locura que es un don divino y fuente de los mayores bienes concedidos a los seres humanos.","o":"there is also a madness which is a divine gift, and the source of the chiefest blessings granted to men","l":"en","ob":"Fedro","an":"c. 370 a. C.","u":"","te":["creatividad","amor"]},{"i":"platon-034","a":"platon","t":"Lo que más hay que valorar no es vivir, sino vivir bien.","o":"not life, but a good life, is to be chiefly valued","l":"en","ob":"Critón","an":"c. 399–390 a. C.","u":"","te":["sentido-de-vida"]},{"i":"platon-035","a":"platon","t":"No debemos responder con represalias ni devolver mal por mal a nadie, sea cual sea el mal que nos haya hecho.","o":"we ought not to retaliate or render evil for evil to any one, whatever evil we may have suffered from him.","l":"en","ob":"Critón","an":"c. 399–390 a. C.","u":"","te":["ira","compasion"]},{"i":"platon-036","a":"platon","t":"No debemos atender a lo que dice de nosotros la mayoría, sino a lo que dirá quien entiende de lo justo y lo injusto, y a lo que dirá la verdad.","o":"we must not regard what the many say of us: but what he, the one man who has understanding of just and unjust, will say, and what the truth will say.","l":"en","ob":"Critón","an":"c. 399–390 a. C.","u":"","te":["autenticidad","verdad"]},{"i":"platon-037","a":"platon","t":"Seremos mejores, más valientes y menos impotentes si creemos que hay que investigar, que si nos entregamos a la ociosa fantasía de que no se puede saber ni vale la pena buscar lo que no sabemos.","o":"we shall be better and braver and less helpless if we think that we ought to enquire, than we should have been if we indulged in the idle fancy that there was no knowing and no use in seeking to know what we do not know","l":"en","ob":"Menón","an":"c. 385 a. C.","u":"","te":["conocimiento","educacion"]},{"i":"platon-038","a":"platon","t":"Toda búsqueda y todo aprendizaje no son más que recuerdo.","o":"for all enquiry and all learning is but recollection","l":"en","ob":"Menón","an":"c. 385 a. C.","u":"","te":["conocimiento","memoria"]},{"i":"platon-045","a":"platon","t":"El asombro es el sentimiento propio del filósofo, y la filosofía empieza con el asombro.","o":"for wonder is the feeling of a philosopher, and philosophy begins in wonder","l":"en","ob":"Teeteto","an":"c. 369 a. C.","u":"","te":["conocimiento","creatividad"]},{"i":"platon-046","a":"platon","t":"El triunfo de mi arte está en examinar a fondo si el pensamiento que da a luz la mente del joven es un ídolo falso o un parto noble y verdadero.","o":"the triumph of my art is in thoroughly examining whether the thought which the mind of the young man brings forth is a false idol or a noble and true birth.","l":"en","ob":"Teeteto","an":"c. 369 a. C.","u":"","te":["educacion","terapia","verdad"]},{"i":"platon-047","a":"platon","t":"Y como las parteras, yo soy estéril [de sabiduría].","o":"And like the midwives, I am barren","l":"en","ob":"Teeteto","an":"c. 369 a. C.","u":"","te":["conocimiento","terapia"]},{"i":"platon-048","a":"platon","t":"Debemos huir de la tierra al cielo lo antes posible; y huir es asemejarse a Dios en la medida de lo posible.","o":"we ought to fly away from earth to heaven as quickly as we can; and to fly away is to become like God, as far as this is possible","l":"en","ob":"Teeteto","an":"c. 369 a. C.","u":"","te":["trascendencia"]},{"i":"aristoteles-001","a":"aristoteles","t":"Así como una golondrina o un día de sol no hacen primavera, tampoco un día o un breve tiempo hacen a alguien dichoso y feliz.","o":"for as it is not one swallow or one fine day that makes a spring, so it is not one day or a short time that makes a man blessed and happy.","l":"en","ob":"Ética a Nicómaco","an":"s. IV a. C.","u":"","te":["felicidad","tiempo","habitos"]},{"i":"aristoteles-002","a":"aristoteles","t":"Haciendo actos justos nos volvemos justos; haciendo actos de dominio de nosotros mismos nos volvemos dueños de nosotros; y haciendo actos valientes [nos volvemos valientes].","o":"by doing just actions we come to be just; by doing the actions of self-mastery we come to be perfected in self-mastery; and by doing brave actions","l":"en","ob":"Ética a Nicómaco","an":"s. IV a. C.","u":"Libro 2","te":["habitos","transformacion-personal"]},{"i":"aristoteles-003","a":"aristoteles","t":"Las virtudes no nacen en nosotros por naturaleza ni contra la naturaleza: la naturaleza nos da la capacidad de recibirlas, y la costumbre las perfecciona.","o":"The Virtues then come to be in us neither by nature, nor in despite of nature, but we are furnished by nature with a capacity for receiving themu and are perfected in them through custom.","l":"en","ob":"Ética a Nicómaco","an":"s. IV a. C.","u":"Libro 2","te":["habitos","desarrollo-humano"]},{"i":"aristoteles-004","a":"aristoteles","t":"Tenemos razón al decir que estas virtudes se forman en una persona por hacer las acciones correspondientes.","o":"We are right then in saying, that these virtues are formed in a man by his doing the actions","l":"en","ob":"Ética a Nicómaco","an":"s. IV a. C.","u":"Libro 2","te":["habitos"]},{"i":"aristoteles-005","a":"aristoteles","t":"A quien alega no saber que los hábitos se forman a partir de actos sucesivos, le respondemos que esa ignorancia es señal de una torpeza excesiva.","o":"As for the plea, that a man did not know that habits are produced from separate acts of working, we reply, such ignorance is a mark of excessive stupidity.","l":"en","ob":"Ética a Nicómaco","an":"s. IV a. C.","u":"Libro 3","te":["habitos","responsabilidad"]},{"i":"aristoteles-006","a":"aristoteles","t":"De ahí la necesidad de haber sido bien educado en hábitos para estudiar con algún provecho los principios de lo noble, de lo justo y de la ética en general.","o":"Hence the necessity that he should have been well trained in habits, who is to study, with any tolerable chance of profit, the principles of nobleness and justice and moral philosophy generally.","l":"en","ob":"Ética a Nicómaco","an":"s. IV a. C.","u":"","te":["educacion","habitos"]},{"i":"aristoteles-007","a":"aristoteles","t":"La felicidad es, pues, evidentemente algo final y suficiente en sí mismo: el fin de todo lo que se hace y se puede hacer.","o":"So then Happiness is manifestly something final and self-sufficient, being the end of all things which are and may be done.","l":"en","ob":"Ética a Nicómaco","an":"s. IV a. C.","u":"","te":["felicidad","sentido-de-vida"]},{"i":"aristoteles-008","a":"aristoteles","t":"Aun en la desgracia brilla la nobleza cuando alguien soporta con serenidad muchos y grandes infortunios, no por insensibilidad al dolor, sino porque es noble y magnánimo.","o":"But still, even in these, nobleness shines through when a man bears contentedly many and great mischances not from insensibility to pain but because he is noble and high-spirited.","l":"en","ob":"Ética a Nicómaco","an":"s. IV a. C.","u":"","te":["resiliencia","sufrimiento"]},{"i":"aristoteles-009","a":"aristoteles","t":"[El placer] crece con todos nosotros desde la infancia; por eso es difícil quitarnos ese sentimiento, tan arraigado en nuestra vida.","o":"Again, it grows up with us all from infancy, and so it is a hard matter to remove from ourselves this feeling, engrained as it is into our very life.","l":"en","ob":"Ética a Nicómaco","an":"s. IV a. C.","u":"Libro 2","te":["deseo","infancia"]},{"i":"aristoteles-010","a":"aristoteles","t":"La ira y el miedo los sentimos sin elegirlos, mientras que las virtudes son actos de elección.","o":"Again, both anger and fear we feel without moral choice, whereas the virtues are acts of moral choice","l":"en","ob":"Ética a Nicómaco","an":"s. IV a. C.","u":"Libro 2","te":["emociones","ira","miedo","libertad"]},{"i":"aristoteles-011","a":"aristoteles","t":"La virtud ha de ser una disposición por la cual el ser humano llega a ser bueno y realiza bien su propia tarea.","o":"Virtue, must be a state whereby Man comes to be good and whereby he will perform well his proper work.","l":"en","ob":"Ética a Nicómaco","an":"s. IV a. C.","u":"Libro 2","te":["identidad","responsabilidad"]},{"i":"aristoteles-012","a":"aristoteles","t":"La virtud es, en cierto sentido, un término medio, ya que tiende a apuntar al justo medio.","o":"Virtue then is in a sense a mean state, since it certainly has an aptitude for aiming at the mean.","l":"en","ob":"Ética a Nicómaco","an":"s. IV a. C.","u":"Libro 2","te":["regulacion-emocional"]},{"i":"aristoteles-013","a":"aristoteles","t":"Por eso es difícil ser bueno: en cada caso es difícil encontrar el término medio, así como encontrar el centro de un círculo no es algo que cualquiera pueda hacer.","o":"And so it is hard to be good: for surely hard it is in each instance to find the mean, just as to find the mean point or centre of a circle is not what any man can do","l":"en","ob":"Ética a Nicómaco","an":"s. IV a. C.","u":"Libro 2","te":["regulacion-emocional","responsabilidad"]},{"i":"aristoteles-014","a":"aristoteles","t":"Tenemos una inclinación natural hacia los placeres; por eso nos inclinamos mucho más a abandonar todo control de nosotros mismos que a la disciplina.","o":"Thus we have a natural bias towards pleasures, for which reason we are much more inclined to the rejection of all self-control, than to self-discipline.","l":"en","ob":"Ética a Nicómaco","an":"s. IV a. C.","u":"Libro 2","te":["deseo","habitos"]},{"i":"aristoteles-015","a":"aristoteles","t":"En todos los casos hay que cuidarse sobre todo de lo agradable y del placer mismo, porque no somos jueces imparciales de él.","o":"But in all cases we must guard most carefully against what is pleasant, and pleasure itself, because we are not impartial judges of it.","l":"en","ob":"Ética a Nicómaco","an":"s. IV a. C.","u":"Libro 2","te":["deseo","autoconocimiento"]},{"i":"aristoteles-016","a":"aristoteles","t":"Es realmente absurdo atribuir las propias acciones a las cosas exteriores en lugar de a la propia facilidad para dejarse atrapar por ellas.","o":"It is truly absurd for a man to attribute his actions to external things instead of to his own capacity for being easily caught by them","l":"en","ob":"Ética a Nicómaco","an":"s. IV a. C.","u":"Libro 3","te":["responsabilidad","autoconocimiento"]},{"i":"aristoteles-017","a":"aristoteles","t":"Es posible temer estas cosas demasiado o demasiado poco, o temer lo que en realidad no es temible como si lo fuera.","o":"Now it is possible to fear these things too much, or too little, or again to fear what is not really fearful as if it were such.","l":"en","ob":"Ética a Nicómaco","an":"s. IV a. C.","u":"Libro 3","te":["miedo","angustia"]},{"i":"aristoteles-018","a":"aristoteles","t":"Los temerarios son precipitados: ansiosos antes del peligro, se derrumban cuando están en él; los valientes, en cambio, son rápidos y decididos en la acción, pero antes están tranquilos y serenos.","o":"The rash again are precipitate, and, being eager before danger, when actually in it fall away, while the Brave are quick and sharp in action, but before are quiet and composed.","l":"en","ob":"Ética a Nicómaco","an":"s. IV a. C.","u":"Libro 3","te":["miedo","resiliencia"]},{"i":"aristoteles-019","a":"aristoteles","t":"De ahí que el coraje implique dolor y sea justamente elogiado: es más difícil soportar lo doloroso que abstenerse de lo agradable.","o":"It follows that Courage involves pain and is justly praised, since it is a harder matter to withstand things that are painful than to abstain from such as are pleasant.","l":"en","ob":"Ética a Nicómaco","an":"s. IV a. C.","u":"Libro 3","te":["resiliencia","sufrimiento"]},{"i":"aristoteles-020","a":"aristoteles","t":"Si se encontrara a alguien que no disfrutara de nada y para quien todo diera igual, estaría lejos de ser humano.","o":"In fact, could a man be found who takes no pleasure in anything and to whom all things are alike, he would be far from being human at all","l":"en","ob":"Ética a Nicómaco","an":"s. IV a. C.","u":"Libro 3","te":["alegria","salud-mental"]},{"i":"aristoteles-021","a":"aristoteles","t":"Además, el dolor perturba y estropea la disposición natural de quien lo padece.","o":"And again, pain deranges and spoils the natural disposition of its victim","l":"en","ob":"Ética a Nicómaco","an":"s. IV a. C.","u":"Libro 3","te":["sufrimiento"]},{"i":"aristoteles-022","a":"aristoteles","t":"Es propio de él [el magnánimo] ser franco en lo que le gusta y en lo que le disgusta, porque el ocultamiento es consecuencia del miedo.","o":"It is a property of him also to be open, both in his dislikes and his likings, because concealment is a consequent of fear.","l":"en","ob":"Ética a Nicómaco","an":"s. IV a. C.","u":"Libro 4","te":["autenticidad","miedo","comunicacion"]},{"i":"aristoteles-023","a":"aristoteles","t":"Se elogia a quien se enoja por lo que corresponde y con quien corresponde, y además de la manera, en el momento y durante el tiempo adecuados.","o":"Now he who is angry at what and with whom he ought, and further, in right manner and time, and for proper length of time, is praised","l":"en","ob":"Ética a Nicómaco","an":"s. IV a. C.","u":"Libro 4","te":["ira","regulacion-emocional"]},{"i":"aristoteles-024","a":"aristoteles","t":"Ser apacible es ser imperturbable, no dejarse arrastrar por la pasión, sino enojarse de la manera, por las cosas y durante el tiempo que la razón indique.","o":"For the notion represented by the term Meek man is the being imperturbable, and not being led away by passion, but being angry in that manner, and at those things, and for that length of time, which Reason may direct.","l":"en","ob":"Ética a Nicómaco","an":"s. IV a. C.","u":"Libro 4","te":["ira","regulacion-emocional"]},{"i":"aristoteles-025","a":"aristoteles","t":"Y digerir el enojo dentro de uno lleva tiempo.","o":"and digesting anger within one's self takes time","l":"en","ob":"Ética a Nicómaco","an":"s. IV a. C.","u":"Libro 4","te":["ira","tiempo"]},{"i":"aristoteles-026","a":"aristoteles","t":"No es fácil definir cómo, con quién, por qué cosas y durante cuánto tiempo hay que enojarse, ni hasta qué punto se tiene razón o no.","o":"I mean, it is no easy matter to define how, and with what persons, and at what kind of things, and how long one ought to be angry, and up to what point a person is right or is wrong.","l":"en","ob":"Ética a Nicómaco","an":"s. IV a. C.","u":"Libro 4","te":["ira","regulacion-emocional"]},{"i":"aristoteles-027","a":"aristoteles","t":"Sin embargo, en general se considera que en la vida son indispensables cierto descanso y diversión.","o":"Yet some pause and amusement in life are generally judged to be indispensable.","l":"en","ob":"Ética a Nicómaco","an":"s. IV a. C.","u":"Libro 4","te":["alegria","humor","trabajo"]},{"i":"aristoteles-028","a":"aristoteles","t":"[La vergüenza] se define como “una especie de miedo al deshonor”, y sus efectos se parecen a los del miedo al peligro: quienes sienten vergüenza se ponen rojos, y quienes temen la muerte, pálidos.","o":"It is defined, we know, to be \"a kind of fear of disgrace,\" and its effects are similar to those of the fear of danger, for they who feel Shame grow red and they who fear death turn pale.","l":"en","ob":"Ética a Nicómaco","an":"s. IV a. C.","u":"Libro 4","te":["emociones","cuerpo","culpa"]},{"i":"aristoteles-029","a":"aristoteles","t":"En la pobreza y en todas las demás adversidades, se piensa que los amigos son el único refugio.","o":"in poverty moreover and all other adversities men think friends to be their only refuge.","l":"en","ob":"Ética a Nicómaco","an":"s. IV a. C.","u":"Libro 8","te":["amistad","resiliencia"]},{"i":"aristoteles-030","a":"aristoteles","t":"Además, la amistad parece ser el lazo de las comunidades, y los legisladores parecen preocuparse más por ella que por la justicia misma.","o":"Furthermore, Friendship seems to be the bond of Social Communities, and legislators seem to be more anxious to secure it than Justice even.","l":"en","ob":"Ética a Nicómaco","an":"s. IV a. C.","u":"Libro 8","te":["amistad","sociedad"]},{"i":"aristoteles-031","a":"aristoteles","t":"Al amigo, se dice, hay que desearle todo bien por él mismo.","o":"But to the friend they say one should wish all good for his sake.","l":"en","ob":"Ética a Nicómaco","an":"s. IV a. C.","u":"Libro 8","te":["amistad","amor"]},{"i":"aristoteles-032","a":"aristoteles","t":"Estas amistades son accidentales: no se quiere al otro por ser quien es, sino por la utilidad o el placer que brinda.","o":"These Friendships then are a matter of result: since the object is not beloved in that he is the man he is but in that he furnishes advantage or pleasure as the case may be.","l":"en","ob":"Ética a Nicómaco","an":"s. IV a. C.","u":"Libro 8","te":["amistad","vinculos"]},{"i":"aristoteles-033","a":"aristoteles","t":"Por eso [los jóvenes] hacen y deshacen amistades con rapidez: la amistad cambia con lo que les resulta agradable, y eso cambia pronto.","o":"This is the reason why they form and dissolve Friendships rapidly: since the Friendship changes with the pleasurable object and such pleasure changes quickly.","l":"en","ob":"Ética a Nicómaco","an":"s. IV a. C.","u":"Libro 8","te":["amistad","desarrollo-humano"]},{"i":"aristoteles-034","a":"aristoteles","t":"Es probable que estas amistades sean raras, porque las personas así son raras.","o":"Rare it is probable Friendships of this kind will be, because men of this kind are rare.","l":"en","ob":"Ética a Nicómaco","an":"s. IV a. C.","u":"Libro 8","te":["amistad"]},{"i":"aristoteles-035","a":"aristoteles","t":"Los sentimientos amistosos que mostramos hacia nuestros amigos parecen haber nacido de los que tenemos hacia nosotros mismos.","o":"Now the friendly feelings which are exhibited towards our friends, and by which Friendships are characterised, seem to have sprung out of those which we entertain toward ourselves.","l":"en","ob":"Ética a Nicómaco","an":"s. IV a. C.","u":"Libro 9","te":["amistad","autoestima"]},{"i":"aristoteles-036","a":"aristoteles","t":"[Hay que esforzarse por ser bueno,] porque así uno puede ser amigo de sí mismo y llegar a ser amigo de otro.","o":"because thus may he be friends with himself and may come to be a friend to another.","l":"en","ob":"Ética a Nicómaco","an":"s. IV a. C.","u":"Libro 9","te":["amistad","autoestima"]},{"i":"aristoteles-037","a":"aristoteles","t":"Y haber hecho posible que un amigo haga algo puede ser más noble que haberlo hecho uno mismo.","o":"and to have caused a friend's doing a thing may be more noble than having done it one's self.","l":"en","ob":"Ética a Nicómaco","an":"s. IV a. C.","u":"Libro 9","te":["amistad","compasion"]},{"i":"aristoteles-038","a":"aristoteles","t":"El amigo no es sino el nombre de otro yo.","o":"friend being but a name for a second Self","l":"en","ob":"Ética a Nicómaco","an":"s. IV a. C.","u":"Libro 9","te":["amistad","identidad"]},{"i":"aristoteles-039","a":"aristoteles","t":"Quien vaya a ser feliz, según lo entendemos, necesitará buenos amigos.","o":"The man therefore who is to come up to our notion \"Happy\" will need good Friends.","l":"en","ob":"Ética a Nicómaco","an":"s. IV a. C.","u":"Libro 9","te":["amistad","felicidad"]},{"i":"aristoteles-040","a":"aristoteles","t":"La sola presencia de los amigos es agradable incluso en la adversidad: cuando las personas sufren, las consuela la compañía de sus amigos.","o":"For the very presence of friends is pleasant even in adversity: since men when grieved are comforted by the sympathy of their friends.","l":"en","ob":"Ética a Nicómaco","an":"s. IV a. C.","u":"Libro 9","te":["amistad","duelo","resiliencia"]},{"i":"aristoteles-041","a":"aristoteles","t":"Quizás haya que cuidarse de no parecer huraño al rechazar el consuelo o la ayuda de los amigos.","o":"One should perhaps be cautious not to present the appearance of sullenness in declining the sympathy or help of friends","l":"en","ob":"Ética a Nicómaco","an":"s. IV a. C.","u":"Libro 9","te":["amistad","vinculos"]},{"i":"aristoteles-042","a":"aristoteles","t":"Y así se educa a los jóvenes, guiándolos con los timones del placer y del dolor.","o":"and so men train the young, guiding them on their course by the rudders of Pleasure and Pain.","l":"en","ob":"Ética a Nicómaco","an":"s. IV a. C.","u":"Libro 10","te":["educacion","emociones"]},{"i":"aristoteles-043","a":"aristoteles","t":"El placer perfecciona la actividad, y así también la vida, a la que todos aspiran.","o":"And Pleasure perfects the acts of Working, and so Life after which men grasp.","l":"en","ob":"Ética a Nicómaco","an":"s. IV a. C.","u":"Libro 10","te":["alegria","sentido-de-vida"]},{"i":"aristoteles-044","a":"aristoteles","t":"El placer completa la actividad no como algo que le es propio, sino como un acabado que se le suma, como la lozanía a quienes están en la flor de la edad.","o":"Furthermore, Pleasure perfects the act of Working not in the way of an inherent state but as a supervening finish, such as is bloom in people at their prime.","l":"en","ob":"Ética a Nicómaco","an":"s. IV a. C.","u":"Libro 10","te":["alegria","trabajo"]},{"i":"aristoteles-045","a":"aristoteles","t":"Si la felicidad es una actividad conforme a la excelencia, esa excelencia ha de ser la más alta: la de lo mejor que hay en nosotros.","o":"Now if Happiness is a Working in the way of Excellence of course that Excellence must be the highest, that is to say, the Excellence of the best Principle.","l":"en","ob":"Ética a Nicómaco","an":"s. IV a. C.","u":"Libro 10","te":["felicidad"]},{"i":"aristoteles-046","a":"aristoteles","t":"Las virtudes tienen que ver con acciones y sentimientos, y a todo sentimiento y a toda acción les siguen el placer o el dolor.","o":"Again: since Virtues have to do with actions and feelings, and on every feeling and every action pleasure and pain follow","l":"en","ob":"Ética a Nicómaco","an":"s. IV a. C.","u":"Libro 2","te":["emociones"]},{"i":"aristoteles-047","a":"aristoteles","t":"El ser humano es por naturaleza un animal político.","o":"that man is naturally a political animal","l":"en","ob":"Política","an":"s. IV a. C.","u":"cap. 2","te":["sociedad","vinculos"]},{"i":"aristoteles-048","a":"aristoteles","t":"Quien es incapaz de vivir en sociedad, o tan suficiente que no la necesita, no forma parte de la ciudad: es una bestia o un dios.","o":"he that is incapable of society, or so complete in himself as not to want it, makes no part of a city, as a beast or a god.","l":"en","ob":"Política","an":"s. IV a. C.","u":"cap. 2","te":["sociedad","soledad"]},{"i":"aristoteles-049","a":"aristoteles","t":"Pensamos que la amistad es el mayor bien que puede tener una ciudad, porque nada previene tanto las discordias.","o":"we think that friendship is the greatest good which can happen to any city, as nothing so much prevents seditions","l":"en","ob":"Política","an":"s. IV a. C.","u":"Libro 2, cap. 4","te":["amistad","sociedad"]},{"i":"aristoteles-050","a":"aristoteles","t":"[La tragedia,] mediante la compasión y el miedo, lleva a cabo la purificación (catarsis) de esas emociones.","o":"through pity and fear effecting the proper purgation of these emotions","l":"en","ob":"Poética","an":"s. IV a. C.","u":"","te":["emociones","cultura","terapia"]},{"i":"aristoteles-051","a":"aristoteles","t":"El instinto de imitación está implantado en el ser humano desde la infancia.","o":"the instinct of imitation is implanted in man from childhood","l":"en","ob":"Poética","an":"s. IV a. C.","u":"","te":["infancia","educacion"]},{"i":"aristoteles-052","a":"aristoteles","t":"La poesía es, por eso, más filosófica y más elevada que la historia.","o":"Poetry, therefore, is a more philosophical and a higher thing than history","l":"en","ob":"Poética","an":"s. IV a. C.","u":"","te":["cultura","creatividad"]},{"i":"epicteto-029","a":"epicteto","t":"Son las dificultades las que muestran quiénes son las personas.","o":"It is circumstances (difficulties) which show what men are.","l":"en","ob":"Disertaciones (selección)","an":"c. 108","u":"«How we should struggle with circumstances»","te":["resiliencia","identidad"]},{"i":"epicteto-030","a":"epicteto","t":"Nada grande, decía Epicteto, se produce de golpe: ni siquiera la uva o el higo.","o":"Nothing great, said Epictetus, is produced suddenly, since not even the grape or the fig is.","l":"en","ob":"Disertaciones (selección)","an":"c. 108","u":"«What philosophy promises»","te":["cambio","habitos"]},{"i":"epicteto-031","a":"epicteto","t":"La materia del arte de vivir es la vida de cada uno.","o":"so the matter of the art of living is each man's life.","l":"en","ob":"Disertaciones (selección)","an":"c. 108","u":"«What philosophy promises»","te":["sentido-de-vida","responsabilidad"]},{"i":"epicteto-032","a":"epicteto","t":"¿Dónde está el bien? En la voluntad. ¿Dónde está el mal? En la voluntad.","o":"Where is the good? In the will. Where is the evil? In the will.","l":"en","ob":"Disertaciones (selección)","an":"c. 108","u":"«That we do not strive to use our opinions about good and evil»","te":["voluntad","responsabilidad"]},{"i":"epicteto-033","a":"epicteto","t":"Es imposible empezar a aprender lo que uno cree que ya sabe.","o":"For it is impossible for a man to begin to learn that which he thinks that he knows.","l":"en","ob":"Disertaciones (selección)","an":"c. 108","u":"«How we must adapt preconceptions to particular cases»","te":["educacion","conocimiento"]},{"i":"epicteto-034","a":"epicteto","t":"Todo hábito y toda capacidad se mantienen y crecen con las acciones que les corresponden.","o":"Every habit and faculty is maintained and increased by the corresponding actions","l":"en","ob":"Disertaciones (selección)","an":"c. 108","u":"«How we should struggle against appearances»","te":["habitos"]},{"i":"epicteto-035","a":"epicteto","t":"Si querés ser un buen lector, leé; si querés ser escritor, escribí.","o":"If you would be a good reader, read; if a writer, write.","l":"en","ob":"Disertaciones (selección)","an":"c. 108","u":"«How we should struggle against appearances»","te":["habitos","educacion"]},{"i":"epicteto-036","a":"epicteto","t":"En general, si querés que algo se vuelva hábito, hacelo; si no querés, no lo hagas.","o":"Generally then if you would make anything a habit, do it; if you would not make it a habit, do not do it","l":"en","ob":"Disertaciones (selección)","an":"c. 108","u":"«How we should struggle against appearances»","te":["habitos","cambio"]},{"i":"epicteto-037","a":"epicteto","t":"El comienzo de la filosofía, para quien entra en ella como corresponde, es la conciencia de la propia debilidad e incapacidad en las cosas necesarias.","o":"The beginning of philosophy, to him at least who enters on it in the right way and by the door is a consciousness of his own weakness and inability about necessary things","l":"en","ob":"Disertaciones (selección)","an":"c. 108","u":"«What the beginning of philosophy is»","te":["autoconocimiento","conocimiento"]},{"i":"epicteto-038","a":"epicteto","t":"Es libre quien vive como quiere vivir, sin estar sometido a la coacción, al impedimento ni a la fuerza.","o":"He is free who lives as he wishes to live; who is neither subject to compulsion nor to hindrance, nor to force","l":"en","ob":"Disertaciones (selección)","an":"c. 108","u":"«About freedom»","te":["libertad"]},{"i":"epicteto-039","a":"epicteto","t":"Tengo que morir. ¿Tengo entonces que morir lamentándome? Me van a encadenar. ¿Tengo también que lamentarme?","o":"I must die. Must I then die lamenting? I must be put in chains. Must I then also lament?","l":"en","ob":"Disertaciones (selección)","an":"c. 108","u":"«Of the things which are in our power and not in our power»","te":["muerte","aceptacion","libertad"]},{"i":"epicteto-040","a":"epicteto","t":"Quien entiende qué es el bien sabe también amar.","o":"Whoever then understands what is good can also know how to love","l":"en","ob":"Disertaciones (selección)","an":"c. 108","u":"«On friendship»","te":["amor","amistad"]},{"i":"epicteto-041","a":"epicteto","t":"La soledad es la condición de una persona desamparada. Porque alguien esté solo no por eso está en soledad.","o":"Solitude is a certain condition of a helpless man. For because a man is alone, he is not for that reason also solitary","l":"en","ob":"Disertaciones (selección)","an":"c. 108","u":"«What solitude is, and what kind of person a solitary man is»","te":["soledad","vinculos"]},{"i":"epicteto-042","a":"epicteto","t":"Si sos alguien, caminá solo, hablá con vos mismo y no te escondas en el coro.","o":"Man, if you are anything, both walk alone and talk to yourself, and do not hide yourself in the chorus.","l":"en","ob":"Disertaciones (selección)","an":"c. 108","u":"«Certain miscellaneous matters»","te":["soledad","autenticidad","identidad"]},{"i":"epicteto-043","a":"epicteto","t":"Examinate un poco por fin, mirá a tu alrededor, sacudite, para saber quién sos.","o":"Examine a little at last, look around, stir yourself up, that you may know who you are.","l":"en","ob":"Disertaciones (selección)","an":"c. 108","u":"«Certain miscellaneous matters»","te":["autoconocimiento","identidad"]},{"i":"epicteto-044","a":"epicteto","t":"Quien trata con frecuencia con otros, para conversar, beber juntos o por la vida social, termina pareciéndose a ellos o haciéndolos parecidos a él.","o":"If a man has frequent intercourse with others either for talk, or drinking together, or generally for social purposes, he must either become like them, or change them to his own fashion.","l":"en","ob":"Disertaciones (selección)","an":"c. 108","u":"«That we ought with caution to enter into familiar intercourse with men»","te":["vinculos","amistad"]},{"i":"epicteto-045","a":"epicteto","t":"Las cosas en sí son indiferentes; el uso que hacemos de ellas, no.","o":"Things themselves (materials) are indifferent; but the use of them is not indifferent.","l":"en","ob":"Disertaciones (selección)","an":"c. 108","u":"«How magnanimity is consistent with care»","te":["responsabilidad"]},{"i":"epicteto-046","a":"epicteto","t":"Lo exterior no depende de mí; la voluntad, sí.","o":"Externals are not in my power: will is in my power.","l":"en","ob":"Disertaciones (selección)","an":"c. 108","u":"«How magnanimity is consistent with care»","te":["libertad","voluntad","aceptacion"]},{"i":"epicteto-047","a":"epicteto","t":"Para cada persona, la causa de sus actos es su opinión.","o":"For to every man the cause of his acting is opinion.","l":"en","ob":"Disertaciones (selección)","an":"c. 108","u":"«To a certain rhetorician who was going up to rome on a suit»","te":["conciencia","responsabilidad"]},{"i":"epicteto-048","a":"epicteto","t":"[Para alabar la Providencia hacen falta dos cosas:] la capacidad de ver lo que pertenece y sucede a todas las personas y cosas, y una disposición agradecida.","o":"the faculty of seeing what belongs and happens to all persons and things, and a grateful disposition","l":"en","ob":"Disertaciones (selección)","an":"c. 108","u":"«Of providence»","te":["gratitud","atencion"]},{"i":"epicteto-049","a":"epicteto","t":"Considerá quién sos.","o":"Consider who you are.","l":"en","ob":"Disertaciones (selección)","an":"c. 108","u":"«How we may discover the duties of life from names»","te":["identidad","autoconocimiento"]},{"i":"epicteto-050","a":"epicteto","t":"Además, sos ciudadano del mundo y parte de él.","o":"Further, you are a citizen of the world, and a part of it","l":"en","ob":"Disertaciones (selección)","an":"c. 108","u":"«How we may discover the duties of life from names»","te":["sociedad","conexion"]},{"i":"epicteto-051","a":"epicteto","t":"No debemos retroceder cuando estamos en el combate más grande: hasta hay que recibir golpes.","o":"For we must not shrink when we are engaged in the greatest combat, but we must even take blows.","l":"en","ob":"Disertaciones (selección)","an":"c. 108","u":"«From their purpose»","te":["resiliencia"]},{"i":"epicteto-052","a":"epicteto","t":"Creo que nadie tuvo una dificultad más provechosa que la tuya, si querés aprovecharla como un atleta a un rival joven.","o":"In my opinion no man has had a more profitable difficulty than you have had, if you choose to make use of it as an athlete would deal with a young antagonist.","l":"en","ob":"Disertaciones (selección)","an":"c. 108","u":"«How we should struggle with circumstances»","te":["resiliencia","sufrimiento"]},{"i":"epicteto-053","a":"epicteto","t":"La filosofía no promete conseguirle a nadie nada exterior.","o":"Philosophy does not propose to secure for a man any external thing.","l":"en","ob":"Disertaciones (selección)","an":"c. 108","u":"«What philosophy promises»","te":["sentido-de-vida","libertad"]},{"i":"epicteto-001","a":"epicteto","t":"De las cosas, unas dependen de nosotros y otras no.","o":"Of things some are in our power, and others are not.","l":"en","ob":"Manual (Enquiridión)","an":"c. 125","u":"§ 1","te":["libertad","aceptacion","responsabilidad"]},{"i":"epicteto-002","a":"epicteto","t":"Si amás una vasija de barro, decite que amás una vasija de barro: cuando se rompa, no te perturbará.","o":"If you love an earthen vessel, say it is an earthen vessel which you love; for when it has been broken you will not be disturbed.","l":"en","ob":"Manual (Enquiridión)","an":"c. 125","u":"§ 3","te":["perdida","aceptacion"]},{"i":"epicteto-003","a":"epicteto","t":"A los seres humanos no los perturban las cosas que suceden, sino las opiniones sobre las cosas.","o":"Men are disturbed not by the things which happen, but by the opinions about the things","l":"en","ob":"Manual (Enquiridión)","an":"c. 125","u":"§ 5","te":["sufrimiento","conciencia","regulacion-emocional"]},{"i":"epicteto-004","a":"epicteto","t":"Lo terrible es la opinión de que la muerte es terrible.","o":"for the opinion about death that it is terrible, is the terrible thing.","l":"en","ob":"Manual (Enquiridión)","an":"c. 125","u":"§ 5","te":["muerte","miedo"]},{"i":"epicteto-005","a":"epicteto","t":"No pretendas que las cosas sucedan como querés: querelas como suceden, y tu vida fluirá en calma.","o":"Seek not that the things which happen should happen as you wish; but wish the things which happen to be as they are, and you will have a tranquil flow of life.","l":"en","ob":"Manual (Enquiridión)","an":"c. 125","u":"§ 8","te":["aceptacion","felicidad"]},{"i":"epicteto-006","a":"epicteto","t":"La enfermedad es un impedimento para el cuerpo, pero no para la voluntad, a menos que ella misma lo elija.","o":"Disease is an impediment to the body, but not to the will, unless the will itself chooses.","l":"en","ob":"Manual (Enquiridión)","an":"c. 125","u":"§ 9","te":["cuerpo","libertad","resiliencia"]},{"i":"epicteto-007","a":"epicteto","t":"Ante cada cosa que te suceda, acordate de volver a vos y preguntarte qué capacidad tenés para aprovecharla.","o":"On the occasion of every accident (event) that befalls you, remember to turn to yourself and inquire what power you have for turning it to use.","l":"en","ob":"Manual (Enquiridión)","an":"c. 125","u":"§ 10","te":["resiliencia","responsabilidad"]},{"i":"epicteto-008","a":"epicteto","t":"Nunca digas de algo “lo perdí”, sino “lo devolví”.","o":"Never say about anything, I have lost it, but say I have restored it.","l":"en","ob":"Manual (Enquiridión)","an":"c. 125","u":"§ 11","te":["perdida","duelo","aceptacion"]},{"i":"epicteto-009","a":"epicteto","t":"Si querés progresar, aceptá que te consideren tonto e ignorante en las cosas exteriores.","o":"If you would improve, submit to be considered without sense and foolish with respect to externals.","l":"en","ob":"Manual (Enquiridión)","an":"c. 125","u":"§ 13","te":["autenticidad","transformacion-personal"]},{"i":"epicteto-010","a":"epicteto","t":"Recordá que en la vida tenés que comportarte como en un banquete.","o":"Remember that in life you ought to behave as at a banquet.","l":"en","ob":"Manual (Enquiridión)","an":"c. 125","u":"§ 15","te":["deseo","aceptacion"]},{"i":"epicteto-011","a":"epicteto","t":"Recordá que sos un actor en una obra, tal como el autor quiera que sea.","o":"Remember that thou art an actor in a play, of such a kind as the teacher (author) may choose","l":"en","ob":"Manual (Enquiridión)","an":"c. 125","u":"§ 17","te":["identidad","aceptacion"]},{"i":"epicteto-012","a":"epicteto","t":"Podés ser invencible si no entrás en ninguna contienda en la que vencer no dependa de vos.","o":"You can be invincible, if you enter into no contest in which it is not in your power to conquer.","l":"en","ob":"Manual (Enquiridión)","an":"c. 125","u":"§ 19","te":["libertad","resiliencia"]},{"i":"epicteto-013","a":"epicteto","t":"Recordá que no te ofende quien te insulta o te golpea, sino tu opinión de que eso es ofensivo.","o":"Remember that it is not he who reviles you or strikes you, who insults you, but it is your opinion about these things as being insulting.","l":"en","ob":"Manual (Enquiridión)","an":"c. 125","u":"§ 20","te":["ira","conciencia"]},{"i":"epicteto-014","a":"epicteto","t":"Cuando alguien te irrita, sabé que lo que te irritó es tu propia opinión.","o":"When then a man irritates you, you must know that it is your own opinion which has irritated you.","l":"en","ob":"Manual (Enquiridión)","an":"c. 125","u":"§ 20","te":["ira","regulacion-emocional"]},{"i":"epicteto-015","a":"epicteto","t":"Tené cada día ante los ojos la muerte, el exilio y todo lo que parece terrible, sobre todo la muerte: nunca pensarás nada mezquino ni desearás nada en exceso.","o":"Let death and exile and every other thing which appears dreadful be daily before your eyes; but most of all death: and you will never think of anything mean nor will you desire anything extravagantly.","l":"en","ob":"Manual (Enquiridión)","an":"c. 125","u":"§ 21","te":["muerte","deseo"]},{"i":"epicteto-016","a":"epicteto","t":"Si alguna vez te volcás hacia lo exterior para agradar a alguien, sabé que perdiste el rumbo de tu vida.","o":"If it should ever happen to you to be turned to externals in order to please some person, you must know that you have lost your purpose in life.","l":"en","ob":"Manual (Enquiridión)","an":"c. 125","u":"§ 23","te":["autenticidad","sentido-de-vida"]},{"i":"epicteto-017","a":"epicteto","t":"[Te indignaría que alguien entregara tu cuerpo a un desconocido;] pero que pongas tu mente en manos de cualquiera, de modo que si te insulta quede turbada, ¿no te avergüenza?","o":"but that you put your understanding in the power of any man whom you meet, so that if he should revile you, it is disturbed and troubled, are you not ashamed at this?","l":"en","ob":"Manual (Enquiridión)","an":"c. 125","u":"§ 28","te":["libertad","autoestima"]},{"i":"epicteto-018","a":"epicteto","t":"Que el silencio sea la regla general, o que se diga solo lo necesario y en pocas palabras.","o":"And let silence be the general rule, or let only what is necessary be said, and in few words.","l":"en","ob":"Manual (Enquiridión)","an":"c. 125","u":"§ 33","te":["silencio","comunicacion"]},{"i":"epicteto-019","a":"epicteto","t":"[Ante la impresión de un placer,] que la cosa te espere, y concedete cierta demora.","o":"but let the thing wait for you, and allow yourself a certain delay on your own part.","l":"en","ob":"Manual (Enquiridión)","an":"c. 125","u":"§ 34","te":["deseo","regulacion-emocional"]},{"i":"epicteto-020","a":"epicteto","t":"Cuando decidiste que algo debe hacerse y lo estás haciendo, no evites que te vean, aunque muchos opinen mal de ello.","o":"When you have decided that a thing ought to be done, and are doing it, never avoid being seen doing it, though the many shall form an unfavorable opinion about it.","l":"en","ob":"Manual (Enquiridión)","an":"c. 125","u":"§ 35","te":["autenticidad","responsabilidad"]},{"i":"epicteto-021","a":"epicteto","t":"Que todo tu cuidado se dirija a la mente.","o":"let all your care be directed to the mind.","l":"en","ob":"Manual (Enquiridión)","an":"c. 125","u":"§ 41","te":["autoconocimiento"]},{"i":"epicteto-022","a":"epicteto","t":"Cuando alguien te trata mal o habla mal de vos, recordá que lo hace o lo dice porque cree que es lo que corresponde.","o":"When any person treats you ill or speaks ill of you, remember that he does this or says this because he thinks that it is his duty.","l":"en","ob":"Manual (Enquiridión)","an":"c. 125","u":"§ 42","te":["vinculos","compasion","ira"]},{"i":"epicteto-023","a":"epicteto","t":"Todo tiene dos asas: una por la que se lo puede llevar y otra por la que no.","o":"Everything has two handles, the one by which it may be borne, the other by which it may not.","l":"en","ob":"Manual (Enquiridión)","an":"c. 125","u":"§ 43","te":["aceptacion","vinculos"]},{"i":"epicteto-024","a":"epicteto","t":"Antes de conocer su razón, ¿cómo sabés si obra mal?","o":"For before you shall have determined the opinion how do you know whether he is acting wrong?","l":"en","ob":"Manual (Enquiridión)","an":"c. 125","u":"§ 45","te":["vinculos","comunicacion"]},{"i":"epicteto-025","a":"epicteto","t":"En un banquete no digas cómo hay que comer: comé como se debe.","o":"at a banquet do not say how a man ought to eat, but eat as you ought to eat.","l":"en","ob":"Manual (Enquiridión)","an":"c. 125","u":"§ 46","te":["autenticidad","habitos"]},{"i":"epicteto-026","a":"epicteto","t":"Lo propio del filósofo es esto: espera de sí mismo todo beneficio y todo daño.","o":"The condition and characteristic of a philosopher is this: he expects all advantage and all harm from himself.","l":"en","ob":"Manual (Enquiridión)","an":"c. 125","u":"§ 48","te":["responsabilidad","libertad"]},{"i":"epicteto-027","a":"epicteto","t":"Y lo que digan de vos, no le prestes atención: no es asunto tuyo.","o":"And whatever any man shall say about you, do not attend to it; for this is no affair of yours.","l":"en","ob":"Manual (Enquiridión)","an":"c. 125","u":"§ 50","te":["autoestima","libertad"]},{"i":"epicteto-028","a":"epicteto","t":"Si querés que tus hijos, tu pareja y tus amigos vivan para siempre, sos un ingenuo.","o":"If you would have your children and your wife and your friends to live for ever, you are silly","l":"en","ob":"Manual (Enquiridión)","an":"c. 125","u":"§ 14","te":["muerte","aceptacion","vinculos"]},{"i":"baruch-spinoza-001","a":"baruch-spinoza","t":"Consideraré las acciones y los deseos humanos exactamente como si se tratara de líneas, planos y cuerpos.","o":"I shall consider human actions and desires in exactly the same manner, as though I were concerned with lines, planes, and solids.","l":"en","ob":"Ética demostrada según el orden geométrico","an":"1677","u":"Parte 3","te":["emociones","conocimiento"]},{"i":"baruch-spinoza-002","a":"baruch-spinoza","t":"Cada cosa, en cuanto está en sí, se esfuerza por perseverar en su ser.","o":"Everything, in so far as it is in itself, endeavours to persist in its own being.","l":"en","ob":"Ética demostrada según el orden geométrico","an":"1677","u":"Parte 3","te":["existencia","deseo"]},{"i":"baruch-spinoza-003","a":"baruch-spinoza","t":"Los seres humanos se creen libres porque son conscientes de sus voliciones y deseos, y en su ignorancia ni sueñan con las causas [que los determinan].","o":"men think themselves free inasmuch as they are conscious of their volitions and desires, and never even dream, in their ignorance, of the causes","l":"en","ob":"Ética demostrada según el orden geométrico","an":"1677","u":"Parte 1","te":["libertad","inconsciente","deseo"]},{"i":"baruch-spinoza-004","a":"baruch-spinoza","t":"Conscientes de sus acciones y apetitos, pero ignorantes de las causas que los determinan a desear algo en particular.","o":"conscious of their own actions and appetites, but ignorant of the causes whereby they are determined to any particular desire","l":"en","ob":"Ética demostrada según el orden geométrico","an":"1677","u":"Parte 4","te":["inconsciente","deseo"]},{"i":"baruch-spinoza-005","a":"baruch-spinoza","t":"El deseo es la esencia misma del ser humano.","o":"Desire is the actual essence of man","l":"en","ob":"Ética demostrada según el orden geométrico","an":"1677","u":"Parte 3","te":["deseo","identidad"]},{"i":"baruch-spinoza-006","a":"baruch-spinoza","t":"La alegría es el paso de una perfección menor a una mayor.","o":"Pleasure is the transition of a man from a less to a greater perfection.","l":"en","ob":"Ética demostrada según el orden geométrico","an":"1677","u":"Parte 3","te":["alegria","emociones"]},{"i":"baruch-spinoza-007","a":"baruch-spinoza","t":"La tristeza es el paso de una perfección mayor a una menor.","o":"Pain is the transition of a man from a greater to a less perfection.","l":"en","ob":"Ética demostrada según el orden geométrico","an":"1677","u":"Parte 3","te":["tristeza","emociones"]},{"i":"baruch-spinoza-008","a":"baruch-spinoza","t":"El amor no es sino una alegría acompañada de la idea de una causa exterior.","o":"Love is nothing else but pleasure accompanied by the idea of an external cause","l":"en","ob":"Ética demostrada según el orden geométrico","an":"1677","u":"Parte 3","te":["amor","emociones"]},{"i":"baruch-spinoza-009","a":"baruch-spinoza","t":"El odio es una tristeza acompañada de la idea de una causa exterior.","o":"Hatred is pain, accompanied by the idea of an external cause.","l":"en","ob":"Ética demostrada según el orden geométrico","an":"1677","u":"Parte 3","te":["ira","emociones"]},{"i":"baruch-spinoza-010","a":"baruch-spinoza","t":"La admiración es la imaginación de algo en que la mente se detiene, porque esa idea no tiene conexión con otras.","o":"Wonder is the conception (imaginatio) of anything, wherein the mind comes to a stand, because the particular concept in question has no connection with other concepts","l":"en","ob":"Ética demostrada según el orden geométrico","an":"1677","u":"Parte 3","te":["emociones","atencion"]},{"i":"baruch-spinoza-011","a":"baruch-spinoza","t":"La esperanza es una alegría inconstante, surgida de la idea de algo pasado o futuro de cuyo desenlace dudamos en alguna medida.","o":"Hope is an inconstant pleasure, arising from the idea of something past or future, whereof we to a certain extent doubt the issue.","l":"en","ob":"Ética demostrada según el orden geométrico","an":"1677","u":"Parte 3","te":["esperanza","incertidumbre","emociones"]},{"i":"baruch-spinoza-012","a":"baruch-spinoza","t":"El miedo es una tristeza inconstante, surgida de la idea de algo pasado o futuro de cuyo desenlace dudamos en alguna medida.","o":"Fear is an inconstant pain arising from the idea of something past or future, whereof we to a certain extent doubt the issue","l":"en","ob":"Ética demostrada según el orden geométrico","an":"1677","u":"Parte 3","te":["miedo","incertidumbre","emociones"]},{"i":"baruch-spinoza-013","a":"baruch-spinoza","t":"La seguridad es una alegría surgida de la idea de algo pasado o futuro del que se ha eliminado toda causa de duda.","o":"Confidence is pleasure arising from the idea of something past or future, wherefrom all cause of doubt has been removed.","l":"en","ob":"Ética demostrada según el orden geométrico","an":"1677","u":"Parte 3","te":["emociones","esperanza"]},{"i":"baruch-spinoza-014","a":"baruch-spinoza","t":"La desesperación es una tristeza surgida de la idea de algo pasado o futuro del que se ha eliminado toda causa de duda.","o":"Despair is pain arising from the idea of something past or future, wherefrom all cause of doubt has been removed.","l":"en","ob":"Ética demostrada según el orden geométrico","an":"1677","u":"Parte 3","te":["angustia","emociones"]},{"i":"baruch-spinoza-015","a":"baruch-spinoza","t":"La decepción es una tristeza acompañada de la idea de algo pasado que tuvo un desenlace contrario a nuestra esperanza.","o":"Disappointment is pain accompanied by the idea of something past, which has had an issue contrary to our hope.","l":"en","ob":"Ética demostrada según el orden geométrico","an":"1677","u":"Parte 3","te":["tristeza","emociones"]},{"i":"baruch-spinoza-016","a":"baruch-spinoza","t":"La conmiseración es una tristeza acompañada de la idea de un mal que le sucedió a otro que imaginamos semejante a nosotros.","o":"Pity is pain accompanied by the idea of evil, which has befallen someone else whom we conceive to be like ourselves","l":"en","ob":"Ética demostrada según el orden geométrico","an":"1677","u":"Parte 3","te":["empatia","compasion","emociones"]},{"i":"baruch-spinoza-017","a":"baruch-spinoza","t":"La envidia es odio en cuanto lleva a entristecerse por la dicha ajena y alegrarse por la desgracia ajena.","o":"Envy is hatred, in so far as it induces a man to be pained by another's good fortune, and to rejoice in another's evil fortune.","l":"en","ob":"Ética demostrada según el orden geométrico","an":"1677","u":"Parte 3","te":["emociones","vinculos"]},{"i":"baruch-spinoza-018","a":"baruch-spinoza","t":"La humildad es una tristeza que surge de contemplar la propia debilidad del cuerpo o de la mente.","o":"Humility is pain arising from a man's contemplation of his own weakness of body or mind.","l":"en","ob":"Ética demostrada según el orden geométrico","an":"1677","u":"Parte 3","te":["autoestima","emociones"]},{"i":"baruch-spinoza-019","a":"baruch-spinoza","t":"La soberbia es estimarse más de lo justo por amor de sí.","o":"Pride is thinking too highly of one's self from self--love.","l":"en","ob":"Ética demostrada según el orden geométrico","an":"1677","u":"Parte 3","te":["autoestima","emociones"]},{"i":"baruch-spinoza-020","a":"baruch-spinoza","t":"La vergüenza es una tristeza acompañada de la idea de alguna acción propia que creemos censurada por los demás.","o":"Shame is pain accompanied by the idea of some action of our own, which we believe to be blamed by others.","l":"en","ob":"Ética demostrada según el orden geométrico","an":"1677","u":"Parte 3","te":["culpa","emociones"]},{"i":"baruch-spinoza-021","a":"baruch-spinoza","t":"La añoranza es el deseo de poseer algo, mantenido vivo por su recuerdo y a la vez frenado por el recuerdo de otras cosas que excluyen su existencia.","o":"Regret is the desire or appetite to possess something, kept alive by the remembrance of the said thing, and at the same time constrained by the remembrance of other things which exclude the existence of it.","l":"en","ob":"Ética demostrada según el orden geométrico","an":"1677","u":"Parte 3","te":["duelo","memoria","emociones"]},{"i":"baruch-spinoza-022","a":"baruch-spinoza","t":"La emulación es el deseo de algo, engendrado en nosotros porque imaginamos que otros tienen el mismo deseo.","o":"Emulation is the desire of something, engendered in us by our conception that others have the same desire.","l":"en","ob":"Ética demostrada según el orden geométrico","an":"1677","u":"Parte 3","te":["deseo","vinculos"]},{"i":"baruch-spinoza-023","a":"baruch-spinoza","t":"El agradecimiento o gratitud es el deseo, nacido del amor, de hacer el bien a quien, con un afecto semejante, nos hizo bien.","o":"Thankfulness or Gratitude is the desire or zeal springing from love, whereby we endeavour to benefit him, who with similar feelings of love has conferred a benefit on us.","l":"en","ob":"Ética demostrada según el orden geométrico","an":"1677","u":"Parte 3","te":["gratitud","vinculos"]},{"i":"baruch-spinoza-024","a":"baruch-spinoza","t":"La ira es el deseo que, por odio, nos impulsa a dañar a quien odiamos.","o":"Anger is the desire, whereby through hatred we are induced to injure one whom we hate","l":"en","ob":"Ética demostrada según el orden geométrico","an":"1677","u":"Parte 3","te":["ira","emociones"]},{"i":"baruch-spinoza-025","a":"baruch-spinoza","t":"La venganza es el deseo que, por odio recíproco, nos impulsa a dañar a quien, con un afecto semejante, nos dañó.","o":"Revenge is the desire whereby we are induced, through mutual hatred, to injure one who, with similar feelings, has injured us.","l":"en","ob":"Ética demostrada según el orden geométrico","an":"1677","u":"Parte 3","te":["ira","vinculos"]},{"i":"baruch-spinoza-026","a":"baruch-spinoza","t":"La ambición es el deseo inmoderado de poder.","o":"Ambition is the immoderate desire of power.","l":"en","ob":"Ética demostrada según el orden geométrico","an":"1677","u":"Parte 3","te":["poder","deseo"]},{"i":"baruch-spinoza-027","a":"baruch-spinoza","t":"Un afecto que es una pasión deja de ser pasión en cuanto nos formamos de él una idea clara y distinta.","o":"An emotion, which is a passion, ceases to be a passion, as soon as we form a clear and distinct idea thereof.","l":"en","ob":"Ética demostrada según el orden geométrico","an":"1677","u":"Parte 5","te":["regulacion-emocional","autoconocimiento","terapia"]},{"i":"baruch-spinoza-028","a":"baruch-spinoza","t":"Un afecto solo puede ser reprimido o suprimido por otro afecto contrario y más fuerte.","o":"An emotion can only be controlled or destroyed by another emotion contrary thereto, and with more power for controlling emotion.","l":"en","ob":"Ética demostrada según el orden geométrico","an":"1677","u":"Parte 4","te":["regulacion-emocional","emociones"]},{"i":"baruch-spinoza-029","a":"baruch-spinoza","t":"Un afecto es tanto más fuerte cuantas más causas concurren a la vez para despertarlo.","o":"An emotion is stronger in proportion to the number of simultaneous concurrent causes whereby it is aroused.","l":"en","ob":"Ética demostrada según el orden geométrico","an":"1677","u":"Parte 5","te":["emociones"]},{"i":"baruch-spinoza-030","a":"baruch-spinoza","t":"Llamo servidumbre a la impotencia humana para moderar y reprimir los afectos.","o":"Human infirmity in moderating and checking the emotions I name bondage","l":"en","ob":"Ética demostrada según el orden geométrico","an":"1677","u":"Parte 4","te":["libertad","regulacion-emocional"]},{"i":"baruch-spinoza-031","a":"baruch-spinoza","t":"El odio aumenta cuando es correspondido y, en cambio, puede ser destruido por el amor.","o":"Hatred is increased by being reciprocated, and can on the other hand be destroyed by love.","l":"en","ob":"Ética demostrada según el orden geométrico","an":"1677","u":"Parte 3","te":["ira","amor"]},{"i":"baruch-spinoza-032","a":"baruch-spinoza","t":"El odio nunca puede ser bueno.","o":"Hatred can never be good.","l":"en","ob":"Ética demostrada según el orden geométrico","an":"1677","u":"Parte 4","te":["ira"]},{"i":"baruch-spinoza-033","a":"baruch-spinoza","t":"[Quien vive guiado por la razón] se esfuerza, en lo posible, por devolver amor o bondad al odio de los demás.","o":"endeavours, as far as possible, to render back love, or kindness, for other men's hatred","l":"en","ob":"Ética demostrada según el orden geométrico","an":"1677","u":"Parte 4","te":["compasion","ira"]},{"i":"baruch-spinoza-034","a":"baruch-spinoza","t":"Los afectos de esperanza y miedo no pueden ser buenos por sí mismos.","o":"Emotions of hope and fear cannot be in themselves good.","l":"en","ob":"Ética demostrada según el orden geométrico","an":"1677","u":"Parte 4","te":["esperanza","miedo"]},{"i":"baruch-spinoza-035","a":"baruch-spinoza","t":"La humildad no es una virtud, o no nace de la razón.","o":"Humility is not a virtue, or does not arise from reason.","l":"en","ob":"Ética demostrada según el orden geométrico","an":"1677","u":"Parte 4","te":["autoestima"]},{"i":"baruch-spinoza-036","a":"baruch-spinoza","t":"El contento de sí puede nacer de la razón, y el que nace de la razón es el más alto posible.","o":"Self--approval may arise from reason, and that which arises from reason is the highest possible.","l":"en","ob":"Ética demostrada según el orden geométrico","an":"1677","u":"Parte 4","te":["autoestima","felicidad"]},{"i":"baruch-spinoza-037","a":"baruch-spinoza","t":"En quien vive guiado por la razón, la conmiseración es en sí misma mala e inútil.","o":"Pity, in a man who lives under the guidance of reason, is in itself bad and useless.","l":"en","ob":"Ética demostrada según el orden geométrico","an":"1677","u":"Parte 4","te":["compasion"]},{"i":"baruch-spinoza-038","a":"baruch-spinoza","t":"Para el ser humano no hay nada más útil que otro ser humano.","o":"to man there is nothing more useful than man","l":"en","ob":"Ética demostrada según el orden geométrico","an":"1677","u":"Parte 4","te":["vinculos","sociedad"]},{"i":"baruch-spinoza-039","a":"baruch-spinoza","t":"El bien supremo de quienes siguen la virtud es común a todos, y por eso todos pueden gozarlo por igual.","o":"The highest good of those who follow virtue is common to all, and therefore all can equally rejoice therein.","l":"en","ob":"Ética demostrada según el orden geométrico","an":"1677","u":"Parte 4","te":["felicidad","sociedad"]},{"i":"baruch-spinoza-040","a":"baruch-spinoza","t":"Sin embargo, las almas no se vencen con las armas, sino con el amor y la generosidad.","o":"Yet minds are not conquered by force, but by love and high--mindedness.","l":"en","ob":"Ética demostrada según el orden geométrico","an":"1677","u":"Parte 4","te":["amor","poder"]},{"i":"baruch-spinoza-041","a":"baruch-spinoza","t":"El hombre libre en nada piensa menos que en la muerte, y su sabiduría es una meditación no de la muerte sino de la vida.","o":"A free man thinks of death least of all things; and his wisdom is a meditation not of death but of life.","l":"en","ob":"Ética demostrada según el orden geométrico","an":"1677","u":"Parte 4","te":["muerte","libertad","sentido-de-vida"]},{"i":"baruch-spinoza-042","a":"baruch-spinoza","t":"Quien sabe bien que todo se sigue de la necesidad de la naturaleza divina [no hallará nada digno de odio, risa o desprecio].","o":"He who rightly realizes, that all things follow from the necessity of the divine nature","l":"en","ob":"Ética demostrada según el orden geométrico","an":"1677","u":"Parte 4","te":["aceptacion","trascendencia"]},{"i":"baruch-spinoza-043","a":"baruch-spinoza","t":"El bien supremo de la mente es el conocimiento de Dios.","o":"The mind's highest good is the knowledge of God","l":"en","ob":"Ética demostrada según el orden geométrico","an":"1677","u":"Parte 4","te":["trascendencia","conocimiento"]},{"i":"baruch-spinoza-044","a":"baruch-spinoza","t":"Sentimos y experimentamos que somos eternos.","o":"we feel and know that we are eternal","l":"en","ob":"Ética demostrada según el orden geométrico","an":"1677","u":"Parte 5","te":["trascendencia","existencia"]},{"i":"baruch-spinoza-045","a":"baruch-spinoza","t":"La felicidad no es el premio de la virtud, sino la virtud misma.","o":"Blessedness is not the reward of virtue, but virtue itself","l":"en","ob":"Ética demostrada según el orden geométrico","an":"1677","u":"Parte 5","te":["felicidad"]},{"i":"baruch-spinoza-046","a":"baruch-spinoza","t":"Pero todo lo excelso es tan difícil como raro.","o":"But all things excellent are as difficult as they are rare.","l":"en","ob":"Ética demostrada según el orden geométrico","an":"1677","u":"Parte 5","te":["transformacion-personal","esperanza"]},{"i":"baruch-spinoza-047","a":"baruch-spinoza","t":"La devoción es amor hacia alguien a quien admiramos.","o":"Devotion is love towards one whom we admire.","l":"en","ob":"Ética demostrada según el orden geométrico","an":"1677","u":"Parte 3","te":["amor","emociones"]},{"i":"baruch-spinoza-048","a":"baruch-spinoza","t":"La indignación es odio hacia quien hizo mal a otro.","o":"Indignation is hatred towards one who has done evil to another.","l":"en","ob":"Ética demostrada según el orden geométrico","an":"1677","u":"Parte 3","te":["ira","sociedad"]},{"i":"baruch-spinoza-049","a":"baruch-spinoza","t":"La sobrestimación es estimar a alguien más de lo justo por el amor que le tenemos.","o":"Partiality is thinking too highly of anyone because of the love we bear him.","l":"en","ob":"Ética demostrada según el orden geométrico","an":"1677","u":"Parte 3","te":["amor","vinculos"]},{"i":"baruch-spinoza-050","a":"baruch-spinoza","t":"La benevolencia es el deseo de hacer bien a alguien que nos inspira conmiseración.","o":"Benevolence is the desire of benefiting one whom we pity.","l":"en","ob":"Ética demostrada según el orden geométrico","an":"1677","u":"Parte 3","te":["compasion"]},{"i":"baruch-spinoza-051","a":"baruch-spinoza","t":"La audacia es el deseo que impulsa a hacer algo peligroso que nuestros iguales temen intentar.","o":"Daring is the desire, whereby a man is set on to do something dangerous which his equals fear to attempt.","l":"en","ob":"Ética demostrada según el orden geométrico","an":"1677","u":"Parte 3","te":["miedo","voluntad"]},{"i":"immanuel-kant-001","a":"immanuel-kant","t":"La Ilustración es la salida del ser humano de su minoría de edad, de la que él mismo es culpable.","o":"Aufklärung ist der Ausgang des Menschen aus seiner selbst verschuldeten Unmündigkeit.","l":"de","ob":"Respuesta a la pregunta: ¿qué es la Ilustración?","an":"1784","u":"Capítulo 1","te":["libertad","transformacion-personal"]},{"i":"immanuel-kant-002","a":"immanuel-kant","t":"La minoría de edad es la incapacidad de servirse del propio entendimiento sin la guía de otro.","o":"Unmündigkeit ist das Unvermögen, sich seines Verstandes ohne Leitung eines anderen zu bedienen.","l":"de","ob":"Respuesta a la pregunta: ¿qué es la Ilustración?","an":"1784","u":"Capítulo 1","te":["libertad","desarrollo-humano"]},{"i":"immanuel-kant-003","a":"immanuel-kant","t":"Sapere aude: ¡tené el valor de servirte de tu propio entendimiento! Ese es el lema de la Ilustración.","o":"Sapere aude! Habe Mut dich deines eigenen Verstandes zu bedienen! ist also der Wahlspruch der Aufklärung.","l":"de","ob":"Respuesta a la pregunta: ¿qué es la Ilustración?","an":"1784","u":"Capítulo 1","te":["libertad","miedo","autenticidad"]},{"i":"immanuel-kant-004","a":"immanuel-kant","t":"La pereza y la cobardía son las causas por las que tantas personas [siguen gustosamente toda la vida en la minoría de edad].","o":"Faulheit und Feigheit sind die Ursachen, warum ein so großer Teil der Menschen","l":"de","ob":"Respuesta a la pregunta: ¿qué es la Ilustración?","an":"1784","u":"Capítulo 1","te":["libertad","miedo"]},{"i":"immanuel-kant-005","a":"immanuel-kant","t":"¡Es tan cómodo ser menor de edad!","o":"Es ist so bequem, unmündig zu sein.","l":"de","ob":"Respuesta a la pregunta: ¿qué es la Ilustración?","an":"1784","u":"Capítulo 1","te":["libertad","responsabilidad"]},{"i":"immanuel-kant-006","a":"immanuel-kant","t":"Si tengo un libro que piensa por mí, un director espiritual que tiene conciencia por mí, un médico que decide por mí la dieta… [no necesito esforzarme].","o":"Habe ich ein Buch, das für mich Verstand hat, einen Seelsorger, der für mich Gewissen hat, einen Arzt, der für mich die Diät beurteilt","l":"de","ob":"Respuesta a la pregunta: ¿qué es la Ilustración?","an":"1784","u":"Capítulo 1","te":["responsabilidad","libertad"]},{"i":"immanuel-kant-007","a":"immanuel-kant","t":"[Para la Ilustración solo hace falta la libertad] de hacer uso público de la propia razón en todos los asuntos.","o":"von seiner Vernunft in allen Stücken öffentlichen Gebrauch zu machen","l":"de","ob":"Respuesta a la pregunta: ¿qué es la Ilustración?","an":"1784","u":"Capítulo 1","te":["libertad","sociedad","comunicacion"]},{"i":"immanuel-kant-008","a":"immanuel-kant","t":"Que un público se ilustre a sí mismo es más bien posible; más aún, si se le deja libertad, es casi inevitable.","o":"Daß aber ein Publikum sich selbst aufkläre, ist eher möglich; ja es ist, wenn man ihm nur Freiheit läßt, beinahe unausbleiblich.","l":"de","ob":"Respuesta a la pregunta: ¿qué es la Ilustración?","an":"1784","u":"Capítulo 1","te":["libertad","sociedad"]},{"i":"immanuel-kant-009","a":"immanuel-kant","t":"No hay nada en el mundo, ni fuera de él, que pueda considerarse bueno sin restricción, salvo una buena voluntad.","o":"Es ist überall nichts in der Welt, ja überhaupt auch außer derselben zu denken möglich, was ohne Einschränkung für gut könnte gehalten werden, als allein ein guter Wille.","l":"de","ob":"Fundamentación de la metafísica de las costumbres","an":"1785","u":"Capítulo 3","te":["voluntad","responsabilidad"]},{"i":"immanuel-kant-010","a":"immanuel-kant","t":"Obrá solo según aquella máxima que puedas querer, al mismo tiempo, que se convierta en ley universal.","o":"Handle nur nach derjenigen Maxime, durch die du zugleich wollen kannst, dass sie ein allgemeines Gesetz werde.","l":"de","ob":"Fundamentación de la metafísica de las costumbres","an":"1785","u":"Capítulo 4","te":["responsabilidad"]},{"i":"immanuel-kant-011","a":"immanuel-kant","t":"¿Podés querer también que tu máxima se convierta en ley universal?","o":"Kannst du auch wollen, dass deine Maxime ein allgemeines Gesetz werde?","l":"de","ob":"Fundamentación de la metafísica de las costumbres","an":"1785","u":"Capítulo 3","te":["responsabilidad","autoconocimiento"]},{"i":"immanuel-kant-012","a":"immanuel-kant","t":"Obrá de tal modo que trates a la humanidad, tanto en tu persona como en la de cualquier otro, siempre a la vez como un fin y nunca solo como un medio.","o":"Handle so, dass du die Menschheit sowohl in deiner Person, als in der Person eines jeden andern jederzeit zugleich als Zweck, niemals bloß als Mittel brauchst.","l":"de","ob":"Fundamentación de la metafísica de las costumbres","an":"1785","u":"Capítulo 4","te":["vinculos","responsabilidad","sociedad"]},{"i":"immanuel-kant-013","a":"immanuel-kant","t":"En el reino de los fines, todo tiene un precio o una dignidad.","o":"Im Reiche der Zwecke hat alles entweder einen Preis, oder eine Würde.","l":"de","ob":"Fundamentación de la metafísica de las costumbres","an":"1785","u":"Capítulo 4","te":["identidad","sociedad"]},{"i":"immanuel-kant-014","a":"immanuel-kant","t":"Lo que tiene precio puede ser reemplazado por otra cosa equivalente; lo que está por encima de todo precio y no admite equivalente tiene dignidad.","o":"Was einen Preis hat, an dessen Stelle kann auch etwas anderes als Äquivalent gesetzt werden; was dagegen über allen Preis erhaben ist, mithin kein Äquivalent verstattet, das hat eine Würde.","l":"de","ob":"Fundamentación de la metafísica de las costumbres","an":"1785","u":"Capítulo 4","te":["identidad","autoestima"]},{"i":"immanuel-kant-015","a":"immanuel-kant","t":"La autonomía es, pues, el fundamento de la dignidad de la naturaleza humana y de toda naturaleza racional.","o":"Autonomie ist also der Grund der Würde der menschlichen und jeder vernünftigen Natur.","l":"de","ob":"Fundamentación de la metafísica de las costumbres","an":"1785","u":"Capítulo 4","te":["libertad","identidad"]},{"i":"immanuel-kant-016","a":"immanuel-kant","t":"Porque la felicidad no es un ideal de la razón, sino de la imaginación.","o":"weil Glückseligkeit nicht ein Ideal der Vernunft, sondern der Einbildungskraft ist","l":"de","ob":"Fundamentación de la metafísica de las costumbres","an":"1785","u":"Capítulo 4","te":["felicidad","deseo"]},{"i":"immanuel-kant-017","a":"immanuel-kant","t":"El deber es la necesidad de una acción por respeto a la ley.","o":"Pflicht ist die Notwendigkeit einer Handlung aus Achtung fürs Gesetz.","l":"de","ob":"Fundamentación de la metafísica de las costumbres","an":"1785","u":"Capítulo 3","te":["responsabilidad"]},{"i":"immanuel-kant-018","a":"immanuel-kant","t":"En rigor, el respeto es la representación de un valor que le pone freno a mi amor propio.","o":"Eigentlich ist Achtung die Vorstellung von einem Werte, der meiner Selbstliebe Abbruch tut.","l":"de","ob":"Fundamentación de la metafísica de las costumbres","an":"1785","u":"Capítulo 3","te":["vinculos","autoestima"]},{"i":"immanuel-kant-019","a":"immanuel-kant","t":"Conservan su vida conforme al deber, pero no por deber.","o":"Sie bewahren ihr Leben zwar pflichtmäßig aber nicht aus Pflicht.","l":"de","ob":"Fundamentación de la metafísica de las costumbres","an":"1785","u":"Capítulo 3","te":["responsabilidad"]},{"i":"immanuel-kant-020","a":"immanuel-kant","t":"[Ahí empieza el valor del carácter:] en hacer el bien no por inclinación, sino por deber.","o":"dass er wohltue, nicht aus Neigung, sondern aus Pflicht","l":"de","ob":"Fundamentación de la metafísica de las costumbres","an":"1785","u":"Capítulo 3","te":["responsabilidad","compasion"]},{"i":"immanuel-kant-021","a":"immanuel-kant","t":"Todos los seres humanos tienen por sí mismos la inclinación más poderosa e íntima hacia la felicidad.","o":"haben alle Menschen schon von selbst die mächtigste und innigste Neigung zur Glückseligkeit","l":"de","ob":"Fundamentación de la metafísica de las costumbres","an":"1785","u":"Capítulo 3","te":["felicidad","deseo"]},{"i":"immanuel-kant-022","a":"immanuel-kant","t":"La habilidad y la diligencia en el trabajo tienen un precio de mercado; el ingenio, la imaginación viva y el humor, un precio afectivo; en cambio, la fidelidad a lo prometido y la benevolencia por principios tienen un valor interior.","o":"Geschicklichkeit und Fleiß im Arbeiten haben einen Marktpreis; Witz, lebhafte Einbildungskraft und Launen einen Affektionspreis; dagegen Treue im Versprechen, Wohlwollen aus Grundsätzen (nicht aus Instinkt) haben einen innern Wert.","l":"de","ob":"Fundamentación de la metafísica de las costumbres","an":"1785","u":"Capítulo 4","te":["trabajo","vinculos","autenticidad"]},{"i":"immanuel-kant-023","a":"immanuel-kant","t":"Todo respeto por una persona es, en rigor, respeto por la ley [de la que nos da el ejemplo].","o":"Alle Achtung für eine Person ist eigentlich nur Achtung fürs Gesetz","l":"de","ob":"Fundamentación de la metafísica de las costumbres","an":"1785","u":"Capítulo 3","te":["vinculos"]},{"i":"immanuel-kant-024","a":"immanuel-kant","t":"Dos cosas llenan el ánimo de una admiración y un respeto siempre nuevos y crecientes, cuanto más a menudo y con más constancia se ocupa de ellas la reflexión: el cielo estrellado sobre mí y la ley moral en mí.","o":"Zwei Dinge erfüllen das Gemüt mit immer neuer und zunehmender Bewunderung und Ehrfurcht, je öfter und anhaltender sich das Nachdenken damit beschäftigt: Der bestirnte Himmel über mir, und das moralische Gesetz in mir.","l":"de","ob":"Crítica de la razón práctica","an":"1788","u":"Capítulo 34","te":["trascendencia","conciencia","naturaleza"]},{"i":"immanuel-kant-025","a":"immanuel-kant","t":"¡Deber! Nombre sublime y grande…","o":"Pflicht! du erhabener großer Name","l":"de","ob":"Crítica de la razón práctica","an":"1788","u":"Capítulo 17","te":["responsabilidad"]},{"i":"immanuel-kant-026","a":"immanuel-kant","t":"Pensar por uno mismo significa buscar en sí mismo, es decir, en la propia razón, la piedra de toque suprema de la verdad; y la máxima de pensar siempre por uno mismo es la Ilustración.","o":"Selbstdenken heißt den obersten Probierstein der Wahrheit in sich selbst (d. i. in seiner eigenen Vernunft) suchen; und die Maxime, jederzeit selbst zu denken, ist die Aufklärung.","l":"de","ob":"¿Qué significa orientarse en el pensamiento?","an":"1786","u":"Capítulo 2","te":["autenticidad","verdad","libertad"]},{"i":"immanuel-kant-027","a":"immanuel-kant","t":"Pero ¡cuánto y con qué acierto pensaríamos si no pensáramos, por así decir, en comunidad con otros a quienes comunicamos nuestros pensamientos y que nos comunican los suyos!","o":"Allein wie viel und mit welcher Richtigkeit würden wir wohl denken, wenn wir nicht gleichsam in Gemeinschaft mit andern, denen wir unsere und die uns ihre Gedanken mitteilen, dächten!","l":"de","ob":"¿Qué significa orientarse en el pensamiento?","an":"1786","u":"Capítulo 2","te":["comunicacion","encuentro","conocimiento"]},{"i":"immanuel-kant-028","a":"immanuel-kant","t":"La razón no siente: advierte su carencia y, mediante el impulso de conocer, produce el sentimiento de necesidad.","o":"Die Vernunft fühlt nicht; sie sieht ihren Mangel ein, und wirkt durch den Erkenntnistrieb das Gefühl des Bedürfnisses.","l":"de","ob":"¿Qué significa orientarse en el pensamiento?","an":"1786","u":"Capítulo 2","te":["emociones","conocimiento"]},{"i":"immanuel-kant-029","a":"immanuel-kant","t":"Y así, la libertad de pensamiento, si quiere proceder con total independencia de las leyes de la razón, termina destruyéndose a sí misma.","o":"Und so zerstört Freiheit im Denken, wenn sie so gar unabhängig von Gesetzen der Vernunft verfahren will, endlich sich selbst.","l":"de","ob":"¿Qué significa orientarse en el pensamiento?","an":"1786","u":"Capítulo 2","te":["libertad"]},{"i":"immanuel-kant-030","a":"immanuel-kant","t":"Se dice que un poder superior puede quitarnos la libertad de hablar o de escribir, pero de ningún modo la libertad de pensar.","o":"Zwar sagt man: die Freiheit zu sprechen oder zu schreiben, könne uns zwar durch obere Gewalt, aber die Freiheit zu denken durch sie gar nicht genommen werden.","l":"de","ob":"¿Qué significa orientarse en el pensamiento?","an":"1786","u":"Capítulo 2","te":["libertad","poder"]},{"i":"immanuel-kant-051","a":"immanuel-kant","t":"A la libertad de pensar se opone, en primer lugar, la coacción civil.","o":"Der Freiheit zu denken ist erstlich der bürgerliche Zwang entgegengesetzt.","l":"de","ob":"¿Qué significa orientarse en el pensamiento?","an":"1786","u":"Capítulo 2","te":["libertad","poder"]},{"i":"immanuel-kant-038","a":"immanuel-kant","t":"El estado de paz entre seres humanos que viven juntos no es un estado natural [hay que instaurarlo].","o":"Der Friedenszustand unter Menschen, die neben einander leben, ist kein Naturstand","l":"de","ob":"Sobre la paz perpetua","an":"1795","u":"Capítulo 4","te":["sociedad","vinculos"]},{"i":"immanuel-kant-039","a":"immanuel-kant","t":"El mundo no se va a hundir porque haya menos personas malas.","o":"Die Welt wird keinesweges dadurch untergehen, daß der bösen Menschen weniger wird.","l":"de","ob":"Sobre la paz perpetua","an":"1795","u":"Capítulo 9","te":["sociedad","humor"]},{"i":"immanuel-kant-040","a":"immanuel-kant","t":"Es el espíritu comercial el que no puede coexistir con la guerra.","o":"Es ist der Handelsgeist, der mit dem Kriege nicht zusammen bestehen kann","l":"de","ob":"Sobre la paz perpetua","an":"1795","u":"Capítulo 8","te":["sociedad"]},{"i":"immanuel-kant-031","a":"immanuel-kant","t":"Lo sublime conmueve; lo bello encanta.","o":"Das Erhabene rührt, das Schöne reizt.","l":"de","ob":"Observaciones sobre el sentimiento de lo bello y lo sublime","an":"1764","u":"Capítulo 2","te":["emociones","cultura"]},{"i":"immanuel-kant-032","a":"immanuel-kant","t":"La noche es sublime; el día es bello.","o":"Die Nacht ist erhaben, der Tag ist schön.","l":"de","ob":"Observaciones sobre el sentimiento de lo bello y lo sublime","an":"1764","u":"Capítulo 2","te":["naturaleza","emociones"]},{"i":"immanuel-kant-033","a":"immanuel-kant","t":"Las cualidades sublimes inspiran respeto; las bellas, amor.","o":"Erhabene Eigenschaften flößen Hochachtung, schöne aber Liebe ein.","l":"de","ob":"Observaciones sobre el sentimiento de lo bello y lo sublime","an":"1764","u":"Capítulo 3","te":["amor","vinculos"]},{"i":"immanuel-kant-034","a":"immanuel-kant","t":"La amistad tiene sobre todo el rasgo de lo sublime.","o":"Freundschaft hat hauptsächlich den Zug des Erhabenen.","l":"de","ob":"Observaciones sobre el sentimiento de lo bello y lo sublime","an":"1764","u":"Capítulo 3","te":["amistad"]},{"i":"immanuel-kant-035","a":"immanuel-kant","t":"Entre las cualidades morales, solo la verdadera virtud es sublime.","o":"In moralischen Eigenschaften ist wahre Tugend allein erhaben.","l":"de","ob":"Observaciones sobre el sentimiento de lo bello y lo sublime","an":"1764","u":"Capítulo 3","te":["autenticidad"]},{"i":"immanuel-kant-036","a":"immanuel-kant","t":"La veracidad y la honradez son sencillas y nobles; la broma y la lisonja amable son finas y bellas.","o":"Wahrhaftigkeit und Redlichkeit ist einfältig und edel, Scherz und gefällige Schmeichelei ist fein und schön.","l":"de","ob":"Observaciones sobre el sentimiento de lo bello y lo sublime","an":"1764","u":"Capítulo 3","te":["verdad","comunicacion"]},{"i":"immanuel-kant-037","a":"immanuel-kant","t":"Las bromas y la alegría pertenecen al sentimiento de lo bello.","o":"Scherze und Munterkeit schlagen in das Gefühl des Schönen ein.","l":"de","ob":"Observaciones sobre el sentimiento de lo bello y lo sublime","an":"1764","u":"Capítulo 3","te":["humor","alegria"]},{"i":"immanuel-kant-041","a":"immanuel-kant","t":"De una madera tan torcida como aquella de la que está hecho el ser humano no puede tallarse nada del todo recto.","o":"aus so krummem Holze, als woraus der Mensch gemacht ist, kann nichts ganz Gerades gezimmert werden.","l":"de","ob":"Idea de una historia universal en sentido cosmopolita","an":"1784","u":"Capítulo 1","te":["aceptacion","existencia"]},{"i":"immanuel-kant-042","a":"immanuel-kant","t":"Entiendo aquí por antagonismo la insociable sociabilidad del ser humano.","o":"Ich verstehe hier unter dem Antagonism die ungesellige Geselligkeit des Menschen","l":"de","ob":"Idea de una historia universal en sentido cosmopolita","an":"1784","u":"Capítulo 1","te":["vinculos","sociedad"]},{"i":"immanuel-kant-043","a":"immanuel-kant","t":"Del poder del ánimo para dominar sus sentimientos morbosos por la sola resolución.","o":"Von der Macht des Gemüths durch den bloßen Vorsatz seiner krankhaften Gefühle Meister zu sein.","l":"de","ob":"El conflicto de las facultades","an":"1798","u":"Capítulo 1","te":["regulacion-emocional","salud-mental"]},{"i":"immanuel-kant-044","a":"immanuel-kant","t":"Cuando lo asaltan angustias que amenazan convertirse en cavilaciones, es decir, en males imaginados, una persona razonable se pregunta si existe un objeto que las justifique.","o":"Ein vernünftiger Mensch statuirt keine solche Hypochondrie: sondern wenn ihm Beängstigungen anwandeln, die in Grillen, d.i. selbst ausgedachte Übel, ausschlagen wollen, so fragt er sich, ob ein Object derselben da sei.","l":"de","ob":"El conflicto de las facultades","an":"1798","u":"Capítulo 1","te":["angustia","regulacion-emocional","terapia"]},{"i":"immanuel-kant-045","a":"immanuel-kant","t":"[Por mi pecho estrecho tengo] una disposición natural a la hipocondría.","o":"eine natürliche Anlage zur Hypochondrie","l":"de","ob":"El conflicto de las facultades","an":"1798","u":"Capítulo 1","te":["salud-mental","cuerpo"]},{"i":"immanuel-kant-046","a":"immanuel-kant","t":"Pero llegué a dominar su influencia sobre mis pensamientos y acciones apartando la atención de ese sentimiento, como si no tuviera que ver conmigo.","o":"Aber über ihren Einfluß auf meine Gedanken und Handlungen bin ich Meister geworden durch Abkehrung der Aufmerksamkeit von diesem Gefühle, als ob es mich gar nicht anginge.","l":"de","ob":"El conflicto de las facultades","an":"1798","u":"Capítulo 1","te":["atencion","regulacion-emocional","salud-mental"]},{"i":"immanuel-kant-047","a":"immanuel-kant","t":"Uno se alegra más de la vida por lo que hace en el uso libre de ella que por lo que disfruta.","o":"da man des Lebens mehr froh wird durch das, was man im freien Gebrauch desselben thut, als was man genießt","l":"de","ob":"El conflicto de las facultades","an":"1798","u":"Capítulo 1","te":["sentido-de-vida","alegria","trabajo"]},{"i":"immanuel-kant-048","a":"immanuel-kant","t":"Para quien estudia, pensar es un alimento sin el cual, cuando está despierto y solo, no puede vivir.","o":"Einem Gelehrten ist das Denken ein Nahrungsmittel, ohne welches, wenn er wach und allein ist, er nicht leben kann","l":"de","ob":"El conflicto de las facultades","an":"1798","u":"Capítulo 1","te":["conocimiento","soledad"]},{"i":"immanuel-kant-049","a":"immanuel-kant","t":"Pensar con esfuerzo mientras se camina cansa enseguida; en cambio, si uno se entrega al libre juego de la imaginación, el movimiento repara.","o":"daß das angestrengte Denken im Gehen geschwinde matt macht; dagegen, wenn man sich dem freien Spiel der Einbildungskraft überläßt, die Motion restaurirend ist.","l":"de","ob":"El conflicto de las facultades","an":"1798","u":"Capítulo 1","te":["cuerpo","creatividad","habitos"]},{"i":"immanuel-kant-050","a":"immanuel-kant","t":"[El arte de cuidar la salud] es filosófico cuando el modo de vida lo determina solo el poder de la razón para dominar los sentimientos sensibles mediante un principio que uno mismo se da.","o":"Diese ist alsdann philosophisch, wenn bloß die Macht der Vernunft im Menschen, über seine sinnliche Gefühle durch einen sich selbst gegebenen Grundsatz Meister zu sein, die Lebensweise bestimmt.","l":"de","ob":"El conflicto de las facultades","an":"1798","u":"Capítulo 1","te":["habitos","regulacion-emocional","cuerpo"]},{"i":"arthur-schopenhauer-001","a":"arthur-schopenhauer","t":"Para el bienestar de una persona, y para toda su manera de existir, lo principal es evidentemente lo que hay o sucede dentro de ella misma.","o":"Allerdings ist für das Wohlsein des Menschen, ja für die ganze Weise seines Daseins die Hauptsache offenbar das, was in ihm selbst besteht, oder vergeht.","l":"de","ob":"Aforismos sobre el arte de vivir","an":"1851","u":"Capítulo 3","te":["felicidad","identidad"]},{"i":"arthur-schopenhauer-002","a":"arthur-schopenhauer","t":"Por eso la vida de cada persona, a pesar de todos los cambios exteriores, conserva siempre el mismo carácter: se parece a una serie de variaciones sobre un mismo tema.","o":"Demgemäß trägt das Leben jedes Menschen, trotz aller Abwechslung von außen, durchgängig denselben Charakter und ist einer Reihe Variationen auf ein Thema zu vergleichen.","l":"de","ob":"Aforismos sobre el arte de vivir","an":"1851","u":"Capítulo 3","te":["identidad","repeticion"]},{"i":"arthur-schopenhauer-003","a":"arthur-schopenhauer","t":"La salud supera tanto a todos los bienes exteriores que, en verdad, un mendigo sano es más feliz que un rey enfermo.","o":"Besonders überwiegt die Gesundheit alle äußeren Güter so sehr, daß wahrlich ein gesunder Bettler glücklicher ist, als ein kranker König.","l":"de","ob":"Aforismos sobre el arte de vivir","an":"1851","u":"Capítulo 3","te":["cuerpo","felicidad"]},{"i":"arthur-schopenhauer-004","a":"arthur-schopenhauer","t":"Un carácter bueno, moderado y apacible puede estar contento en circunstancias humildes, mientras que uno codicioso, envidioso y malo no lo está con toda su riqueza.","o":"Ein guter, gemäßigter, sanfter Charakter kann unter dürftigen Umständen zufrieden sein; während ein begehrlicher, neidischer und böser es bei allem Reichtum nicht ist.","l":"de","ob":"Aforismos sobre el arte de vivir","an":"1851","u":"Capítulo 3","te":["felicidad","deseo"]},{"i":"arthur-schopenhauer-005","a":"arthur-schopenhauer","t":"De aquí se sigue que desde afuera se puede influir en una persona mucho menos de lo que se cree.","o":"Hieraus nun folgt, daß dem Menschen von außen viel weniger beizukommen ist, als man wohl meint.","l":"de","ob":"Aforismos sobre el arte de vivir","an":"1851","u":"Capítulo 3","te":["identidad","resiliencia"]},{"i":"arthur-schopenhauer-006","a":"arthur-schopenhauer","t":"Lo que uno es para sí mismo, lo que lo acompaña en la soledad y nadie puede darle ni quitarle, es evidentemente más esencial que todo lo que pueda poseer o lo que pueda ser a los ojos de los demás.","o":"Denn was einer für sich selbst ist, was ihn in die Einsamkeit begleitet und was keiner ihm geben, oder nehmen kann, ist offenbar für ihn wesentlicher, als alles, was er besitzen, oder auch, was er in den Augen anderer sein mag.","l":"de","ob":"Aforismos sobre el arte de vivir","an":"1851","u":"Capítulo 3","te":["identidad","soledad","autoestima"]},{"i":"arthur-schopenhauer-007","a":"arthur-schopenhauer","t":"Una persona de espíritu encuentra, en completa soledad, una compañía excelente en sus propios pensamientos y fantasías.","o":"Ein geistreicher Mensch hat in gänzlicher Einsamkeit, an seinen eigenen Gedanken und Phantasien vortreffliche Unterhaltung","l":"de","ob":"Aforismos sobre el arte de vivir","an":"1851","u":"Capítulo 3","te":["soledad","creatividad"]},{"i":"arthur-schopenhauer-008","a":"arthur-schopenhauer","t":"El mundo en que vive cada uno depende ante todo de la manera en que lo concibe.","o":"Die Welt, in der jeder lebt, hängt zunächst ab von seiner Auffassung derselben","l":"de","ob":"Aforismos sobre el arte de vivir","an":"1851","u":"Capítulo 3","te":["conciencia","identidad"]},{"i":"arthur-schopenhauer-009","a":"arthur-schopenhauer","t":"Así, lo que uno tiene en sí mismo es lo más esencial para la felicidad de su vida.","o":"Also, was einer an sich selber hat, ist zu seinem Lebensglücke das Wesentlichste.","l":"de","ob":"Aforismos sobre el arte de vivir","an":"1851","u":"Capítulo 3","te":["felicidad","autoconocimiento"]},{"i":"arthur-schopenhauer-010","a":"arthur-schopenhauer","t":"El vacío interior, la insipidez de la conciencia y la pobreza de espíritu empujan a muchos a buscar compañía.","o":"Die Leere ihres Innern, das Fade ihres Bewußtseins, die Armut ihres Geistes treibt sie zur Gesellschaft","l":"de","ob":"Aforismos sobre el arte de vivir","an":"1851","u":"Capítulo 3","te":["soledad","vinculos"]},{"i":"arthur-schopenhauer-011","a":"arthur-schopenhauer","t":"Además, uno sigue siendo esclavo de la opinión y del parecer ajenos.","o":"Außerdem bleibt man der Sklave fremder Meinung und fremden Bedünkens.","l":"de","ob":"Aforismos sobre el arte de vivir","an":"1851","u":"Capítulo 6","te":["autoestima","libertad"]},{"i":"arthur-schopenhauer-012","a":"arthur-schopenhauer","t":"Por eso, valorar con justeza lo que uno es en sí y para sí, frente a lo que es solo a los ojos de los demás, contribuirá mucho a nuestra felicidad.","o":"Demnach wird eine richtige Abschätzung des Wertes dessen, was man in und für sich selbst ist, gegen das, was man bloß in den Augen anderer ist, zu unserm Glücke viel beitragen.","l":"de","ob":"Aforismos sobre el arte de vivir","an":"1851","u":"Capítulo 6","te":["autoestima","felicidad"]},{"i":"arthur-schopenhauer-013","a":"arthur-schopenhauer","t":"Comprenderemos entonces que quien le da mucho valor a la opinión de la gente le hace demasiado honor.","o":"Wir werden dann einsehen, daß wer auf die Meinung der Menschen einen großen Wert legt, ihnen zuviel Ehre erzeigt.","l":"de","ob":"Aforismos sobre el arte de vivir","an":"1851","u":"Capítulo 6","te":["autoestima","libertad"]},{"i":"arthur-schopenhauer-014","a":"arthur-schopenhauer","t":"Todas nuestras preocupaciones, disgustos, rencillas, enojos, angustias y esfuerzos se refieren, quizás en la mayoría de los casos, a la opinión ajena.","o":"Unser aller Sorgen, Kümmern, Wurmen, Ärgern, Ängstigen, Anstrengen, usw. betrifft, in vielleicht den meisten Fällen, eigentlich die fremde Meinung","l":"de","ob":"Aforismos sobre el arte de vivir","an":"1851","u":"Capítulo 6","te":["angustia","autoestima"]},{"i":"arthur-schopenhauer-015","a":"arthur-schopenhauer","t":"No menos brotan de esa misma raíz [la opinión ajena] nuestra envidia y nuestro odio.","o":"Nicht weniger entspringt unser Neid und Haß größtenteils aus besagter Wurzel.","l":"de","ob":"Aforismos sobre el arte de vivir","an":"1851","u":"Capítulo 6","te":["ira","autoestima"]},{"i":"arthur-schopenhauer-016","a":"arthur-schopenhauer","t":"El honor es, objetivamente, la opinión de los demás sobre nuestro valor y, subjetivamente, nuestro miedo a esa opinión.","o":"die Ehre ist, objektiv, die Meinung anderer von unserm Wert, und subjektiv, unsere Furcht vor dieser Meinung.","l":"de","ob":"Aforismos sobre el arte de vivir","an":"1851","u":"Capítulo 6","te":["autoestima","miedo"]},{"i":"arthur-schopenhauer-017","a":"arthur-schopenhauer","t":"El ser humano solo puede muy poco y es un Robinson abandonado: únicamente en comunidad con los demás es y puede mucho.","o":"Der Mensch für sich allein vermag gar wenig und ist ein verlassener Robinson: nur in der Gemeinschaft mit den andern ist und vermag er viel.","l":"de","ob":"Aforismos sobre el arte de vivir","an":"1851","u":"Capítulo 6","te":["vinculos","sociedad"]},{"i":"arthur-schopenhauer-018","a":"arthur-schopenhauer","t":"Debe tener una opinión muy débil de su propio valor quien se apura a sofocar cualquier comentario que lo ponga en duda.","o":"Der aber muß selbst eine schwache Meinung von seinem eigenen Werte haben, der sich beeilt, jeder denselben anfechtenden Äußerung den Daumen aufs Auge zu drücken","l":"de","ob":"Aforismos sobre el arte de vivir","an":"1851","u":"Capítulo 6","te":["autoestima","ira"]},{"i":"arthur-schopenhauer-019","a":"arthur-schopenhauer","t":"Nuestra vida es tan pobre que hay que administrar sus bienes con más economía.","o":"Unser Leben ist so arm, daß seine Güter haushälterischer verteilt werden müssen.","l":"de","ob":"Aforismos sobre el arte de vivir","an":"1851","u":"Capítulo 6","te":["existencia"]},{"i":"arthur-schopenhauer-020","a":"arthur-schopenhauer","t":"Los dolores, en cambio, se sienten de manera positiva: por eso su ausencia es la medida de la felicidad de una vida.","o":"Die Schmerzen hingegen werden positiv empfunden: daher ist ihre Abwesenheit der Maßstab des Lebensglückes.","l":"de","ob":"Aforismos sobre el arte de vivir","an":"1851","u":"Capítulo 7","te":["sufrimiento","felicidad"]},{"i":"arthur-schopenhauer-021","a":"arthur-schopenhauer","t":"Si a un estado sin dolor se suma la ausencia de aburrimiento, la felicidad terrenal está, en lo esencial, alcanzada.","o":"Kommt zu einem schmerzlosen Zustand noch die Abwesenheit der Langenweile; so ist das irdische Glück im wesentlichen erreicht","l":"de","ob":"Aforismos sobre el arte de vivir","an":"1851","u":"Capítulo 7","te":["felicidad","sufrimiento"]},{"i":"arthur-schopenhauer-022","a":"arthur-schopenhauer","t":"El necio corre tras los placeres de la vida y se ve engañado; el sabio evita los males.","o":"Der Tor läuft den Genüssen des Lebens nach und sieht sich betrogen: der Weise vermeidet die Übel.","l":"de","ob":"Aforismos sobre el arte de vivir","an":"1851","u":"Capítulo 7","te":["felicidad","deseo"]},{"i":"arthur-schopenhauer-023","a":"arthur-schopenhauer","t":"Llegamos al mundo llenos de pretensiones de felicidad y placer, y alimentamos la esperanza tonta de conseguirlos.","o":"wir treten in die Welt voll Ansprüche auf Glück und Genuß und hegen die törichte Hoffnung, solche durchzusetzen.","l":"de","ob":"Aforismos sobre el arte de vivir","an":"1851","u":"Capítulo 7","te":["felicidad","esperanza","deseo"]},{"i":"arthur-schopenhauer-024","a":"arthur-schopenhauer","t":"La compañía verdaderamente buena es, en todas partes y necesariamente, muy reducida.","o":"Die wirklich gute Gesellschaft nämlich ist, überall und notwendig, sehr klein.","l":"de","ob":"Aforismos sobre el arte de vivir","an":"1851","u":"Capítulo 7","te":["amistad","vinculos"]},{"i":"arthur-schopenhauer-025","a":"arthur-schopenhauer","t":"En general, una de las mayores y más frecuentes tonterías es hacer grandes preparativos para vivir.","o":"Überhaupt ist es eine der größten und häufigsten Torheiten, daß man weitläufige Anstalten zum Leben macht","l":"de","ob":"Aforismos sobre el arte de vivir","an":"1851","u":"Capítulo 7","te":["tiempo","presencia"]},{"i":"arthur-schopenhauer-026","a":"arthur-schopenhauer","t":"Muchos viven demasiado en el presente: los imprudentes.","o":"Viele leben zu sehr in der Gegenwart; die Leichtsinnigen.","l":"de","ob":"Aforismos sobre el arte de vivir","an":"1851","u":"Capítulo 7","te":["presencia","tiempo"]},{"i":"arthur-schopenhauer-027","a":"arthur-schopenhauer","t":"Otros, demasiado en el futuro: los ansiosos y preocupados.","o":"Andere zu sehr in der Zukunft: die Ängstlichen und Besorglichen.","l":"de","ob":"Aforismos sobre el arte de vivir","an":"1851","u":"Capítulo 7","te":["angustia","tiempo"]},{"i":"arthur-schopenhauer-028","a":"arthur-schopenhauer","t":"Solo el presente es verdadero y real: es el tiempo efectivamente lleno, y únicamente en él está nuestra existencia.","o":"Die Gegenwart allein ist wahr und wirklich: sie ist die real erfüllte Zeit, und ausschließlich in ihr liegt unser Dasein.","l":"de","ob":"Aforismos sobre el arte de vivir","an":"1851","u":"Capítulo 7","te":["presencia","tiempo"]},{"i":"arthur-schopenhauer-029","a":"arthur-schopenhauer","t":"Cada uno huirá de la soledad, la soportará o la amará en proporción exacta al valor de su propio yo.","o":"Demgemäß wird jeder in genauer Proportion zum Werte seines eigenen Selbst die Einsamkeit fliehen, ertragen, oder lieben.","l":"de","ob":"Aforismos sobre el arte de vivir","an":"1851","u":"Capítulo 7","te":["soledad","identidad"]},{"i":"arthur-schopenhauer-030","a":"arthur-schopenhauer","t":"Cada uno puede ser enteramente él mismo solo mientras está solo: quien no ama la soledad tampoco ama la libertad, porque solo cuando uno está solo es libre.","o":"Ganz er selbst sein darf jeder nur so lange er allein ist: wer also nicht die Einsamkeit liebt, der liebt auch nicht die Freiheit: denn nur wenn man allein ist, ist man frei","l":"de","ob":"Aforismos sobre el arte de vivir","an":"1851","u":"Capítulo 7","te":["soledad","libertad","autenticidad"]},{"i":"arthur-schopenhauer-031","a":"arthur-schopenhauer","t":"En esa clase de compañía tenemos que renunciar, con penosa negación de nosotros mismos, a tres cuartas partes de lo que somos para parecernos a los demás.","o":"In solcher Gesellschaft müssen wir daher mit schwerer Selbstverleugnung dreiviertel unserer selbst aufgeben, um uns den andern zu verähnlichen.","l":"de","ob":"Aforismos sobre el arte de vivir","an":"1851","u":"Capítulo 7","te":["autenticidad","vinculos"]},{"i":"arthur-schopenhauer-032","a":"arthur-schopenhauer","t":"El vacío interior y el hastío son los que empujan a muchos a la vida social, al extranjero y a los viajes.","o":"Innere Leere und Überdruß sind es, von denen sie sowohl in die Gesellschaft, wie in die Fremde und auf Reisen getrieben werden.","l":"de","ob":"Aforismos sobre el arte de vivir","an":"1851","u":"Capítulo 7","te":["soledad","deseo"]},{"i":"arthur-schopenhauer-033","a":"arthur-schopenhauer","t":"Quien se hace amigo de la soledad a tiempo, y hasta llega a quererla, ha conseguido una mina de oro.","o":"Sonach hat, wer sich zeitig mit der Einsamkeit befreundet, ja, sie lieb gewinnt, eine Goldmine erworben.","l":"de","ob":"Aforismos sobre el arte de vivir","an":"1851","u":"Capítulo 7","te":["soledad","felicidad"]},{"i":"arthur-schopenhauer-034","a":"arthur-schopenhauer","t":"Así como al principio la necesidad, una vez resuelta esta es el aburrimiento lo que junta a las personas.","o":"Denn wie ursprünglich die Not, so treibt, nach Beseitigung dieser, die Langeweile die Menschen zusammen.","l":"de","ob":"Aforismos sobre el arte de vivir","an":"1851","u":"Capítulo 7","te":["vinculos","soledad"]},{"i":"arthur-schopenhauer-035","a":"arthur-schopenhauer","t":"La envidia es natural en el ser humano; sin embargo, es a la vez un vicio y una desdicha.","o":"Neid ist dem Menschen natürlich: dennoch ist er ein Laster und Unglück zugleich.","l":"de","ob":"Aforismos sobre el arte de vivir","an":"1851","u":"Capítulo 7","te":["emociones","sufrimiento"]},{"i":"arthur-schopenhauer-036","a":"arthur-schopenhauer","t":"La envidia de las personas muestra cuán desdichadas se sienten; su atención constante a lo que hacen los demás, cuánto se aburren.","o":"Der Neid der Menschen zeigt an, wie unglücklich sie sich fühlen; ihre beständige Aufmerksamkeit auf fremdes Tun und Lassen, wie sehr sie sich langweilen.","l":"de","ob":"Aforismos sobre el arte de vivir","an":"1851","u":"Capítulo 7","te":["emociones","felicidad"]},{"i":"arthur-schopenhauer-037","a":"arthur-schopenhauer","t":"En general, la salud, el sueño, la alimentación, la temperatura, el clima, el entorno y muchas otras cosas exteriores influyen poderosamente en nuestro ánimo, y este en nuestros pensamientos.","o":"Überhaupt aber hat Gesundheitszustand, Schlaf, Nahrung, Temperatur, Wetter, Umgebung und noch viel anderes Äußerliches auf unsere Stimmung, und diese auf unsere Gedanken einen mächtigen Einfluß.","l":"de","ob":"Aforismos sobre el arte de vivir","an":"1851","u":"Capítulo 7","te":["cuerpo","emociones","habitos"]},{"i":"arthur-schopenhauer-038","a":"arthur-schopenhauer","t":"Cada día es una pequeña vida: cada despertar y levantarse, un pequeño nacimiento; cada mañana fresca, una pequeña juventud; y cada acostarse y dormirse, una pequeña muerte.","o":"Jeder Tag ist ein kleines Leben - jedes Erwachen und Aufstehen eine kleine Geburt, jeder frische Morgen eine kleine Jugend, und jedes Zubettgehen und Einschlafen ein kleiner Tod.","l":"de","ob":"Aforismos sobre el arte de vivir","an":"1851","u":"Capítulo 7","te":["tiempo","presencia","habitos"]},{"i":"arthur-schopenhauer-039","a":"arthur-schopenhauer","t":"Nuestra existencia es esencialmente inquieta: por eso la inactividad total se nos vuelve pronto insoportable.","o":"Unser Dasein nämlich ist ein wesentlich restloses: daher wird die gänzliche Untätigkeit uns bald unerträglich","l":"de","ob":"Aforismos sobre el arte de vivir","an":"1851","u":"Capítulo 7","te":["trabajo","existencia"]},{"i":"arthur-schopenhauer-040","a":"arthur-schopenhauer","t":"Esforzarse y luchar contra la resistencia es para el ser humano una necesidad, como cavar lo es para el topo.","o":"Sich zu mühen und mit dem Widerstände zu kämpfen ist dem Menschen Bedürfnis, wie dem Maulwurf das Graben.","l":"de","ob":"Aforismos sobre el arte de vivir","an":"1851","u":"Capítulo 7","te":["trabajo","resiliencia"]},{"i":"arthur-schopenhauer-041","a":"arthur-schopenhauer","t":"La riqueza se parece al agua de mar: cuanto más se bebe, más sed da. Lo mismo vale para la fama.","o":"Der Reichtum gleicht dem Seewasser: je mehr man davon trinkt, desto durstiger wird man. - Dasselbe gilt vom Ruhm.","l":"de","ob":"Aforismos sobre el arte de vivir","an":"1851","u":"Capítulo 5","te":["deseo","felicidad"]},{"i":"arthur-schopenhauer-042","a":"arthur-schopenhauer","t":"Lo que la gente suele llamar destino no son, en su mayoría, más que sus propias tonterías.","o":"Was aber die Leute gemeiniglich das Schicksal nennen sind meistens nur ihre eigenen dummen Streiche.","l":"de","ob":"Aforismos sobre el arte de vivir","an":"1851","u":"Capítulo 7","te":["responsabilidad"]},{"i":"arthur-schopenhauer-043","a":"arthur-schopenhauer","t":"Salvo raras excepciones, en el mundo solo se puede elegir entre la soledad y la vulgaridad.","o":"daß es, seltene Ausnahmen abgerechnet, in der Welt nur die Wahl gibt zwischen Einsamkeit und Gemeinheit.","l":"de","ob":"Aforismos sobre el arte de vivir","an":"1851","u":"Capítulo 7","te":["soledad"]},{"i":"arthur-schopenhauer-044","a":"arthur-schopenhauer","t":"Claro que eso implica infligirse el gran dolor del descontento con uno mismo; pero nadie se educa sin pasar por algún castigo.","o":"Freilich hat man sich dabei den großen Schmerz der Unzufriedenheit mit sich selbst anzutun: aber der Mensch wird nicht erzogen, ohne daß er gestraft wird.","l":"de","ob":"Aforismos sobre el arte de vivir","an":"1851","u":"Capítulo 7","te":["educacion","culpa"]},{"i":"arthur-schopenhauer-045","a":"arthur-schopenhauer","t":"La mitad objetiva del presente y de la realidad está en manos del destino y es, por tanto, variable; la mitad subjetiva somos nosotros mismos.","o":"Die objektive Hälfte der Gegenwart und Wirklichkeit steht in der Hand des Schicksals und ist demnach veränderlich: die subjektive sind wir selbst","l":"de","ob":"Aforismos sobre el arte de vivir","an":"1851","u":"Capítulo 3","te":["responsabilidad","identidad"]},{"i":"arthur-schopenhauer-046","a":"arthur-schopenhauer","t":"Para no perder la tranquilidad de la vida por males inciertos o indeterminados [conviene mirarlos como si nunca fueran a llegar].","o":"Um also nicht der Ruhe unseres Lebens durch ungewisse, oder unbestimmte Übel verlustig zu werden","l":"de","ob":"Aforismos sobre el arte de vivir","an":"1851","u":"Capítulo 7","te":["angustia","incertidumbre"]},{"i":"arthur-schopenhauer-047","a":"arthur-schopenhauer","t":"Toda compañía exige necesariamente una adaptación mutua y una moderación; por eso, cuanto más grande, más insípida.","o":"Zunächst erfordert jede Gesellschaft notwendig eine gegenseitige Accommodation und Temperatur; daher wird sie, je größer, desto fader.","l":"de","ob":"Aforismos sobre el arte de vivir","an":"1851","u":"Capítulo 7","te":["vinculos","sociedad"]},{"i":"arthur-schopenhauer-048","a":"arthur-schopenhauer","t":"A menudo, donde buscábamos placer, dicha y alegría, recibimos en cambio enseñanza, comprensión y conocimiento.","o":"Zumal wird uns oft da, wo wir, Genuß, Glück, Freude suchten, statt ihrer Belehrung, Einsicht, Erkenntnis","l":"de","ob":"Aforismos sobre el arte de vivir","an":"1851","u":"Capítulo 7","te":["conocimiento","transformacion-personal"]},{"i":"arthur-schopenhauer-049","a":"arthur-schopenhauer","t":"Es un consuelo de la vejez tener ya detrás el trabajo de la vida.","o":"Ja es ist ein Trost im Alter, daß man die Arbeit des Lebens hinter sich hat.","l":"de","ob":"Aforismos sobre el arte de vivir","an":"1851","u":"Capítulo 7","te":["desarrollo-humano","trabajo"]},{"i":"arthur-schopenhauer-050","a":"arthur-schopenhauer","t":"Es curioso que el ser humano tenga un cierto respeto innato, realmente instintivo, por las canas.","o":"Merkwürdig aber ist es, daß dem Menschen ein gewisser Respekt vor weißen Haaren angeboren und daher wirklich instinktiv ist.","l":"de","ob":"Aforismos sobre el arte de vivir","an":"1851","u":"Capítulo 6","te":["desarrollo-humano"]},{"i":"arthur-schopenhauer-051","a":"arthur-schopenhauer","t":"Para alcanzar la dicha de la paz del espíritu, los cínicos renunciaban a toda posesión; quien con el mismo fin renuncia a la vida social eligió el medio más sabio.","o":"Um des Glückes der Geistesruhe teilhaftig zu werden, entsagen die Zyniker jedem Besitze: wer in gleicher Absicht der Gesellschaft entsagt, hat das weiseste Mittel erwählt.","l":"de","ob":"Aforismos sobre el arte de vivir","an":"1851","u":"Capítulo 7","te":["soledad","silencio"]},{"i":"friedrich-nietzsche-026","a":"friedrich-nietzsche","t":"Hay que tener todavía caos dentro de sí para poder dar a luz una estrella danzante.","o":"man muss noch Chaos in sich haben, um einen tanzenden Stern gebären zu können","l":"de","ob":"Así habló Zaratustra","an":"1883–1885","u":"Erster Theil","te":["creatividad","transformacion-personal"]},{"i":"friedrich-nietzsche-027","a":"friedrich-nietzsche","t":"El ser humano es una cuerda tendida entre el animal y el superhombre.","o":"Der Mensch ist ein Seil, geknüpft zwischen Thier und Übermensch","l":"de","ob":"Así habló Zaratustra","an":"1883–1885","u":"Erster Theil","te":["existencia","transformacion-personal"]},{"i":"friedrich-nietzsche-028","a":"friedrich-nietzsche","t":"Lo grande del ser humano es que es un puente y no una meta.","o":"Was gross ist am Menschen, das ist, dass er eine Brücke und kein Zweck ist","l":"de","ob":"Así habló Zaratustra","an":"1883–1885","u":"Erster Theil","te":["transformacion-personal","cambio"]},{"i":"friedrich-nietzsche-029","a":"friedrich-nietzsche","t":"Solo creería en un dios que supiera bailar.","o":"Ich würde nur an einen Gott glauben, der zu tanzen verstünde.","l":"de","ob":"Así habló Zaratustra","an":"1883–1885","u":"Erster Theil","te":["trascendencia","alegria"]},{"i":"friedrich-nietzsche-030","a":"friedrich-nietzsche","t":"Siempre hay algo de locura en el amor. Pero siempre hay también algo de razón en la locura.","o":"Es ist immer etwas Wahnsinn in der Liebe. Es ist aber immer auch etwas Vernunft im Wahnsinn.","l":"de","ob":"Así habló Zaratustra","an":"1883–1885","u":"Erster Theil","te":["amor","deseo"]},{"i":"friedrich-nietzsche-031","a":"friedrich-nietzsche","t":"Detrás de tus pensamientos y sentimientos, hermano, hay un soberano poderoso, un sabio desconocido: se llama “sí mismo”. Habita en tu cuerpo; es tu cuerpo.","o":"Hinter deinen Gedanken und Gefühlen, mein Bruder, steht ein mächtiger Gebieter, ein unbekannter Weiser-der heisst Selbst. In deinem Leibe wohnt er, dein Leib ist er.","l":"de","ob":"Así habló Zaratustra","an":"1883–1885","u":"Erster Theil","te":["cuerpo","inconsciente","identidad"]},{"i":"friedrich-nietzsche-032","a":"friedrich-nietzsche","t":"Hay más razón en tu cuerpo que en tu mejor sabiduría.","o":"Es ist mehr Vernunft in deinem Leibe, als in deiner besten Weisheit.","l":"de","ob":"Así habló Zaratustra","an":"1883–1885","u":"Erster Theil","te":["cuerpo","conocimiento"]},{"i":"friedrich-nietzsche-033","a":"friedrich-nietzsche","t":"También tu pequeña razón es una herramienta de tu cuerpo.","o":"Werkzeug deines Leibes ist auch deine kleine Vernunft","l":"de","ob":"Así habló Zaratustra","an":"1883–1885","u":"Erster Theil","te":["cuerpo","conciencia"]},{"i":"friedrich-nietzsche-034","a":"friedrich-nietzsche","t":"Tenés que querer quemarte en tu propia llama: ¿cómo querrías renovarte si antes no te hiciste ceniza?","o":"Verbrennen musst du dich wollen in deiner eignen Flamme: wie wolltest du neu werden, wenn du nicht erst Asche geworden bist!","l":"de","ob":"Así habló Zaratustra","an":"1883–1885","u":"Erster Theil","te":["transformacion-personal","cambio"]},{"i":"friedrich-nietzsche-035","a":"friedrich-nietzsche","t":"Solitario, recorrés el camino hacia vos mismo.","o":"Einsamer, du gehst den Weg zu dir selber!","l":"de","ob":"Así habló Zaratustra","an":"1883–1885","u":"Erster Theil","te":["soledad","autoconocimiento"]},{"i":"friedrich-nietzsche-036","a":"friedrich-nietzsche","t":"Pero el peor enemigo que podés encontrar siempre serás vos mismo.","o":"Aber der schlimmste Feind, dem du begegnen kannst, wirst du immer dir selber sein","l":"de","ob":"Así habló Zaratustra","an":"1883–1885","u":"Erster Theil","te":["autoconocimiento","sufrimiento"]},{"i":"friedrich-nietzsche-037","a":"friedrich-nietzsche","t":"En verdad, el ser humano es un río sucio. Hay que ser un mar para poder recibir un río sucio sin volverse impuro.","o":"Wahrlich, ein schmutziger Strom ist der Mensch. Man muss schon ein Meer sein, um einen schmutzigen Strom aufnehmen zu können, ohne unrein zu werden.","l":"de","ob":"Así habló Zaratustra","an":"1883–1885","u":"Erster Theil","te":["aceptacion","existencia"]},{"i":"friedrich-nietzsche-038","a":"friedrich-nietzsche","t":"El valor es el mejor matador, el valor que ataca: hasta a la muerte mata.","o":"Muth aber ist der beste Todtschläger, Muth, der angreift: der schlägt noch den Tod todt","l":"de","ob":"Así habló Zaratustra","an":"1883–1885","u":"Dritter Theil","te":["miedo","muerte","resiliencia"]},{"i":"friedrich-nietzsche-039","a":"friedrich-nietzsche","t":"¿Eso era la vida? ¡Bien! ¡Otra vez!","o":"War _das_ das Leben? Wohlan! Noch Ein Mal!","l":"de","ob":"Así habló Zaratustra","an":"1883–1885","u":"Dritter Theil","te":["sentido-de-vida","aceptacion"]},{"i":"friedrich-nietzsche-040","a":"friedrich-nietzsche","t":"Se le paga mal a un maestro si se sigue siendo siempre solo su alumno.","o":"Man vergilt einem Lehrer schlecht, wenn man immer nur der Schüler bleibt.","l":"de","ob":"Así habló Zaratustra","an":"1883–1885","u":"Erster Theil","te":["educacion","autenticidad"]},{"i":"friedrich-nietzsche-041","a":"friedrich-nietzsche","t":"El ser humano es algo que debe ser superado.","o":"Der Mensch ist Etwas, das überwunden werden soll.","l":"de","ob":"Así habló Zaratustra","an":"1883–1885","u":"Erster Theil","te":["transformacion-personal"]},{"i":"friedrich-nietzsche-042","a":"friedrich-nietzsche","t":"Permanezcan fieles a la tierra.","o":"bleibt der Erde treu","l":"de","ob":"Así habló Zaratustra","an":"1883–1885","u":"Erster Theil","te":["naturaleza","cuerpo"]},{"i":"friedrich-nietzsche-043","a":"friedrich-nietzsche","t":"Toda la vida es una disputa sobre gustos y sabores.","o":"alles Leben ist Streit um Geschmack und Schmecken","l":"de","ob":"Así habló Zaratustra","an":"1883–1885","u":"Zweiter Theil","te":["existencia","deseo"]},{"i":"friedrich-nietzsche-044","a":"friedrich-nietzsche","t":"De todo lo escrito, solo amo lo que alguien escribe con su sangre.","o":"Von allem Geschriebenen liebe ich nur Das, was Einer mit seinem Blute schreibt.","l":"de","ob":"Así habló Zaratustra","an":"1883–1885","u":"Erster Theil","te":["autenticidad","creatividad"]},{"i":"friedrich-nietzsche-011","a":"friedrich-nietzsche","t":"Quien lucha con monstruos debe cuidar de no convertirse en monstruo. Y si mirás largo tiempo a un abismo, el abismo también mira dentro de vos.","o":"Wer mit Ungeheuern kämpft, mag zusehn, dass er nicht dabei zum Ungeheuer wird. Und wenn du lange in einen Abgrund blickst, blickt der Abgrund auch in dich hinein.","l":"de","ob":"Más allá del bien y del mal","an":"1886","u":"§ 146","te":["identidad","inconsciente"]},{"i":"friedrich-nietzsche-012","a":"friedrich-nietzsche","t":"“Esto lo hice yo”, dice mi memoria. “Esto no puedo haberlo hecho”, dice mi orgullo, y se mantiene inflexible. Al final, cede la memoria.","o":"\"Das habe ich gethan\" sagt mein Gedächtniss. Das kann ich nicht gethan haben - sagt mein Stolz und bleibt unerbittlich. Endlich - giebt das Gedächtniss nach.","l":"de","ob":"Más allá del bien y del mal","an":"1886","u":"§ 68","te":["memoria","autoestima","inconsciente"]},{"i":"friedrich-nietzsche-013","a":"friedrich-nietzsche","t":"Lo que se hace por amor sucede siempre más allá del bien y del mal.","o":"Was aus Liebe gethan wird, geschieht immer jenseits von Gut und Böse.","l":"de","ob":"Más allá del bien y del mal","an":"1886","u":"§ 153","te":["amor"]},{"i":"friedrich-nietzsche-014","a":"friedrich-nietzsche","t":"La locura es algo raro en los individuos; pero en los grupos, los partidos, los pueblos y las épocas, es la regla.","o":"Der Irrsinn ist bei Einzelnen etwas Seltenes, - aber bei Gruppen, Parteien, Völkern, Zeiten die Regel.","l":"de","ob":"Más allá del bien y del mal","an":"1886","u":"§ 156","te":["sociedad","salud-mental"]},{"i":"friedrich-nietzsche-015","a":"friedrich-nietzsche","t":"Quien se desprecia a sí mismo se respeta todavía, en eso, como despreciador.","o":"Wer sich selbst verachtet, achtet sich doch immer noch dabei als Verächter.","l":"de","ob":"Más allá del bien y del mal","an":"1886","u":"§ 78","te":["autoestima","identidad"]},{"i":"friedrich-nietzsche-016","a":"friedrich-nietzsche","t":"Al final, uno ama su deseo y no lo deseado.","o":"Man liebt zuletzt seine Begierde, und nicht das Begehrte.","l":"de","ob":"Más allá del bien y del mal","an":"1886","u":"§ 175","te":["deseo","amor"]},{"i":"friedrich-nietzsche-017","a":"friedrich-nietzsche","t":"Todo lo profundo ama la máscara.","o":"Alles, was tief ist, liebt die Maske","l":"de","ob":"Más allá del bien y del mal","an":"1886","u":"§ 40","te":["identidad","autenticidad"]},{"i":"friedrich-nietzsche-018","a":"friedrich-nietzsche","t":"No me conmovió que me mintieras, sino que ya no pueda creerte.","o":"Nicht dass du mich belogst, sondern dass ich dir nicht mehr glaube, hat mich erschüttert.","l":"de","ob":"Más allá del bien y del mal","an":"1886","u":"§ 183","te":["vinculos","verdad","perdida"]},{"i":"friedrich-nietzsche-019","a":"friedrich-nietzsche","t":"No hay fenómenos morales, sino solo una interpretación moral de los fenómenos.","o":"Es giebt gar keine moralischen Phänomene, sondern nur eine moralische Ausdeutung von Phänomenen","l":"de","ob":"Más allá del bien y del mal","an":"1886","u":"§ 108","te":["verdad","cultura"]},{"i":"friedrich-nietzsche-020","a":"friedrich-nietzsche","t":"Uno ya no ama lo suficiente su conocimiento en cuanto lo comunica.","o":"Man liebt seine Erkenntniss nicht genug mehr, sobald man sie mittheilt.","l":"de","ob":"Más allá del bien y del mal","an":"1886","u":"§ 160","te":["conocimiento","comunicacion"]},{"i":"friedrich-nietzsche-021","a":"friedrich-nietzsche","t":"Un pensamiento viene cuando “él” quiere, y no cuando “yo” quiero.","o":"ein Gedanke kommt, wenn \"er\" will, und nicht wenn \"ich\" will","l":"de","ob":"Más allá del bien y del mal","an":"1886","u":"§ 17","te":["inconsciente","conciencia"]},{"i":"friedrich-nietzsche-022","a":"friedrich-nietzsche","t":"Madurez del hombre: haber reencontrado la seriedad que se tenía de niño al jugar.","o":"Reife des Mannes: das heisst den Ernst wiedergefunden haben, den man als Kind hatte, beim Spiel.","l":"de","ob":"Más allá del bien y del mal","an":"1886","u":"§ 94","te":["infancia","desarrollo-humano"]},{"i":"friedrich-nietzsche-023","a":"friedrich-nietzsche","t":"Que un juicio sea falso no es todavía, para nosotros, una objeción contra ese juicio.","o":"Die Falschheit eines Urtheils ist uns noch kein Einwand gegen ein Urtheil","l":"de","ob":"Más allá del bien y del mal","an":"1886","u":"§ 4","te":["verdad","conocimiento"]},{"i":"friedrich-nietzsche-024","a":"friedrich-nietzsche","t":"El amor saca a la luz las cualidades elevadas y ocultas de quien ama.","o":"Die Liebe bringt die hohen und verborgenen Eigenschaften eines Liebenden an's Licht","l":"de","ob":"Más allá del bien y del mal","an":"1886","u":"§ 163","te":["amor","identidad"]},{"i":"friedrich-nietzsche-025","a":"friedrich-nietzsche","t":"[¿Un gran hombre?] Siempre veo solo al actor de su propio ideal.","o":"Ich sehe immer nur den Schauspieler seines eignen Ideals","l":"de","ob":"Más allá del bien y del mal","an":"1886","u":"§ 97","te":["identidad","autenticidad"]},{"i":"friedrich-nietzsche-001","a":"friedrich-nietzsche","t":"Lo que no me mata me hace más fuerte.","o":"Was mich nicht umbringt, macht mich stärker.","l":"de","ob":"El ocaso de los ídolos","an":"1889","u":"«Sprüche und Pfeile», § 8","te":["resiliencia","sufrimiento"]},{"i":"friedrich-nietzsche-002","a":"friedrich-nietzsche","t":"Si se tiene un “por qué” para vivir, se soporta casi cualquier “cómo”.","o":"Hat man sein warum? des Lebens, so verträgt man sich fast mit jedem wie?","l":"de","ob":"El ocaso de los ídolos","an":"1889","u":"«Sprüche und Pfeile», § 12","te":["sentido-de-vida","resiliencia"]},{"i":"friedrich-nietzsche-003","a":"friedrich-nietzsche","t":"Sin música, la vida sería un error.","o":"Ohne Musik wäre das Leben ein Irrthum.","l":"de","ob":"El ocaso de los ídolos","an":"1889","u":"«Sprüche und Pfeile», § 33","te":["alegria","cultura"]},{"i":"friedrich-nietzsche-004","a":"friedrich-nietzsche","t":"El ocio es el comienzo de toda psicología.","o":"Müssiggang ist aller Psychologie Anfang.","l":"de","ob":"El ocaso de los ídolos","an":"1889","u":"«Sprüche und Pfeile», § 1","te":["autoconocimiento","humor"]},{"i":"friedrich-nietzsche-005","a":"friedrich-nietzsche","t":"Hasta el más valiente de nosotros rara vez tiene el valor de lo que en verdad sabe.","o":"Auch der Muthigste von uns hat nur selten den Muth zu dem, was er eigentlich weiss","l":"de","ob":"El ocaso de los ídolos","an":"1889","u":"«Sprüche und Pfeile», § 2","te":["miedo","verdad"]},{"i":"friedrich-nietzsche-006","a":"friedrich-nietzsche","t":"La sabiduría también le pone límites al conocimiento.","o":"Die Weisheit zieht auch der Erkenntniss Grenzen.","l":"de","ob":"El ocaso de los ídolos","an":"1889","u":"«Sprüche und Pfeile», § 5","te":["conocimiento"]},{"i":"friedrich-nietzsche-007","a":"friedrich-nietzsche","t":"Desconfío de todos los sistemáticos y los evito. La voluntad de sistema es una falta de honestidad.","o":"Ich misstraue allen Systematikern und gehe ihnen aus dem Weg. Der Wille zum System ist ein Mangel an Rechtschaffenheit.","l":"de","ob":"El ocaso de los ídolos","an":"1889","u":"«Sprüche und Pfeile», § 26","te":["verdad","autenticidad"]},{"i":"friedrich-nietzsche-008","a":"friedrich-nietzsche","t":"Solo valen los pensamientos que nacen caminando.","o":"Nur die ergangenen Gedanken haben Werth.","l":"de","ob":"El ocaso de los ídolos","an":"1889","u":"«Sprüche und Pfeile», § 34","te":["cuerpo","creatividad"]},{"i":"friedrich-nietzsche-009","a":"friedrich-nietzsche","t":"¿Es el ser humano solo un error de Dios? ¿O Dios solo un error del ser humano?","o":"ist der Mensch nur ein Fehlgriff Gottes? Oder Gott nur ein Fehlgriff des Menschen?","l":"de","ob":"El ocaso de los ídolos","an":"1889","u":"«Sprüche und Pfeile», § 7","te":["trascendencia","existencia"]},{"i":"friedrich-nietzsche-010","a":"friedrich-nietzsche","t":"El gusano pisado se enrosca. Así es prudente.","o":"Der getretene Wurm krümmt sich. So ist es klug.","l":"de","ob":"El ocaso de los ídolos","an":"1889","u":"«Sprüche und Pfeile», § 31","te":["poder","humor"]},{"i":"friedrich-nietzsche-045","a":"friedrich-nietzsche","t":"Mi fórmula para la grandeza del ser humano es amor fati: no querer que nada sea distinto, ni hacia adelante, ni hacia atrás, ni por toda la eternidad.","o":"Meine Formel für die Grösse am Menschen ist amor fati: dass man Nichts anders haben will, vorwärts nicht, rückwärts nicht, in alle Ewigkeit nicht.","l":"de","ob":"Ecce homo","an":"1888 (publ. 1908)","u":"«Warum ich so klug bin», § 10","te":["aceptacion","sentido-de-vida"]},{"i":"friedrich-nietzsche-046","a":"friedrich-nietzsche","t":"No darle crédito a ningún pensamiento que no haya nacido al aire libre.","o":"keinem Gedanken Glauben schenken, der nicht im Freien geboren ist","l":"de","ob":"Ecce homo","an":"1888 (publ. 1908)","u":"«Warum ich so klug bin»","te":["cuerpo","naturaleza","creatividad"]},{"i":"friedrich-nietzsche-047","a":"friedrich-nietzsche","t":"Llegar a ser lo que uno es supone no sospechar ni remotamente lo que uno es.","o":"Dass man wird, was man ist, setzt voraus, dass man nicht im Entferntesten ahnt, was man ist.","l":"de","ob":"Ecce homo","an":"1888 (publ. 1908)","u":"«Warum ich so klug bin», § 9","te":["identidad","desarrollo-humano","autoconocimiento"]},{"i":"friedrich-nietzsche-048","a":"friedrich-nietzsche","t":"No soy un hombre, soy dinamita.","o":"Ich bin kein Mensch, ich bin Dynamit.","l":"de","ob":"Ecce homo","an":"1888 (publ. 1908)","u":"«Warum ich ein Schicksal bin», § 1","te":["identidad"]},{"i":"friedrich-nietzsche-049","a":"friedrich-nietzsche","t":"Las convicciones son enemigas de la verdad más peligrosas que las mentiras.","o":"Ueberzeugungen sind gefährlichere Feinde der Wahrheit, als Lügen.","l":"de","ob":"Humano, demasiado humano","an":"1878","u":"§ 483","te":["verdad"]},{"i":"friedrich-nietzsche-050","a":"friedrich-nietzsche","t":"[La esperanza] es, en verdad, el peor de los males, porque prolonga el tormento de los seres humanos.","o":"sie ist in Wahrheit das übelste der Uebel, weil sie die Qual der Menschen verlängert","l":"de","ob":"Humano, demasiado humano","an":"1878","u":"§ 71","te":["esperanza","sufrimiento"]},{"i":"friedrich-nietzsche-051","a":"friedrich-nietzsche","t":"Lo que hace al amigo es compartir la alegría, no compartir el sufrimiento.","o":"Mitfreude, nicht Mitleiden, macht den Freund.","l":"de","ob":"Humano, demasiado humano","an":"1878","u":"§ 499","te":["amistad","alegria"]},{"i":"friedrich-nietzsche-052","a":"friedrich-nietzsche","t":"Quien haya llegado aunque sea un poco a la libertad de la razón no puede sentirse en la tierra sino como un caminante.","o":"Wer nur einigermaassen zur Freiheit der Vernunft gekommen ist, kann sich auf Erden nicht anders fühlen, denn als Wanderer","l":"de","ob":"Humano, demasiado humano","an":"1878","u":"§ 638","te":["libertad","existencia"]},{"i":"rene-descartes-011","a":"rene-descartes","t":"En nada se ve mejor cuán defectuosas son las ciencias que heredamos de los antiguos que en lo que escribieron sobre las pasiones.","o":"Il n'y a rien en quoi paraisse mieux combien les sciences que nous avons des anciens sont défectueuses qu'en ce qu'ils ont écrit des passions.","l":"fr","ob":"Las pasiones del alma","an":"1649","u":"art. 1","te":["emociones","conocimiento"]},{"i":"rene-descartes-012","a":"rene-descartes","t":"Tales son los sentimientos de alegría, de ira y otros semejantes, que a veces despiertan en nosotros los objetos que mueven nuestros nervios, y a veces otras causas.","o":"Tels sont les sentiments de joie, de colère, et autres semblables, qui sont quelquefois excités en nous par les objets qui meuvent nos nerfs, et quelquefois aussi par d'autres causes.","l":"fr","ob":"Las pasiones del alma","an":"1649","u":"art. 25","te":["emociones","cuerpo"]},{"i":"rene-descartes-013","a":"rene-descartes","t":"Cómo una misma causa puede despertar pasiones distintas en personas distintas.","o":"Comment une même cause peut exciter diverses passions en divers hommes.","l":"fr","ob":"Las pasiones del alma","an":"1649","u":"art. 39","te":["emociones","identidad"]},{"i":"rene-descartes-014","a":"rene-descartes","t":"Por ejemplo, si la ira hace levantar la mano para golpear, la voluntad puede de ordinario retenerla; si el miedo empuja las piernas a huir, la voluntad puede detenerlas; y así con las demás.","o":"Par exemple, si la colère fait lever la main pour frapper, la volonté peut ordinairement la retenir ; si la peur incite les jambes à fuir, la volonté les peut arrêter, et ainsi des autres.","l":"fr","ob":"Las pasiones del alma","an":"1649","u":"art. 46","te":["regulacion-emocional","ira","miedo"]},{"i":"rene-descartes-015","a":"rene-descartes","t":"Pero hay quienes no pueden probar su fuerza porque nunca hacen combatir a su voluntad con sus propias armas, sino solo con las que le dan algunas pasiones para resistir a otras.","o":"Mais il y en a qui ne peuvent éprouver leur force, parce qu'ils ne font jamais combattre leur volonté avec ses propres armes, mais seulement avec celles que lui fournissent quelques passions pour résister à quelques autres.","l":"fr","ob":"Las pasiones del alma","an":"1649","u":"art. 48","te":["voluntad","regulacion-emocional"]},{"i":"rene-descartes-016","a":"rene-descartes","t":"Que no hay alma tan débil que, bien guiada, no pueda adquirir un poder absoluto sobre sus pasiones.","o":"Qu'il n'y a point d'âme si faible qu'elle ne puisse, étant bien conduite, acquérir un pouvoir absolu sur ses passions.","l":"fr","ob":"Las pasiones del alma","an":"1649","u":"art. 50","te":["regulacion-emocional","esperanza"]},{"i":"rene-descartes-017","a":"rene-descartes","t":"Es útil saber estas cosas para darle a cada uno el ánimo de aprender a regular sus pasiones.","o":"Or ces choses sont utiles à savoir pour donner le courage à un chacun d'étudier à régler ses passions.","l":"fr","ob":"Las pasiones del alma","an":"1649","u":"art. 50","te":["regulacion-emocional","educacion"]},{"i":"rene-descartes-018","a":"rene-descartes","t":"Me parece que la admiración [el asombro] es la primera de todas las pasiones.","o":"il me semble que l'admiration est la première de toutes les passions.","l":"fr","ob":"Las pasiones del alma","an":"1649","u":"art. 53","te":["emociones","atencion"]},{"i":"rene-descartes-019","a":"rene-descartes","t":"La admiración es una sorpresa súbita del alma que la lleva a considerar con atención los objetos que le parecen raros y extraordinarios.","o":"L'admiration est une subite surprise de l'âme, qui fait qu'elle se porte à considérer avec attention les objets qui lui semblent rares et extraordinaires.","l":"fr","ob":"Las pasiones del alma","an":"1649","u":"art. 70","te":["emociones","atencion","conocimiento"]},{"i":"rene-descartes-020","a":"rene-descartes","t":"De la admiración puede decirse en particular que es útil porque hace que aprendamos y retengamos en la memoria lo que antes ignorábamos.","o":"Et on peut dire en particulier de l'admiration qu'elle est utile en ce qu'elle fait que nous apprenons et retenons en notre mémoire les choses que nous avons auparavant ignorées.","l":"fr","ob":"Las pasiones del alma","an":"1649","u":"art. 75","te":["educacion","memoria"]},{"i":"rene-descartes-021","a":"rene-descartes","t":"Eso es lo que comúnmente se llama quedarse atónito; y el pasmo es un exceso de admiración que no puede ser sino malo.","o":"C'est cela qu'on appelle communément être étonné ; et l'étonnement est un excès d'admiration qui ne peut jamais être que mauvais.","l":"fr","ob":"Las pasiones del alma","an":"1649","u":"art. 73","te":["emociones"]},{"i":"rene-descartes-022","a":"rene-descartes","t":"El amor es una emoción del alma que la incita a unirse por voluntad a los objetos que le parecen convenientes.","o":"L'amour est une émotion de l'âme causée par le mouvement des esprits, qui l'incite à se joindre de volonté aux objets qui paraissent lui être convenables.","l":"fr","ob":"Las pasiones del alma","an":"1649","u":"art. 79","te":["amor","emociones"]},{"i":"rene-descartes-023","a":"rene-descartes","t":"Y el odio es una emoción que incita al alma a querer separarse de los objetos que se le presentan como dañinos.","o":"Et la haine est une émotion causée par les esprits, qui incite l'âme à vouloir être séparée des objets qui se présentent à elle comme nuisibles.","l":"fr","ob":"Las pasiones del alma","an":"1649","u":"art. 79","te":["ira","emociones"]},{"i":"rene-descartes-024","a":"rene-descartes","t":"Cuando se estima lo que se ama menos que a uno mismo, se siente por ello un simple afecto; cuando se lo estima igual que a uno mismo, se llama amistad; y cuando se lo estima más, esa pasión puede llamarse devoción.","o":"Car lorsqu'on estime l'objet de son amour moins que soi, on n'a pour lui qu'une simple affection ; lorsqu'on l'estime à l'égal de soi, cela se nomme amitié ; et lorsqu'on l'estime davantage, la passion qu'on a peut être nommée dévotion.","l":"fr","ob":"Las pasiones del alma","an":"1649","u":"art. 83","te":["amor","amistad","vinculos"]},{"i":"rene-descartes-025","a":"rene-descartes","t":"El deseo es una agitación del alma que la dispone a querer para el futuro las cosas que se representa como convenientes.","o":"La passion du désir est une agitation de l'âme causée par les esprits qui la dispose à vouloir pour l'avenir les choses qu'elle se représente être convenables.","l":"fr","ob":"Las pasiones del alma","an":"1649","u":"art. 86","te":["deseo","emociones"]},{"i":"rene-descartes-026","a":"rene-descartes","t":"La alegría es una emoción agradable del alma en la que consiste el disfrute del bien que las impresiones del cerebro le presentan como propio.","o":"La joie est une agréable émotion de l'âme, en laquelle consiste la jouissance qu'elle a du bien que les impressions du cerveau lui représentent comme sien.","l":"fr","ob":"Las pasiones del alma","an":"1649","u":"art. 91","te":["alegria","emociones"]},{"i":"rene-descartes-027","a":"rene-descartes","t":"La tristeza es una languidez desagradable en la que consiste el malestar que el alma recibe del mal o de la carencia que las impresiones del cerebro le presentan como propios.","o":"La tristesse est une langueur désagréable en laquelle consiste l'incommodité que l'âme reçoit du mal, ou du défaut que les impressions du cerveau lui représentent comme lui appartenant.","l":"fr","ob":"Las pasiones del alma","an":"1649","u":"art. 92","te":["tristeza","emociones"]},{"i":"rene-descartes-028","a":"rene-descartes","t":"Sin embargo, son tan distintos que a veces se pueden sufrir dolores con alegría y recibir cosquillas que desagradan.","o":"Toutefois, ils diffèrent si fort qu'on peut quelquefois souffrir des douleurs avec joie, et recevoir des chatouillements qui déplaisent.","l":"fr","ob":"Las pasiones del alma","an":"1649","u":"art. 94","te":["emociones","cuerpo"]},{"i":"rene-descartes-029","a":"rene-descartes","t":"El bien que hicimos nos da una satisfacción interior, la más dulce de todas las pasiones; el mal, en cambio, despierta el arrepentimiento, la más amarga.","o":"Et le bien qui a été fait par nous-mêmes nous donne une satisfaction intérieure, qui est la plus douce de toutes les passions, au lieu que le mal excite le repentir, qui est la plus amère.","l":"fr","ob":"Las pasiones del alma","an":"1649","u":"art. 63","te":["culpa","felicidad"]},{"i":"rene-descartes-030","a":"rene-descartes","t":"A veces la duración del bien causa aburrimiento o hastío, mientras que la duración del mal disminuye la tristeza.","o":"Et quelquefois la durée du bien cause l'ennui ou le dégoût, au lieu que celle du mal diminue la tristesse.","l":"fr","ob":"Las pasiones del alma","an":"1649","u":"art. 67","te":["emociones","tiempo"]},{"i":"rene-descartes-031","a":"rene-descartes","t":"Del bien pasado viene la añoranza, que es una especie de tristeza; y del mal pasado, el alivio alegre, que es una especie de alegría.","o":"Enfin, du bien passé vient le regret, qui est une espèce de tristesse, et du mal passé vient l'allégresse, qui est une espèce de joie.","l":"fr","ob":"Las pasiones del alma","an":"1649","u":"art. 67","te":["duelo","alegria","memoria"]},{"i":"rene-descartes-032","a":"rene-descartes","t":"Y como una de las partes principales de la sabiduría es saber de qué manera y por qué causa cada uno debe estimarse o despreciarse, intentaré dar aquí mi opinión.","o":"Et parce que l'une des principales parties de la sagesse est de savoir en quelle façon et pour quelle cause chacun se doit estimer ou mépriser, je tâcherai ici d'en dire mon opinion.","l":"fr","ob":"Las pasiones del alma","an":"1649","u":"art. 152","te":["autoestima","autoconocimiento"]},{"i":"rene-descartes-033","a":"rene-descartes","t":"Cuáles son las propiedades de la generosidad y cómo sirve de remedio contra todos los desarreglos de las pasiones.","o":"Quelles sont les propriétés de la générosité, et comment elle sert de remède contre tous les dérèglements des passions.","l":"fr","ob":"Las pasiones del alma","an":"1649","u":"art. 156","te":["regulacion-emocional","autoestima"]},{"i":"rene-descartes-034","a":"rene-descartes","t":"Quienes son generosos de esta manera tienden naturalmente a hacer grandes cosas, y sin embargo a no emprender nada de lo que no se sientan capaces.","o":"Ceux qui sont généreux en cette façon sont naturellement portés à faire de grandes choses, et toutefois à ne rien entreprendre dont ils ne se sentent capables.","l":"fr","ob":"Las pasiones del alma","an":"1649","u":"art. 156","te":["autoestima","responsabilidad"]},{"i":"rene-descartes-035","a":"rene-descartes","t":"Y sucede a menudo que quienes tienen el espíritu más bajo son los más arrogantes y soberbios, así como los más generosos son los más modestos y humildes.","o":"et il arrive souvent que ceux qui ont l'esprit le plus bas sont les plus arrogants et superbes, en même façon que les plus généreux sont les plus modestes et les plus humbles.","l":"fr","ob":"Las pasiones del alma","an":"1649","u":"art. 159","te":["autoestima"]},{"i":"rene-descartes-036","a":"rene-descartes","t":"Hay que notar que lo que comúnmente llamamos virtudes son hábitos del alma que la disponen a ciertos pensamientos.","o":"Et il faut remarquer que ce qu'on nomme communément des vertus sont des habitudes en l'âme qui la disposent à certaines pensées","l":"fr","ob":"Las pasiones del alma","an":"1649","u":"art. 161","te":["habitos"]},{"i":"rene-descartes-037","a":"rene-descartes","t":"La esperanza es una disposición del alma a persuadirse de que lo que desea sucederá.","o":"L'espérance est une disposition de l'âme à se persuader que ce qu'elle désire adviendra","l":"fr","ob":"Las pasiones del alma","an":"1649","u":"art. 165","te":["esperanza","emociones"]},{"i":"rene-descartes-038","a":"rene-descartes","t":"Y el temor es otra disposición del alma que la persuade de que no sucederá.","o":"Et la crainte est une autre disposition de l'âme qui lui persuade qu'il n'adviendra pas.","l":"fr","ob":"Las pasiones del alma","an":"1649","u":"art. 165","te":["miedo","emociones"]},{"i":"rene-descartes-039","a":"rene-descartes","t":"La irresolución es también una especie de temor que, reteniendo al alma como en una balanza entre varias acciones posibles, hace que no realice ninguna.","o":"L'irrésolution est aussi une espèce de crainte qui, retenant l'âme comme en balance entre plusieurs actions qu'elle peut faire, est cause qu'elle n'en exécute aucune","l":"fr","ob":"Las pasiones del alma","an":"1649","u":"art. 170","te":["miedo","voluntad","incertidumbre"]},{"i":"rene-descartes-040","a":"rene-descartes","t":"Como la principal causa del miedo es la sorpresa, nada mejor para librarse de él que anticiparse y prepararse para todos los sucesos que podrían causarlo.","o":"Et parce que la principale cause de la peur est la surprise, il n'y a rien de meilleur pour s'en exempter que d'user de préméditation et de se préparer à tous les événements, la crainte desquels la peut causer.","l":"fr","ob":"Las pasiones del alma","an":"1649","u":"art. 176","te":["miedo","regulacion-emocional"]},{"i":"rene-descartes-041","a":"rene-descartes","t":"La envidia, en cuanto pasión, es una especie de tristeza mezclada con odio que surge al ver que les llega un bien a quienes creemos que no lo merecen.","o":"L'envie donc, en tant qu'elle est une passion, est une espèce de tristesse mêlée de haine qui vient de ce qu'on voit arriver du bien à ceux qu'on pense en être indignes.","l":"fr","ob":"Las pasiones del alma","an":"1649","u":"art. 182","te":["emociones","vinculos"]},{"i":"rene-descartes-042","a":"rene-descartes","t":"Por lo demás, no hay vicio que dañe tanto la felicidad de las personas como la envidia.","o":"Au reste, il n'y a aucun vice qui nuise tant à la félicité des hommes que celui de l'envie.","l":"fr","ob":"Las pasiones del alma","an":"1649","u":"art. 184","te":["felicidad","emociones"]},{"i":"rene-descartes-043","a":"rene-descartes","t":"La compasión es una especie de tristeza mezclada con amor o buena voluntad hacia quienes vemos sufrir un mal que no merecen.","o":"La pitié est une espèce de tristesse mêlée d'amour ou de bonne volonté envers ceux à qui nous voyons souffrir quelque mal duquel nous les estimons indignes.","l":"fr","ob":"Las pasiones del alma","an":"1649","u":"art. 185","te":["compasion","empatia"]},{"i":"rene-descartes-044","a":"rene-descartes","t":"Tener buena voluntad hacia cada uno es parte de la generosidad.","o":"Car c'est une partie de la générosité que d'avoir de la bonne volonté pour un chacun.","l":"fr","ob":"Las pasiones del alma","an":"1649","u":"art. 187","te":["compasion","vinculos"]},{"i":"rene-descartes-045","a":"rene-descartes","t":"La satisfacción que tienen siempre quienes siguen con constancia la virtud es un hábito del alma que se llama tranquilidad y paz de conciencia.","o":"La satisfaction qu'ont toujours ceux qui suivent constamment la vertu est une habitude en leur âme qui se nomme tranquillité et repos de conscience.","l":"fr","ob":"Las pasiones del alma","an":"1649","u":"art. 190","te":["felicidad","habitos","silencio"]},{"i":"rene-descartes-046","a":"rene-descartes","t":"El arrepentimiento es lo contrario de la satisfacción de uno mismo: una especie de tristeza que surge de creer que hicimos algo malo; y es muy amarga, porque su causa está solo en nosotros.","o":"Le repentir est directement contraire à la satisfaction de soi-même, et c'est une espèce de tristesse qui vient de ce qu'on croit avoir fait quelque mauvaise action ; et elle est très amère, parce que sa cause ne vient que de nous.","l":"fr","ob":"Las pasiones del alma","an":"1649","u":"art. 191","te":["culpa","tristeza"]},{"i":"rene-descartes-047","a":"rene-descartes","t":"La gratitud es también una especie de amor que despierta en nosotros alguna acción de aquel por quien [la sentimos].","o":"La reconnaissance est aussi une espèce d'amour excitée en nous par quelque action de celui pour qui","l":"fr","ob":"Las pasiones del alma","an":"1649","u":"art. 193","te":["gratitud","amor"]},{"i":"rene-descartes-048","a":"rene-descartes","t":"Por lo demás, la indignación se nota mucho más en quienes quieren parecer virtuosos que en quienes lo son de verdad.","o":"Au reste, l'indignation se remarque bien plus en ceux qui veulent paraître vertueux qu'en ceux qui le sont véritablement.","l":"fr","ob":"Las pasiones del alma","an":"1649","u":"art. 198","te":["autenticidad","ira"]},{"i":"rene-descartes-049","a":"rene-descartes","t":"La vergüenza, en cambio, es una especie de tristeza fundada también en el amor de sí, que nace de la opinión o del temor de ser censurado.","o":"La honte, au contraire, est une espèce de tristesse fondée aussi sur l'amour de soi-même, et qui vient de l'opinion ou de la crainte qu'on a d'être blâmé.","l":"fr","ob":"Las pasiones del alma","an":"1649","u":"art. 205","te":["culpa","autoestima"]},{"i":"rene-descartes-050","a":"rene-descartes","t":"Solo hace falta educar el juicio sobre lo que de verdad merece censura o elogio, para no avergonzarse de obrar bien ni envanecerse de los propios vicios.","o":"Il est seulement besoin d'instruire son jugement touchant ce qui est véritablement digne de blâme ou de louange, afin de n'être pas honteux de bien faire, et ne tirer point de vanité de ses vices","l":"fr","ob":"Las pasiones del alma","an":"1649","u":"art. 206","te":["autoestima","educacion"]},{"i":"rene-descartes-051","a":"rene-descartes","t":"Vemos que [las pasiones] son todas buenas por naturaleza, y que solo tenemos que evitar sus malos usos o sus excesos.","o":"Car nous voyons qu'elles sont toutes bonnes de leur nature, et que nous n'avons","l":"fr","ob":"Las pasiones del alma","an":"1649","u":"art. 211","te":["emociones","aceptacion"]},{"i":"rene-descartes-052","a":"rene-descartes","t":"Pero la sabiduría es útil sobre todo en esto: enseña a dominar las pasiones y a manejarlas con tanta destreza que los males que causan resultan muy soportables, y que hasta se saca alegría de todos ellos.","o":"Mais la sagesse est principalement utile en ce point, qu'elle enseigne à s'en rendre tellement maître et à les ménager avec tant d'adresse, que les maux qu'elles causent sont fort supportables, et même qu'on tire de la joie de tous.","l":"fr","ob":"Las pasiones del alma","an":"1649","u":"art. 212","te":["regulacion-emocional","alegria","resiliencia"]},{"i":"rene-descartes-001","a":"rene-descartes","t":"El buen sentido es la cosa mejor repartida del mundo.","o":"Le bon sens est la chose du monde la mieux partagée","l":"fr","ob":"Discurso del método","an":"1637","u":"","te":["conocimiento","humor"]},{"i":"rene-descartes-002","a":"rene-descartes","t":"No basta con tener buen ingenio: lo principal es aplicarlo bien.","o":"car ce n'est pas assez d'avoir l'esprit bon, mais le principal est de l'appliquer bien.","l":"fr","ob":"Discurso del método","an":"1637","u":"","te":["conocimiento","responsabilidad"]},{"i":"rene-descartes-003","a":"rene-descartes","t":"Las almas más grandes son capaces de los mayores vicios tanto como de las mayores virtudes.","o":"Les plus grandes âmes sont capables des plus grands vices aussi bien que des plus grandes vertus","l":"fr","ob":"Discurso del método","an":"1637","u":"","te":["identidad"]},{"i":"rene-descartes-004","a":"rene-descartes","t":"La lectura de todos los buenos libros es como una conversación con las personas más valiosas de los siglos pasados.","o":"la lecture de tous les bons livres est comme une conversation avec les plus honnêtes gens des siècles passés","l":"fr","ob":"Discurso del método","an":"1637","u":"","te":["educacion","cultura","encuentro"]},{"i":"rene-descartes-005","a":"rene-descartes","t":"Pienso, luego existo.","o":"je pense, donc je suis","l":"fr","ob":"Discurso del método","an":"1637","u":"","te":["conciencia","existencia","identidad"]},{"i":"rene-descartes-006","a":"rene-descartes","t":"Procurar siempre vencerme a mí mismo antes que a la fortuna, y cambiar mis deseos antes que el orden del mundo.","o":"tâcher toujours plutôt à me vaincre que la fortune, et à changer mes désirs que l'ordre du monde","l":"fr","ob":"Discurso del método","an":"1637","u":"","te":["aceptacion","deseo","regulacion-emocional"]},{"i":"rene-descartes-007","a":"rene-descartes","t":"No hay nada que esté enteramente en nuestro poder salvo nuestros pensamientos.","o":"il n'y a rien qui soit entièrement en notre pouvoir que nos pensées","l":"fr","ob":"Discurso del método","an":"1637","u":"","te":["libertad","conciencia"]},{"i":"rene-descartes-008","a":"rene-descartes","t":"No aceptar nunca nada como verdadero sin conocer con evidencia que lo es.","o":"ne recevoir jamais aucune chose pour vraie que je ne la connusse évidemment être telle","l":"fr","ob":"Discurso del método","an":"1637","u":"","te":["verdad","conocimiento"]},{"i":"rene-descartes-009","a":"rene-descartes","t":"[Esta proposición:] yo soy, yo existo, es necesariamente verdadera cada vez que la pronuncio o la concibo en mi mente.","o":"je suis, j'existe, est nécessairement vraie, toutes les fois que je la prononce ou que je la conçois en mon esprit.","l":"fr","ob":"Meditaciones metafísicas","an":"1641 (trad. francesa de 1647)","u":"Meditación 2","te":["existencia","conciencia"]},{"i":"rene-descartes-010","a":"rene-descartes","t":"No soy, entonces, hablando con precisión, más que una cosa que piensa.","o":"je ne suis donc, précisément parlant, qu'une chose qui pense","l":"fr","ob":"Meditaciones metafísicas","an":"1641 (trad. francesa de 1647)","u":"Meditación 2","te":["identidad","conciencia"]},{"i":"john-locke-001","a":"john-locke","t":"Supongamos que la mente es, como se dice, un papel en blanco, sin ningún carácter escrito, sin ideas: ¿cómo llega a llenarse?","o":"Let us then suppose the mind to be, as we say, white paper, void of all characters, without any ideas:-How comes it to be furnished?","l":"en","ob":"Ensayo sobre el entendimiento humano, vol. 1","an":"1690","u":"Libro 2, cap. 1","te":["conocimiento","desarrollo-humano"]},{"i":"john-locke-002","a":"john-locke","t":"El conocimiento de nadie puede ir, en esto, más allá de su experiencia.","o":"No man's knowledge here can go beyond his experience.","l":"en","ob":"Ensayo sobre el entendimiento humano, vol. 1","an":"1690","u":"Libro 2, cap. 1","te":["conocimiento"]},{"i":"john-locke-003","a":"john-locke","t":"La conciencia es la percepción de lo que pasa en la propia mente.","o":"Consciousness is the perception of what passes in a man's own mind.","l":"en","ob":"Ensayo sobre el entendimiento humano, vol. 1","an":"1690","u":"Libro 2, cap. 1","te":["conciencia","autoconocimiento"]},{"i":"john-locke-004","a":"john-locke","t":"Las opiniones nuevas son siempre sospechadas y casi siempre combatidas, sin otra razón que la de no ser todavía comunes.","o":"new opinions are always suspected, and usually opposed, without any other reason but because they are not already common.","l":"en","ob":"Ensayo sobre el entendimiento humano, vol. 1","an":"1690","u":"Libro 2, cap. 33","te":["cambio","sociedad"]},{"i":"john-locke-005","a":"john-locke","t":"La verdad casi nunca ganó por votación cuando apareció por primera vez.","o":"Truth scarce ever yet carried it by vote anywhere at its first appearance","l":"en","ob":"Ensayo sobre el entendimiento humano, vol. 1","an":"1690","u":"Libro 2, cap. 33","te":["verdad","sociedad"]},{"i":"john-locke-006","a":"john-locke","t":"Es ambición suficiente trabajar como peón despejando un poco el terreno y quitando algunos escombros del camino hacia el conocimiento.","o":"it is ambition enough to be employed as an under-labourer in clearing the ground a little, and removing some of the rubbish that lies in the way to knowledge","l":"en","ob":"Ensayo sobre el entendimiento humano, vol. 1","an":"1690","u":"Libro 2, cap. 33","te":["conocimiento","trabajo"]},{"i":"john-locke-007","a":"john-locke","t":"Los hábitos, sobre todo los que empiezan muy temprano, terminan produciendo en nosotros acciones que a menudo escapan a nuestra observación.","o":"Habits, especially such as are begun very early, come at last to produce actions in us, which often escape our observation.","l":"en","ob":"Ensayo sobre el entendimiento humano, vol. 1","an":"1690","u":"Libro 2, cap. 9","te":["habitos","inconsciente","infancia"]},{"i":"john-locke-008","a":"john-locke","t":"Cómo la facilidad que adquirimos por la costumbre de hacer algo hace que muchas veces pase en nosotros sin que lo notemos.","o":"how the facility which we get of doing things, by a custom of doing, makes them often pass in us without our notice.","l":"en","ob":"Ensayo sobre el entendimiento humano, vol. 1","an":"1690","u":"Libro 2, cap. 9","te":["habitos","atencion"]},{"i":"john-locke-009","a":"john-locke","t":"Quienes por costumbre adquirieron una muletilla la pronuncian casi en cada frase: los demás la notan, pero ellos mismos ni la oyen ni la advierten.","o":"Men that, by custom, have got the use of a by-word, do almost in every sentence pronounce sounds which, though taken notice of by others, they themselves neither hear nor observe.","l":"en","ob":"Ensayo sobre el entendimiento humano, vol. 1","an":"1690","u":"Libro 2, cap. 9","te":["habitos","comunicacion","autoconocimiento"]},{"i":"john-locke-010","a":"john-locke","t":"En una criatura inteligente, la memoria es lo más necesario después de la percepción.","o":"Memory, in an intellectual creature, is necessary in the next degree to perception.","l":"en","ob":"Ensayo sobre el entendimiento humano, vol. 1","an":"1690","u":"Libro 2, cap. 10","te":["memoria"]},{"i":"john-locke-011","a":"john-locke","t":"No es fácil para la mente desprenderse de las nociones confusas y los prejuicios que absorbió de la costumbre, la distracción y la conversación corriente.","o":"It is not easy for the mind to put off those confused notions and prejudices it has imbibed from custom, inadvertency, and common conversation.","l":"en","ob":"Ensayo sobre el entendimiento humano, vol. 1","an":"1690","u":"Libro 2, cap. 13","te":["cambio","conocimiento"]},{"i":"john-locke-012","a":"john-locke","t":"El placer y el dolor, y lo que los causa —el bien y el mal—, son los goznes sobre los que giran nuestras pasiones.","o":"Pleasure and pain and that which causes them,-good and evil, are the hinges on which our passions turn.","l":"en","ob":"Ensayo sobre el entendimiento humano, vol. 1","an":"1690","u":"Libro 2, cap. 20","te":["emociones"]},{"i":"john-locke-013","a":"john-locke","t":"La inquietud que una persona siente ante la ausencia de algo cuyo disfrute le traería deleite es lo que llamamos deseo.","o":"The uneasiness a man finds in himself upon the absence of anything whose present enjoyment carries the idea of delight with it, is that we call DESIRE","l":"en","ob":"Ensayo sobre el entendimiento humano, vol. 1","an":"1690","u":"Libro 2, cap. 20","te":["deseo","emociones"]},{"i":"john-locke-014","a":"john-locke","t":"El deseo también se detiene o se apaga ante la opinión de que el bien buscado es imposible o inalcanzable.","o":"Desire also is stopped or abated by the opinion of the impossibility or unattainableness of the good proposed","l":"en","ob":"Ensayo sobre el entendimiento humano, vol. 1","an":"1690","u":"Libro 2, cap. 20","te":["deseo","esperanza"]},{"i":"john-locke-015","a":"john-locke","t":"La alegría es un deleite de la mente al considerar la posesión presente, o segura y próxima, de un bien.","o":"JOY is a delight of the mind, from the consideration of the present or assured approaching possession of a good","l":"en","ob":"Ensayo sobre el entendimiento humano, vol. 1","an":"1690","u":"Libro 2, cap. 20","te":["alegria","emociones"]},{"i":"john-locke-016","a":"john-locke","t":"La tristeza es una inquietud de la mente al pensar en un bien perdido del que se podría haber disfrutado más tiempo, o al sentir un mal presente.","o":"SORROW is uneasiness in the mind, upon the thought of a good lost, which might have been enjoyed longer; or the sense of a present evil.","l":"en","ob":"Ensayo sobre el entendimiento humano, vol. 1","an":"1690","u":"Libro 2, cap. 20","te":["tristeza","duelo","emociones"]},{"i":"john-locke-017","a":"john-locke","t":"La esperanza es ese placer de la mente que cada uno encuentra en sí al pensar en el disfrute futuro y probable de algo que puede deleitarlo.","o":"HOPE is that pleasure in the mind, which every one finds in himself, upon the thought of a probable future enjoyment of a thing which is apt to delight him.","l":"en","ob":"Ensayo sobre el entendimiento humano, vol. 1","an":"1690","u":"Libro 2, cap. 20","te":["esperanza","emociones"]},{"i":"john-locke-018","a":"john-locke","t":"El miedo es una inquietud de la mente al pensar en un mal futuro que probablemente nos alcance.","o":"FEAR is an uneasiness of the mind, upon the thought of future evil likely to befall us.","l":"en","ob":"Ensayo sobre el entendimiento humano, vol. 1","an":"1690","u":"Libro 2, cap. 20","te":["miedo","angustia","emociones"]},{"i":"john-locke-019","a":"john-locke","t":"La desesperación es pensar que un bien es inalcanzable; obra de modo distinto en cada mente: a veces produce inquietud o dolor, a veces quietud e indolencia.","o":"DESPAIR is the thought of the unattainableness of any good, which works differently in men's minds, sometimes producing uneasiness or pain, sometimes rest and indolency.","l":"en","ob":"Ensayo sobre el entendimiento humano, vol. 1","an":"1690","u":"Libro 2, cap. 20","te":["angustia","emociones"]},{"i":"john-locke-020","a":"john-locke","t":"La ira es la inquietud o la turbación de la mente al recibir una ofensa, con el propósito presente de vengarse.","o":"ANGER is uneasiness or discomposure of the mind, upon the receipt of any injury, with a present purpose of revenge.","l":"en","ob":"Ensayo sobre el entendimiento humano, vol. 1","an":"1690","u":"Libro 2, cap. 20","te":["ira","emociones"]},{"i":"john-locke-021","a":"john-locke","t":"La envidia es una inquietud de la mente causada por ver un bien que deseamos en manos de alguien que, creemos, no debería haberlo tenido antes que nosotros.","o":"ENVY is an uneasiness of the mind, caused by the consideration of a good we desire obtained by one we think should not have had it before us.","l":"en","ob":"Ensayo sobre el entendimiento humano, vol. 1","an":"1690","u":"Libro 2, cap. 20","te":["emociones","vinculos"]},{"i":"john-locke-022","a":"john-locke","t":"La vergüenza, que es una inquietud de la mente al pensar que hicimos algo indecoroso o que disminuirá la estima que otros nos tienen, no siempre va acompañada de rubor.","o":"For SHAME, which is an uneasiness of the mind upon the thought of having done something which is indecent, or will lessen the valued esteem which others have for us, has not always blushing accompanying it.","l":"en","ob":"Ensayo sobre el entendimiento humano, vol. 1","an":"1690","u":"Libro 2, cap. 20","te":["culpa","emociones","autoestima"]},{"i":"john-locke-023","a":"john-locke","t":"Todo dolor del cuerpo, de cualquier tipo, y toda intranquilidad de la mente son inquietud; y a ella siempre se une un deseo igual al dolor o a la inquietud que se siente.","o":"All pain of the body, of what sort soever, and disquiet of the mind, is uneasiness: and with this is always joined desire, equal to the pain or uneasiness felt","l":"en","ob":"Ensayo sobre el entendimiento humano, vol. 1","an":"1690","u":"Libro 2, cap. 21","te":["sufrimiento","deseo","cuerpo"]},{"i":"john-locke-024","a":"john-locke","t":"Que el deseo es un estado de inquietud lo descubrirá enseguida cualquiera que reflexione sobre sí mismo.","o":"That desire is a state of uneasiness, every one who reflects on himself will quickly find.","l":"en","ob":"Ensayo sobre el entendimiento humano, vol. 1","an":"1690","u":"Libro 2, cap. 21","te":["deseo","autoconocimiento"]},{"i":"john-locke-025","a":"john-locke","t":"Cuando alguien está perfectamente contento con su estado, es decir, sin ninguna inquietud, ¿qué esfuerzo, qué acción, qué voluntad le queda, salvo seguir en él?","o":"When a man is perfectly content with the state he is in-which is when he is perfectly without any uneasiness-what industry, what action, what will is there left, but to continue in it?","l":"en","ob":"Ensayo sobre el entendimiento humano, vol. 1","an":"1690","u":"Libro 2, cap. 21","te":["deseo","felicidad","cambio"]},{"i":"john-locke-026","a":"john-locke","t":"Estoy seguro de que donde hay inquietud, hay deseo.","o":"I am sure wherever there is uneasiness, there is desire.","l":"en","ob":"Ensayo sobre el entendimiento humano, vol. 1","an":"1690","u":"Libro 2, cap. 21","te":["deseo"]},{"i":"john-locke-027","a":"john-locke","t":"Deseamos constantemente la felicidad, y cuanto sentimos de inquietud, tanto nos falta, sin duda, de felicidad.","o":"For we constantly desire happiness; and whatever we feel of uneasiness, so much it is certain we want of happiness","l":"en","ob":"Ensayo sobre el entendimiento humano, vol. 1","an":"1690","u":"Libro 2, cap. 21","te":["felicidad","deseo"]},{"i":"john-locke-028","a":"john-locke","t":"La mayor inquietud presente es el aguijón de la acción: es la que más se siente y la que, casi siempre, determina la voluntad al elegir la acción siguiente.","o":"The greatest present uneasiness is the spur to action, that is constantly most felt, and for the most part determines the will in its choice of the next action.","l":"en","ob":"Ensayo sobre el entendimiento humano, vol. 1","an":"1690","u":"Libro 2, cap. 21","te":["voluntad","deseo"]},{"i":"john-locke-029","a":"john-locke","t":"Una vez quitada toda inquietud, una porción moderada de bien basta para contentar a las personas.","o":"All uneasiness therefore being removed, a moderate portion of good serve at present to content men","l":"en","ob":"Ensayo sobre el entendimiento humano, vol. 1","an":"1690","u":"Libro 2, cap. 21","te":["felicidad","aceptacion"]},{"i":"john-locke-030","a":"john-locke","t":"Pero en cuanto llega una nueva inquietud, esa felicidad se altera y volvemos a ponernos en marcha tras ella.","o":"But as soon as any new uneasiness comes in, this happiness is disturbed, and we are set afresh on work in the pursuit of happiness.","l":"en","ob":"Ensayo sobre el entendimiento humano, vol. 1","an":"1690","u":"Libro 2, cap. 21","te":["felicidad","deseo"]},{"i":"john-locke-031","a":"john-locke","t":"Nada, pensamos apasionadamente, puede superar ni casi igualar la inquietud que pesa tanto sobre nosotros.","o":"Nothing, as we passionately think, can exceed, or almost equal, the uneasiness that sits so heavy upon us.","l":"en","ob":"Ensayo sobre el entendimiento humano, vol. 1","an":"1690","u":"Libro 2, cap. 21","te":["sufrimiento","angustia"]},{"i":"john-locke-032","a":"john-locke","t":"Además, el bien ausente, es decir, el placer futuro, sobre todo si es de una clase que no conocemos, rara vez logra contrapesar una inquietud presente de dolor o de deseo.","o":"Add to this, that absent good, or, which is the same thing, future pleasure,-especially if of a sort we are unacquainted with,-seldom is able to counterbalance any uneasiness, either of pain or desire, which is present.","l":"en","ob":"Ensayo sobre el entendimiento humano, vol. 1","an":"1690","u":"Libro 2, cap. 21","te":["deseo","tiempo","habitos"]},{"i":"john-locke-033","a":"john-locke","t":"En algunos casos bastará una reflexión adecuada; en la mayoría, la práctica, la dedicación y la costumbre.","o":"A due consideration will do it in some cases; and practice, application, and custom in most.","l":"en","ob":"Ensayo sobre el entendimiento humano, vol. 1","an":"1690","u":"Libro 2, cap. 21","te":["habitos","cambio"]},{"i":"john-locke-034","a":"john-locke","t":"Cuando la moda y la opinión común instalaron ideas equivocadas, y la educación y la costumbre malos hábitos, el justo valor de las cosas se desplaza y el gusto de las personas se corrompe.","o":"Fashion and the common opinion having settled wrong notions, and education and custom ill habits, the just values of things are misplaced, and the palates of men corrupted.","l":"en","ob":"Ensayo sobre el entendimiento humano, vol. 1","an":"1690","u":"Libro 2, cap. 21","te":["habitos","sociedad","educacion"]},{"i":"john-locke-035","a":"john-locke","t":"Hay que esforzarse por corregirlo: los hábitos contrarios cambian nuestros placeres y le dan gusto a lo que es necesario o conduce a nuestra felicidad.","o":"Pains should be taken to rectify these; and contrary habits change our pleasures, and give a relish to that which is necessary or conducive to our happiness.","l":"en","ob":"Ensayo sobre el entendimiento humano, vol. 1","an":"1690","u":"Libro 2, cap. 21","te":["habitos","cambio","felicidad"]},{"i":"john-locke-036","a":"john-locke","t":"Las ideas de duendes y espíritus no tienen en realidad más que ver con la oscuridad que con la luz; pero basta que alguien se las inculque a menudo a un niño y las asocie [para que ya no pueda separarlas].","o":"The ideas of goblins and sprites have really no more to do with darkness than light: yet let but a foolish maid inculcate these often on the mind of a child, and raise them there together","l":"en","ob":"Ensayo sobre el entendimiento humano, vol. 1","an":"1690","u":"Libro 2, cap. 33","te":["miedo","infancia","inconsciente"]},{"i":"john-locke-037","a":"john-locke","t":"Ideas que en sí mismas no tienen nada que ver llegan a unirse tanto en la mente de algunas personas que es muy difícil separarlas: siempre van juntas.","o":"Ideas that in themselves are not all of kin, come to be so united in some men's minds, that it is very hard to separate them; they always keep in company","l":"en","ob":"Ensayo sobre el entendimiento humano, vol. 1","an":"1690","u":"Libro 2, cap. 33","te":["inconsciente","memoria","conciencia"]},{"i":"john-locke-038","a":"john-locke","t":"Si la costumbre, desde la infancia, unió una figura a la idea de Dios, ¿en qué absurdos podrá caer esa mente acerca de la divinidad?","o":"Let custom from the very childhood have joined figure and shape to the idea of God, and what absurdities will that mind be liable to about the Deity?","l":"en","ob":"Ensayo sobre el entendimiento humano, vol. 1","an":"1690","u":"Libro 2, cap. 33","te":["infancia","trascendencia"]},{"i":"john-locke-039","a":"john-locke","t":"El odio o el amor hacia seres capaces de dicha o desdicha suelen ser la inquietud o el deleite que encontramos en nosotros por su sola existencia o su felicidad.","o":"But hatred or love, to beings capable of happiness or misery, is often the uneasiness of delight which we find in ourselves, arising from their very being or happiness.","l":"en","ob":"Ensayo sobre el entendimiento humano, vol. 1","an":"1690","u":"Libro 2, cap. 20","te":["amor","ira","vinculos"]},{"i":"john-locke-040","a":"john-locke","t":"La aversión, el miedo, la ira, la envidia, la vergüenza, etcétera, tienen cada uno su propia inquietud, y por eso influyen en la voluntad.","o":"Aversion, fear, anger, envy, shame, &c. have each their uneasinesses too, and thereby influence the will.","l":"en","ob":"Ensayo sobre el entendimiento humano, vol. 1","an":"1690","u":"Libro 2, cap. 21","te":["emociones","voluntad"]},{"i":"john-locke-041","a":"john-locke","t":"El bien que reconocemos como infinitamente mayor suele quedar descuidado para satisfacer la inquietud sucesiva de deseos que persiguen nimiedades.","o":"the infinitely greatest confessed good being often neglected, to satisfy the successive uneasiness of our desires pursuing trifles.","l":"en","ob":"Ensayo sobre el entendimiento humano, vol. 1","an":"1690","u":"Libro 2, cap. 21","te":["deseo","sentido-de-vida"]},{"i":"john-locke-042","a":"john-locke","t":"Solo la inquietud determina la voluntad.","o":"it is uneasiness alone determines the will","l":"en","ob":"Ensayo sobre el entendimiento humano, vol. 1","an":"1690","u":"Libro 2, cap. 21","te":["voluntad","deseo"]},{"i":"john-locke-043","a":"john-locke","t":"Las necesidades corrientes de la vida la llenan en gran parte con las inquietudes del hambre, la sed, el calor, el frío, el cansancio, el trabajo y el sueño, que vuelven una y otra vez.","o":"The ordinary necessities of our lives fill a great part of them with the uneasinesses of hunger, thirst, heat, cold, weariness, with labour, and sleepiness, in their constant returns","l":"en","ob":"Ensayo sobre el entendimiento humano, vol. 1","an":"1690","u":"Libro 2, cap. 21","te":["cuerpo","existencia"]},{"i":"john-locke-050","a":"john-locke","t":"Los niños, aunque puedan tener ideas en el vientre materno, no tienen ninguna innata.","o":"Children, though they may have Ideas in the Womb, have none innate.","l":"en","ob":"Ensayo sobre el entendimiento humano, vol. 1","an":"1690","u":"Libro 2, cap. 9","te":["infancia","desarrollo-humano"]},{"i":"john-locke-044","a":"john-locke","t":"Por eso algunos, no solo niños sino también adultos, dicen muchas palabras como loros, solo porque las aprendieron y se acostumbraron a esos sonidos.","o":"therefore some, not only children but men, speak several words no otherwise than parrots do, only because they have learned them, and have been accustomed to those sounds.","l":"en","ob":"Ensayo sobre el entendimiento humano, vol. 2","an":"1690","u":"Libro 3, cap. 2","te":["comunicacion","habitos"]},{"i":"john-locke-045","a":"john-locke","t":"Es evidente cuánto les gusta a las personas engañar y ser engañadas.","o":"It is evident how much men love to deceive and be deceived","l":"en","ob":"Ensayo sobre el entendimiento humano, vol. 2","an":"1690","u":"Libro 3, cap. 10","te":["verdad","comunicacion"]},{"i":"john-locke-046","a":"john-locke","t":"Las ideas de la nodriza y de la madre están bien formadas en su mente [de los niños] y, como retratos, representan solo a esas personas.","o":"The ideas of the nurse and the mother are well framed in their minds; and, like pictures of them there, represent only those individuals.","l":"en","ob":"Ensayo sobre el entendimiento humano, vol. 2","an":"1690","u":"Libro 3, cap. 3","te":["infancia","familia","desarrollo-humano"]},{"i":"john-locke-047","a":"john-locke","t":"La experiencia nos convence de que tenemos un conocimiento intuitivo de nuestra propia existencia, una percepción interna e infalible de que somos.","o":"Experience then convinces us, that we have an INTUITIVE KNOWLEDGE of our own existence, and an internal infallible perception that we are.","l":"en","ob":"Ensayo sobre el entendimiento humano, vol. 2","an":"1690","u":"Libro 4, cap. 9","te":["conciencia","existencia"]},{"i":"john-locke-048","a":"john-locke","t":"En esta parte debemos apoyarnos en la experiencia.","o":"Experience is that which in this part we must depend on.","l":"en","ob":"Ensayo sobre el entendimiento humano, vol. 2","an":"1690","u":"Libro 4, cap. 3","te":["conocimiento"]},{"i":"john-locke-049","a":"john-locke","t":"Porque muchas palabras se aprenden antes de conocer las ideas que representan.","o":"because words are many of them learned before the ideas are known for which they stand","l":"en","ob":"Ensayo sobre el entendimiento humano, vol. 2","an":"1690","u":"Libro 3, cap. 2","te":["comunicacion","infancia"]},{"i":"buda-001","a":"buda","t":"Todo lo que somos es el resultado de lo que hemos pensado: está fundado en nuestros pensamientos, está hecho de nuestros pensamientos.","o":"All that we are is the result of what we have thought: it is founded on our thoughts, it is made up of our thoughts.","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 1","te":["conciencia","identidad"]},{"i":"buda-002","a":"buda","t":"El odio nunca cesa con el odio: el odio cesa con el amor. Esta es una ley antigua.","o":"For hatred does not cease by hatred at any time: hatred ceases by love, this is an old rule.","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 1, verso 5","te":["ira","amor","compasion"]},{"i":"buda-003","a":"buda","t":"El mundo no sabe que todos hemos de terminar aquí; pero quienes lo saben, dejan enseguida de pelear.","o":"The world does not know that we must all come to an end here;--but those who know it, their quarrels cease at once.","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 1, verso 6","te":["muerte","vinculos"]},{"i":"buda-004","a":"buda","t":"Quienes imaginan verdad en lo falso y ven falsedad en lo verdadero nunca llegan a la verdad: siguen deseos vanos.","o":"They who imagine truth in untruth, and see untruth in truth, never arrive at truth, but follow vain desires.","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 1, verso 11","te":["verdad","deseo"]},{"i":"buda-005","a":"buda","t":"Así como la lluvia no atraviesa una casa bien techada, la pasión no atraviesa una mente que reflexiona.","o":"As rain does not break through a well-thatched house, passion will not break through a well-reflecting mind.","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 1, verso 14","te":["regulacion-emocional","conciencia"]},{"i":"buda-006","a":"buda","t":"Despertándose, con empeño, con mesura y dominio de sí, el sabio puede hacerse una isla que ninguna inundación logre cubrir.","o":"By rousing himself, by earnestness, by restraint and control, the wise man may make for himself an island which no flood can overwhelm.","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 2, verso 25","te":["resiliencia","autoconocimiento"]},{"i":"buda-007","a":"buda","t":"Atento entre los distraídos, despierto entre los dormidos, el sabio avanza como un caballo de carrera que deja atrás al rocín.","o":"Earnest among the thoughtless, awake among the sleepers, the wise man advances like a racer, leaving behind the hack.","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 2, verso 29","te":["atencion","presencia"]},{"i":"buda-008","a":"buda","t":"Es bueno domar la mente, difícil de sujetar y voluble, que corre adonde se le antoja: una mente domada trae felicidad.","o":"It is good to tame the mind, which is difficult to hold in and flighty, rushing wherever it listeth; a tamed mind brings happiness.","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 3, verso 35","te":["atencion","felicidad","regulacion-emocional"]},{"i":"buda-009","a":"buda","t":"Que el sabio cuide sus pensamientos, porque son difíciles de percibir, muy astutos, y corren adonde quieren: los pensamientos bien cuidados traen felicidad.","o":"Let the wise man guard his thoughts, for they are difficult to perceive, very artful, and they rush wherever they list: thoughts well guarded bring happiness.","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 3, verso 36","te":["conciencia","atencion"]},{"i":"buda-010","a":"buda","t":"Lo que un enemigo pueda hacerle a otro enemigo, más daño nos hará una mente mal dirigida.","o":"Whatever a hater may do to a hater, or an enemy to an enemy, a wrongly-directed mind will do us greater mischief.","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 3, verso 42","te":["conciencia","sufrimiento"]},{"i":"buda-011","a":"buda","t":"Ni una madre, ni un padre, ni ningún otro pariente harán tanto por nosotros como una mente bien dirigida.","o":"Not a mother, not a father will do so much, nor any other relative; a well-directed mind will do us greater service.","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 3, verso 43","te":["conciencia","familia"]},{"i":"buda-012","a":"buda","t":"No las faltas de los otros, ni lo que hicieron o dejaron de hacer: el sabio debe fijarse en sus propios errores y descuidos.","o":"Not the perversities of others, not their sins of commission or omission, but his own misdeeds and negligences should a sage take notice of.","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 4, verso 50","te":["autoconocimiento","responsabilidad"]},{"i":"buda-013","a":"buda","t":"Como una flor hermosa, llena de color pero sin perfume, son las palabras bellas y estériles de quien no actúa en consecuencia.","o":"Like a beautiful flower, full of colour, but without scent, are the fine but fruitless words of him who does not act accordingly.","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 4, verso 51","te":["autenticidad","comunicacion"]},{"i":"buda-014","a":"buda","t":"Si un caminante no encuentra a alguien mejor o igual que él, que siga con firmeza su camino solitario: no hay compañía posible con un necio.","o":"If a traveller does not meet with one who is his better, or his equal, let him firmly keep to his solitary journey; there is no companionship with a fool.","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 5, verso 61","te":["soledad","vinculos"]},{"i":"buda-015","a":"buda","t":"El necio que conoce su necedad es, al menos en eso, sabio. Pero el necio que se cree sabio es un necio de verdad.","o":"The fool who knows his foolishness, is wise at least so far. But a fool who thinks himself wise, he is called a fool indeed.","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 5, verso 63","te":["autoconocimiento","conocimiento"]},{"i":"buda-016","a":"buda","t":"Como una roca firme no se mueve con el viento, los sabios no vacilan entre la crítica y el elogio.","o":"As a solid rock is not shaken by the wind, wise people falter not amidst blame and praise.","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 6, verso 81","te":["resiliencia","autoestima"]},{"i":"buda-017","a":"buda","t":"Los sabios, después de escuchar la enseñanza, se vuelven serenos como un lago profundo, liso y quieto.","o":"Wise people, after they have listened to the laws, become serene, like a deep, smooth, and still lake.","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 6, verso 82","te":["silencio","presencia"]},{"i":"buda-018","a":"buda","t":"Si uno vence en batalla mil veces a mil hombres, y otro se vence a sí mismo, este es el mayor de los vencedores.","o":"If one man conquer in battle a thousand times thousand men, and if another conquer himself, he is the greatest of conquerors.","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 8, verso 103","te":["autoconocimiento","regulacion-emocional"]},{"i":"buda-019","a":"buda","t":"Si alguien obra mal, que no lo repita ni se complazca en ello: el dolor es el fruto del mal.","o":"If a man commits a sin, let him not do it again; let him not delight in sin: pain is the outcome of evil.","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 9, verso 117","te":["responsabilidad","habitos"]},{"i":"buda-020","a":"buda","t":"Si alguien obra bien, que lo repita y se alegre en ello: la felicidad es el fruto del bien.","o":"If a man does what is good, let him do it again; let him delight in it: happiness is the outcome of good.","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 9, verso 118","te":["habitos","felicidad"]},{"i":"buda-021","a":"buda","t":"Gota a gota se llena un cántaro.","o":"Even by the falling of water-drops a water-pot is filled","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 9, verso 121","te":["habitos","cambio"]},{"i":"buda-022","a":"buda","t":"Quien aprendió poco envejece como un buey: crece su carne, pero no su conocimiento.","o":"A man who has learnt little, grows old like an ox; his flesh grows, but his knowledge does not grow.","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 11, verso 152","te":["educacion","desarrollo-humano"]},{"i":"buda-023","a":"buda","t":"Que cada uno se encamine primero hacia lo correcto y después enseñe a otros: así el sabio no sufrirá.","o":"Let each man direct himself first to what is proper, then let him teach others; thus a wise man will not suffer.","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 12, verso 158","te":["autenticidad","educacion"]},{"i":"buda-024","a":"buda","t":"Uno mismo es dueño de sí: ¿quién más podría serlo? Con uno mismo bien dominado, se encuentra un señor como pocos encuentran.","o":"Self is the lord of self, who else could be the lord? With self well subdued, a man finds a lord such as few can find.","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 12, verso 160","te":["autoconocimiento","libertad"]},{"i":"buda-025","a":"buda","t":"Lo malo y lo que nos daña es fácil de hacer; lo beneficioso y bueno es muy difícil.","o":"Bad deeds, and deeds hurtful to ourselves, are easy to do; what is beneficial and good, that is very difficult to do.","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 12, verso 163","te":["habitos","voluntad"]},{"i":"buda-026","a":"buda","t":"Por uno mismo se hace el mal, por uno mismo se sufre; por uno mismo se deja de hacerlo, por uno mismo uno se purifica.","o":"By oneself the evil is done, by oneself one suffers; by oneself evil is left undone, by oneself one is purified.","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 12, verso 165","te":["responsabilidad","transformacion-personal"]},{"i":"buda-027","a":"buda","t":"Mirá el mundo como una burbuja, miralo como un espejismo.","o":"Look upon the world as a bubble, look upon it as a mirage","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 13, verso 170","te":["existencia","cambio"]},{"i":"buda-028","a":"buda","t":"No hacer ningún mal, hacer el bien y purificar la propia mente: esa es la enseñanza de todos los Despiertos.","o":"Not to commit any sin, to do good, and to purify one's mind, that is the teaching of (all) the Awakened.","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 14, verso 183","te":["trascendencia","conciencia"]},{"i":"buda-029","a":"buda","t":"No hay manera de saciar los deseos, ni siquiera con una lluvia de monedas de oro.","o":"There is no satisfying lusts, even by a shower of gold pieces","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 14, verso 186","te":["deseo","felicidad"]},{"i":"buda-030","a":"buda","t":"La victoria engendra odio, porque el vencido es desdichado. Quien renunció a la victoria y a la derrota, ese, el contento, es feliz.","o":"Victory breeds hatred, for the conquered is unhappy. He who has given up both victory and defeat, he, the contented, is happy.","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 15, verso 201","te":["felicidad","ira","vinculos"]},{"i":"buda-031","a":"buda","t":"La salud es el mayor de los dones; el contento, la mejor riqueza; la confianza, el mejor de los vínculos; el nirvana, la felicidad suprema.","o":"Health is the greatest of gifts, contentedness the best riches; trust is the best of relationships, Nirvana the highest happiness.","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 15, verso 204","te":["felicidad","vinculos","cuerpo"]},{"i":"buda-032","a":"buda","t":"Quien probó la dulzura de la soledad y la calma queda libre del miedo y del mal.","o":"He who has tasted the sweetness of solitude and tranquillity, is free from fear and free from sin","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 15, verso 205","te":["soledad","silencio","miedo"]},{"i":"buda-033","a":"buda","t":"Del apego nace la pena, del apego nace el miedo; quien está libre del apego no conoce la pena ni el miedo.","o":"From love comes grief, from love comes fear; he who is free from love knows neither grief nor fear.","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 16, verso 215","te":["amor","duelo","miedo"]},{"i":"buda-034","a":"buda","t":"A quien frena la ira que surge como a un carro desbocado, a ese llamo verdadero conductor; los demás solo sostienen las riendas.","o":"He who holds back rising anger like a rolling chariot, him I call a real driver; other people are but holding the reins.","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 17, verso 222","te":["ira","regulacion-emocional"]},{"i":"buda-035","a":"buda","t":"Que se venza la ira con amor, el mal con el bien, la avaricia con generosidad y la mentira con la verdad.","o":"Let a man overcome anger by love, let him overcome evil by good; let him overcome the greedy by liberality, the liar by truth!","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 17, verso 223","te":["ira","compasion","verdad"]},{"i":"buda-036","a":"buda","t":"Decí la verdad, no cedas a la ira; da, aunque te pidan poco.","o":"Speak the truth, do not yield to anger; give, if thou art asked for little","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 17, verso 224","te":["verdad","ira"]},{"i":"buda-037","a":"buda","t":"No hubo, no habrá ni hay ahora nadie que sea siempre criticado, ni nadie que sea siempre elogiado.","o":"There never was, there never will be, nor is there now, a man who is always blamed, or a man who is always praised.","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 17, verso 228","te":["autoestima","aceptacion"]},{"i":"buda-038","a":"buda","t":"Hacete una isla, trabajá con empeño, sé sabio.","o":"Make thyself an island, work hard, be wise!","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 18, verso 236","te":["resiliencia","autoconocimiento"]},{"i":"buda-039","a":"buda","t":"La falta ajena se ve con facilidad; la propia, con dificultad.","o":"The fault of others is easily perceived, but that of oneself is difficult to perceive","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 18, verso 252","te":["autoconocimiento","vinculos"]},{"i":"buda-040","a":"buda","t":"Si alguien vive pendiente de las faltas de los demás y siempre dispuesto a ofenderse, sus propias pasiones crecerán.","o":"If a man looks after the faults of others, and is always inclined to be offended, his own passions will grow","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 18, verso 253","te":["ira","autoconocimiento"]},{"i":"buda-041","a":"buda","t":"Nadie es sabio por hablar mucho; sabio es quien es paciente y está libre de odio y de miedo.","o":"A man is not learned because he talks much; he who is patient, free from hatred and fear, he is called learned.","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 19, verso 258","te":["conocimiento","miedo"]},{"i":"buda-042","a":"buda","t":"Vos mismo tenés que hacer el esfuerzo. Los Budas solo enseñan el camino.","o":"You yourself must make an effort. The Tathagatas (Buddhas) are only preachers.","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 20, verso 276","te":["responsabilidad","transformacion-personal"]},{"i":"buda-043","a":"buda","t":"“Todo lo creado perece”: quien sabe y ve esto se vuelve sereno ante el dolor.","o":"'All created things perish,' he who knows and sees this becomes passive in pain","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 20, verso 277","te":["cambio","aceptacion","sufrimiento"]},{"i":"buda-044","a":"buda","t":"Con dedicación se gana el conocimiento; sin ella, se pierde.","o":"Through zeal knowledge is gotten, through lack of zeal knowledge is lost","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 20, verso 282","te":["educacion","habitos"]},{"i":"buda-045","a":"buda","t":"Si algo debe hacerse, que se haga, y con decisión.","o":"If anything is to be done, let a man do it, let him attack it vigorously!","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 22, verso 313","te":["voluntad","responsabilidad"]},{"i":"buda-046","a":"buda","t":"Esta mente mía andaba antes errante por donde quería, como se le antojaba, como le placía.","o":"This mind of mine went formerly wandering about as it liked, as it listed, as it pleased","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 23, verso 326","te":["atencion","conciencia"]},{"i":"buda-047","a":"buda","t":"No seas descuidado, vigilá tus pensamientos. Salí del mal camino como un elefante hundido en el barro.","o":"Be not thoughtless, watch your thoughts! Draw yourself out of the evil way, like an elephant sunk in mud.","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 23, verso 327","te":["atencion","cambio"]},{"i":"buda-048","a":"buda","t":"Soltá lo que está adelante, soltá lo que está atrás, soltá lo que está en el medio.","o":"Give up what is before, give up what is behind, give up what is in the middle","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 24, verso 348","te":["aceptacion","presencia"]},{"i":"buda-049","a":"buda","t":"Sin conocimiento no hay meditación; sin meditación no hay conocimiento.","o":"Without knowledge there is no meditation, without meditation there is no knowledge","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 25, verso 372","te":["conocimiento","silencio"]},{"i":"buda-050","a":"buda","t":"Despertate por vos mismo, examinate por vos mismo: así, protegido por vos mismo y atento, vivirás feliz.","o":"Rouse thyself by thyself, examine thyself by thyself, thus self-protected and attentive wilt thou live happily","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 25, verso 379","te":["autoconocimiento","atencion","felicidad"]},{"i":"buda-051","a":"buda","t":"Que nadie menosprecie el bien diciéndose: “No llegará a mí”.","o":"Let no man think lightly of good, saying in his heart, It will not come nigh unto me.","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 9, verso 122","te":["esperanza","habitos"]},{"i":"buda-052","a":"buda","t":"Como un pez sacado del agua y arrojado a tierra seca, nuestro pensamiento tiembla por entero.","o":"As a fish taken from his watery home and thrown on dry ground, our thought trembles all over","l":"en","ob":"Dhammapada","an":"s. III a. C.","u":"Capítulo 3, verso 34","te":["angustia","conciencia"]},{"i":"lao-tse-001","a":"lao-tse","t":"El Tao que puede recorrerse no es el Tao permanente e inmutable. El nombre que puede nombrarse no es el nombre permanente e inmutable.","o":"The Tao that can be trodden is not the enduring and unchanging Tao. The name that can be named is not the enduring and unchanging name.","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 1","te":["trascendencia","conocimiento"]},{"i":"lao-tse-002","a":"lao-tse","t":"Todos en el mundo conocen la belleza de lo bello, y al hacerlo ya tienen la idea de lo feo.","o":"All in the world know the beauty of the beautiful, and in doing this they have (the idea of) what ugliness is","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 2","te":["conocimiento","existencia"]},{"i":"lao-tse-003","a":"lao-tse","t":"Deberíamos limar nuestras aristas y desenredar las complicaciones de las cosas.","o":"We should blunt our sharp points, and unravel the complications of things","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 4","te":["aceptacion","vinculos"]},{"i":"lao-tse-004","a":"lao-tse","t":"Por eso el sabio se pone en último lugar, y sin embargo se encuentra en el primero.","o":"Therefore the sage puts his own person last, and yet it is found in the foremost place","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 7","te":["poder","autenticidad"]},{"i":"lao-tse-005","a":"lao-tse","t":"La excelencia más alta es como la del agua.","o":"The highest excellence is like (that of) water.","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 8","te":["naturaleza","aceptacion"]},{"i":"lao-tse-006","a":"lao-tse","t":"La excelencia del agua está en que beneficia a todas las cosas y ocupa, sin disputar, el lugar bajo que todos desprecian.","o":"The excellence of water appears in its benefiting all things, and in its occupying, without striving (to the contrary), the low place which all men dislike.","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 8","te":["naturaleza","compasion"]},{"i":"lao-tse-007","a":"lao-tse","t":"La excelencia de la mente está en su quietud profunda.","o":"that of the mind is in abysmal stillness","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 8","te":["silencio","conciencia"]},{"i":"lao-tse-008","a":"lao-tse","t":"Es mejor dejar una vasija sin llenar que intentar llevarla cuando está colmada.","o":"It is better to leave a vessel unfilled, than to attempt to carry it when it is full.","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 9","te":["deseo","aceptacion"]},{"i":"lao-tse-009","a":"lao-tse","t":"Cuando la obra está hecha y el nombre empieza a destacarse, retirarse a la sombra es el camino del cielo.","o":"When the work is done, and one's name is becoming distinguished, to withdraw into obscurity is the way of Heaven.","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 9","te":["trabajo","poder"]},{"i":"lao-tse-010","a":"lao-tse","t":"Los treinta rayos se unen en un solo cubo; pero del espacio vacío depende la utilidad de la rueda.","o":"The thirty spokes unite in the one nave; but it is on the empty space (for the axle), that the use of the wheel depends.","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 10","te":["silencio","existencia"]},{"i":"lao-tse-011","a":"lao-tse","t":"Cuando las plantas despliegan su crecimiento exuberante, vemos a cada una volver a su raíz.","o":"When things (in the vegetable world) have displayed their luxuriant growth, we see each of them return to its root.","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 16","te":["naturaleza","cambio"]},{"i":"lao-tse-012","a":"lao-tse","t":"Este volver a la raíz es lo que llamamos quietud.","o":"This returning to their root is what we call the state of stillness","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 16","te":["silencio","presencia"]},{"i":"lao-tse-013","a":"lao-tse","t":"Lo parcial se vuelve completo; lo torcido, recto; lo vacío, lleno; lo gastado, nuevo.","o":"The partial becomes complete; the crooked, straight; the empty, full; the worn out, new.","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 22","te":["cambio","esperanza"]},{"i":"lao-tse-014","a":"lao-tse","t":"No se exhibe, y por eso brilla.","o":"He is free from self-display, and therefore he shines","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 22","te":["autenticidad","autoestima"]},{"i":"lao-tse-015","a":"lao-tse","t":"Un viento violento no dura toda la mañana; un aguacero repentino no dura todo el día.","o":"A violent wind does not last for a whole morning; a sudden rain does not last for the whole day.","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 23","te":["cambio","regulacion-emocional","naturaleza"]},{"i":"lao-tse-016","a":"lao-tse","t":"Quien se pone en puntas de pie no está firme; quien estira las piernas no camina con soltura.","o":"He who stands on his tiptoes does not stand firm; he who stretches his legs does not walk (easily).","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 23","te":["autenticidad","aceptacion"]},{"i":"lao-tse-017","a":"lao-tse","t":"La gravedad es la raíz de la ligereza; la quietud, la que gobierna el movimiento.","o":"Gravity is the root of lightness; stillness, the ruler of movement.","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 26","te":["silencio","presencia"]},{"i":"lao-tse-018","a":"lao-tse","t":"El buen viajero no deja huellas de sus ruedas ni de sus pasos.","o":"The skilful traveller leaves no traces of his wheels or footsteps","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 27","te":["presencia","naturaleza"]},{"i":"lao-tse-019","a":"lao-tse","t":"Quien conoce a los demás es perspicaz; quien se conoce a sí mismo es sabio. Quien vence a otros es fuerte; quien se vence a sí mismo es poderoso.","o":"He who knows other men is discerning; he who knows himself is intelligent. He who overcomes others is strong; he who overcomes himself is mighty.","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 33","te":["autoconocimiento","poder"]},{"i":"lao-tse-020","a":"lao-tse","t":"Quien está conforme con lo que tiene es rico.","o":"He who is satisfied with his lot is rich","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 33","te":["felicidad","deseo","aceptacion"]},{"i":"lao-tse-021","a":"lao-tse","t":"Lo blando vence a lo duro; lo débil, a lo fuerte.","o":"The soft overcomes the hard; and the weak the strong.","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 36","te":["resiliencia","naturaleza"]},{"i":"lao-tse-022","a":"lao-tse","t":"El movimiento del Tao procede por contrarios.","o":"The movement of the Tao By contraries proceeds","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 40","te":["cambio","trascendencia"]},{"i":"lao-tse-023","a":"lao-tse","t":"Lo más blando del mundo choca contra lo más duro y lo vence.","o":"The softest thing in the world dashes against and overcomes the hardest","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 43","te":["resiliencia"]},{"i":"lao-tse-024","a":"lao-tse","t":"Quien está contento no teme la vergüenza. Quien sabe detenerse no incurre en culpa.","o":"Who is content Needs fear no shame. Who knows to stop Incurs no blame.","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 44","te":["aceptacion","deseo"]},{"i":"lao-tse-025","a":"lao-tse","t":"No hay culpa mayor que consentir la ambición, ni calamidad mayor que no estar conforme con lo que uno tiene, ni falta mayor que el deseo de obtener.","o":"There is no guilt greater than to sanction ambition; no calamity greater than to be discontented with one's lot; no fault greater than the wish to be getting.","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 46","te":["deseo","felicidad"]},{"i":"lao-tse-026","a":"lao-tse","t":"Por eso la suficiencia del contento es una suficiencia duradera e inmutable.","o":"Therefore the sufficiency of contentment is an enduring and unchanging sufficiency.","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 46","te":["felicidad","aceptacion"]},{"i":"lao-tse-027","a":"lao-tse","t":"Cuanto más lejos va uno, fuera de sí, menos sabe.","o":"The farther that one goes out (from himself), the less he knows.","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 47","te":["autoconocimiento","conocimiento"]},{"i":"lao-tse-028","a":"lao-tse","t":"Quien se dedica al estudio busca aumentar cada día su saber; quien se dedica al Tao busca disminuir cada día su hacer.","o":"He who devotes himself to learning (seeks) from day to day to increase (his knowledge); he who devotes himself to the Tao (seeks) from day to day to diminish (his doing).","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 48","te":["conocimiento","trascendencia"]},{"i":"lao-tse-029","a":"lao-tse","t":"Con quienes son buenos conmigo soy bueno; con quienes no lo son, también soy bueno: y así todos llegan a ser buenos.","o":"To those who are good (to me), I am good; and to those who are not good (to me), I am also good;--and thus (all) get to be good.","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 49","te":["compasion","vinculos"]},{"i":"lao-tse-030","a":"lao-tse","t":"Quien conoce el Tao no se preocupa por hablar de él; quien siempre está dispuesto a hablar de él no lo conoce.","o":"He who knows (the Tao) does not (care to) speak (about it); he who is (ever ready to) speak about it does not know it.","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 56","te":["silencio","conocimiento"]},{"i":"lao-tse-031","a":"lao-tse","t":"¡La desdicha! A su lado se encuentra la dicha. ¡La dicha! Debajo acecha la desdicha. ¿Quién sabe en qué terminará cada una?","o":"Misery!--happiness is to be found by its side! Happiness!--misery lurks beneath it! Who knows what either will come to in the end?","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 58","te":["felicidad","sufrimiento","incertidumbre"]},{"i":"lao-tse-032","a":"lao-tse","t":"No hay nada como la moderación.","o":"there is nothing like moderation","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 59","te":["habitos"]},{"i":"lao-tse-033","a":"lao-tse","t":"Gobernar un gran Estado es como cocinar pescados pequeños.","o":"Governing a great state is like cooking small fish.","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 60","te":["poder","sociedad"]},{"i":"lao-tse-034","a":"lao-tse","t":"Y responder a la ofensa con bondad.","o":"and to recompense injury with kindness","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 63","te":["compasion","ira"]},{"i":"lao-tse-035","a":"lao-tse","t":"El árbol que llena los brazos nació de un brote diminuto; la torre de nueve pisos se levantó de un montón de tierra; el viaje de mil li empezó con un solo paso.","o":"The tree which fills the arms grew from the tiniest sprout; the tower of nine storeys rose from a (small) heap of earth; the journey of a thousand li commenced with a single step.","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 64","te":["cambio","habitos","esperanza"]},{"i":"lao-tse-036","a":"lao-tse","t":"Hay que actuar antes de que algo aparezca; hay que poner orden antes de que empiece el desorden.","o":"Action should be taken before a thing has made its appearance; order should be secured before disorder has begun.","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 64","te":["responsabilidad"]},{"i":"lao-tse-037","a":"lao-tse","t":"Los ríos y los mares reciben el tributo de todos los arroyos del valle porque saben estar más abajo que ellos.","o":"That whereby the rivers and seas are able to receive the homage and tribute of all the valley streams, is their skill in being lower than they","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 66","te":["poder","naturaleza"]},{"i":"lao-tse-038","a":"lao-tse","t":"Tengo tres tesoros que aprecio y conservo: el primero es la bondad; el segundo, la sobriedad; el tercero, no querer ponerme por delante de los demás.","o":"But I have three precious things which I prize and hold fast. The first is gentleness; the second is economy; and the third is shrinking from taking precedence of others.","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 67","te":["compasion","autenticidad"]},{"i":"lao-tse-039","a":"lao-tse","t":"Con esa bondad puedo ser valiente.","o":"With that gentleness I can be bold","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 67","te":["compasion","miedo"]},{"i":"lao-tse-040","a":"lao-tse","t":"Saber y pensar que no sabemos es lo más alto; no saber y creer que sabemos es una enfermedad.","o":"To know and yet (think) we do not know is the highest (attainment); not to know (and yet think) we do know is a disease.","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 71","te":["conocimiento","autoconocimiento"]},{"i":"lao-tse-041","a":"lao-tse","t":"Al nacer, el ser humano es flexible y débil; al morir, rígido y duro.","o":"Man at his birth is supple and weak; at his death, firm and strong.","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 76","te":["muerte","cuerpo"]},{"i":"lao-tse-042","a":"lao-tse","t":"Así, la rigidez y la dureza acompañan a la muerte; la flexibilidad y la suavidad acompañan a la vida.","o":"Thus it is that firmness and strength are the concomitants of death; softness and weakness, the concomitants of life.","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 76","te":["resiliencia","muerte"]},{"i":"lao-tse-043","a":"lao-tse","t":"No hay nada en el mundo más blando y débil que el agua, y sin embargo, para vencer lo firme y lo fuerte, nada la supera.","o":"There is nothing in the world more soft and weak than water, and yet for attacking things that are firm and strong there is nothing that can take precedence of it","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 78","te":["resiliencia","naturaleza"]},{"i":"lao-tse-044","a":"lao-tse","t":"Todos en el mundo saben que lo blando vence a lo duro y lo débil a lo fuerte, pero nadie es capaz de llevarlo a la práctica.","o":"Every one in the world knows that the soft overcomes the hard, and the weak the strong, but no one is able to carry it out in practice.","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 78","te":["conocimiento","habitos"]},{"i":"lao-tse-045","a":"lao-tse","t":"Cuando dos partes se reconcilian después de una gran enemistad, siempre queda algún rencor.","o":"When a reconciliation is effected (between two parties) after a great animosity, there is sure to be a grudge remaining","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 79","te":["vinculos","ira"]},{"i":"lao-tse-046","a":"lao-tse","t":"Las palabras sinceras no son bellas; las palabras bellas no son sinceras.","o":"Sincere words are not fine; fine words are not sincere.","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 81","te":["autenticidad","comunicacion"]},{"i":"lao-tse-047","a":"lao-tse","t":"Cuanto más da a los demás, más posee.","o":"The more that he expends for others, the more does he possess of his own","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 81","te":["compasion","vinculos"]},{"i":"lao-tse-048","a":"lao-tse","t":"Mis palabras son muy fáciles de entender y muy fáciles de practicar; pero nadie en el mundo es capaz de entenderlas y practicarlas.","o":"My words are very easy to know, and very easy to practise; but there is no one in the world who is able to know and able to practise them.","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 70","te":["conocimiento","habitos"]},{"i":"lao-tse-049","a":"lao-tse","t":"La pureza y la quietud dan la norma justa a todo lo que existe bajo el cielo.","o":"Purity and stillness give the correct law to all under heaven.","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 45","te":["silencio"]},{"i":"lao-tse-050","a":"lao-tse","t":"Quien presta atención indivisa a la respiración y la vuelve flexible al máximo puede ser como un niño pequeño.","o":"When one gives undivided attention to the (vital) breath, and brings it to the utmost degree of pliancy, he can become as a (tender) babe.","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 10","te":["cuerpo","atencion","presencia"]},{"i":"lao-tse-051","a":"lao-tse","t":"Quien tiene en abundancia las virtudes del Tao es como un niño recién nacido.","o":"He who has in himself abundantly the attributes (of the Tao) is like an infant.","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 55","te":["infancia","trascendencia"]},{"i":"lao-tse-052","a":"lao-tse","t":"El favor y la desgracia parecen igualmente temibles.","o":"Favour and disgrace would seem equally to be feared","l":"en","ob":"Tao Te Ching","an":"s. IV a. C.","u":"Capítulo 13","te":["miedo","autoestima"]}],"ruta":"/recursos/voces-que-nos-habitan/","temasRuta":"/recursos/voces-que-nos-habitan/temas/","escuelas":[["fil","Filosofía"],["ini","Los comienzos"],["ori","Tradiciones orientales"],["pa","Psicoanálisis"]],"epocas":[["clasico","Clásicos"],["moderno","Modernos"]]};
